-- ================================================================================================
-- MODULE M12: DATA QUALITY & VALIDATION FRAMEWORK
-- PostgreSQL Database Schema Script
-- ================================================================================================
-- Description:
-- This script creates the database schema for Module M12, which serves as the immune system
-- of the PARI infrastructure. It enforces structural, semantic, and regulatory standards
-- on all ingested data to ensure a Zero-Defect state.
--
-- Generated By: Advanced PostgreSQL DBA (AI Agent)
-- Date: 2023-10-27
-- ================================================================================================

-- ================================================================================================
-- 1. SCHEMA CREATION
-- ================================================================================================

CREATE SCHEMA IF NOT EXISTS core AUTHORIZATION CURRENT_USER;
COMMENT ON SCHEMA core IS 'Core schema for Module M12: Data Quality & Validation Framework';

-- ================================================================================================
-- 2. EXTENSIONS
-- ================================================================================================

-- UUID Generation
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
COMMENT ON EXTENSION "uuid-ossp" IS 'Provides functions to generate universally unique identifiers (UUIDs)';

-- Cryptographic functions
CREATE EXTENSION IF NOT EXISTS pgcrypto;
COMMENT ON EXTENSION pgcrypto IS 'Provides cryptographic functions for hashing, encryption, and validation';

-- Trigram matching for fuzzy text search
CREATE EXTENSION IF NOT EXISTS pg_trgm;
COMMENT ON EXTENSION pg_trgm IS 'Provides functions and operator classes for determining similarity of text based on trigram matching';

-- GIN index support for B-Tree types (indexing scalar types in JSONB)
CREATE EXTENSION IF NOT EXISTS btree_gin;
COMMENT ON EXTENSION btree_gin IS 'Provides GIN index operator classes that implement B-tree equivalent behavior';

-- ================================================================================================
-- 2a. LIST OF DATABASE OBJECTS
-- ================================================================================================
-- Scanning the provided matrix, the following database object types are identified:
--
-- 1. TABLES (T001 - T100): Stores configuration, reference data, logs, and validation rules.
-- 2. VIEWS (V001 - V005): Pre-computed aggregations and security views.
-- 3. ENUMS (E001 - E010): Fixed sets of values for currency, country, error severity, etc.
-- 4. STORED PROCEDURES (P001 - P072): Logic for specific validation algorithms (IBAN, Luhn, etc.).
-- 5. JUNCTION TABLES (J001 - J015): Many-to-many relationships (e.g., Rules to Error Codes).
-- ================================================================================================

-- ================================================================================================
-- 3. ENUMS
-- ================================================================================================

------------------------------------------------------------------------------------------------
-- Enum: E001 - enum_currency_code
-- Description: Defines valid ISO 4217 currency codes active within the PARI system.
-- Business Case: Ensures strict adherence to international currency standards, preventing
-- calculation errors and ambiguity in multi-currency transaction processing.
------------------------------------------------------------------------------------------------
CREATE TYPE core.enum_currency_code AS ENUM (
    'USD', 'EUR', 'GBP', 'CHF', 'JPY', 'CAD', 'AUD', 'CNY', 'INR', 'MXN', 'BRL',
    'PLN', 'SEK', 'NOK', 'DKK', 'ZAR', 'SGD', 'HKD', 'KRW', 'TRY', 'RUB', 'KZT'
);
COMMENT ON TYPE core.enum_currency_code IS 'Enumeration of supported ISO 4217 currency codes';

------------------------------------------------------------------------------------------------
-- Enum: E002 - enum_country_code
-- Description: Defines valid ISO 3166-1 alpha-2 country codes.
-- Business Case: Enables jurisdiction-specific logic, including tax calculation,
-- formatting rules, and regulatory compliance checks.
------------------------------------------------------------------------------------------------
CREATE TYPE core.enum_country_code AS ENUM (
    'US', 'GB', 'FR', 'DE', 'IT', 'ES', 'CH', 'AT', 'BE', 'NL', 'PL', 'SE', 'NO', 'DK',
    'FI', 'GR', 'PT', 'IE', 'LU', 'CA', 'MX', 'BR', 'AR', 'CL', 'CO', 'PE', 'AU', 'NZ',
    'JP', 'CN', 'IN', 'SG', 'HK', 'KR', 'MY', 'ID', 'TH', 'VN', 'PH', 'ZA', 'NG', 'KE',
    'EG', 'SA', 'AE', 'QA', 'KW', 'IL', 'TR', 'RU', 'KZ', 'UA', 'CZ', 'HU', 'RO', 'BG'
);
COMMENT ON TYPE core.enum_country_code IS 'Enumeration of supported ISO 3166-1 alpha-2 country codes';

------------------------------------------------------------------------------------------------
-- Enum: E003 - enum_language_code
-- Description: Defines valid ISO 639-1 language codes for localization.
-- Business Case: Facilitates localization of error messages and UI elements, ensuring
-- users receive feedback in a language they understand, reducing support friction.
------------------------------------------------------------------------------------------------
CREATE TYPE core.enum_language_code AS ENUM (
    'en', 'es', 'fr', 'de', 'it', 'pt', 'nl', 'pl', 'sv', 'no', 'da', 'fi', 'ru', 'zh',
    'ja', 'ko', 'ar', 'hi'
);
COMMENT ON TYPE core.enum_language_code IS 'Enumeration of supported ISO 639-1 language codes';

------------------------------------------------------------------------------------------------
-- Enum: E004 - enum_error_severity
-- Description: Defines the severity levels of validation errors.
-- Business Case: Prioritizes system responses. CRITICAL errors halt processing immediately,
-- while LOW errors might be logged for analysis without stopping the flow, optimizing throughput.
------------------------------------------------------------------------------------------------
CREATE TYPE core.enum_error_severity AS ENUM ('CRITICAL', 'HIGH', 'MEDIUM', 'LOW');
COMMENT ON TYPE core.enum_error_severity IS 'Severity classification for validation errors (CRITICAL, HIGH, MEDIUM, LOW)';

------------------------------------------------------------------------------------------------
-- Enum: E005 - enum_check_constraint_type
-- Description: Types of database constraints used in validation logic.
-- Business Case: Categorizes enforcement mechanisms for metadata reporting and auditing
-- of data integrity strategies.
------------------------------------------------------------------------------------------------
CREATE TYPE core.enum_check_constraint_type AS ENUM ('CHECK', 'NOT NULL', 'UNIQUE', 'EXCLUDE', 'FOREIGN KEY');
COMMENT ON TYPE core.enum_check_constraint_type IS 'Types of database constraints enforced by the framework';

------------------------------------------------------------------------------------------------
-- Enum: E006 - enum_data_type
-- Description: Abstract data types used in schema definitions.
-- Business Case: Allows mapping of platform-independent types to specific PostgreSQL types,
-- aiding in cross-database compatibility and schema generation.
------------------------------------------------------------------------------------------------
CREATE TYPE core.enum_data_type AS ENUM ('STRING', 'INTEGER', 'DECIMAL', 'BOOLEAN', 'JSON', 'DATE', 'TIMESTAMP', 'UUID', 'BYTEA');
COMMENT ON TYPE core.enum_data_type IS 'Abstract data type definitions for schema mapping';

------------------------------------------------------------------------------------------------
-- Enum: E007 - enum_mcc_group
-- Description: Groups Merchant Category Codes (MCC) into broader business sectors.
-- Business Case: Enables high-level reporting and fraud rule application based on industry
-- segments rather than individual 4-digit codes.
------------------------------------------------------------------------------------------------
CREATE TYPE core.enum_mcc_group AS ENUM (
    'RETAIL', 'RESTAURANT', 'GROCERY', 'SERVICE', 'UTILITIES', 'TRAVEL', 'AUTOMOTIVE',
    'HEALTHCARE', 'EDUCATION', 'PROFESSIONAL', 'GOVERNMENT'
);
COMMENT ON TYPE core.enum_mcc_group IS 'High-level categorization of Merchant Category Codes (ISO 18245)';

------------------------------------------------------------------------------------------------
-- Enum: E008 - enum_card_brand
-- Description: Supported credit and debit card brands.
-- Business Case: Identifies card networks to apply specific validation rules (Luhn variations)
-- and routing logic.
------------------------------------------------------------------------------------------------
CREATE TYPE core.enum_card_brand AS ENUM (
    'VISA', 'MASTERCARD', 'AMEX', 'DISCOVER', 'JCB', 'UNIONPAY', 'MAESTRO', 'ELO', 'HIPER'
);
COMMENT ON TYPE core.enum_card_brand IS 'Supported card brands for processing';

------------------------------------------------------------------------------------------------
-- Enum: E009 - enum_kyc_level
-- Description: Levels of Know Your Customer verification.
-- Business Case: Controls feature access and transaction limits based on the verification
-- status of the entity, ensuring regulatory compliance (AML/CTF).
------------------------------------------------------------------------------------------------
CREATE TYPE core.enum_kyc_level AS ENUM ('ANONYMOUS', 'PSEUDONYMOUS', 'LIGHT', 'STANDARD', 'FULL');
COMMENT ON TYPE core.enum_kyc_level IS 'Levels of identity verification (KYC) compliance';

------------------------------------------------------------------------------------------------
-- Enum: E010 - enum_pseudonymization_type
-- Description: Algorithms used for hashing/encrypting PII.
-- Business Case: Tracks which method was used to obfuscate data to support data subject
-- access requests (GDPR) and reversible operations if legally permitted.
------------------------------------------------------------------------------------------------
CREATE TYPE core.enum_pseudonymization_type AS ENUM ('SHA256', 'BLAKE2B', 'ARGON2', 'AES256_GCM');
COMMENT ON TYPE core.enum_pseudonymization_type IS 'Hashing or encryption algorithms used for PII protection';

-- ================================================================================================
-- 4. DDL STATEMENTS (TABLES T001 - T050)
-- ================================================================================================

-- Trigger Function for Updated At
CREATE OR REPLACE FUNCTION core.trigger_update_updated_at()
RETURNS TRIGGER AS $$ BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
 $$ LANGUAGE plpgsql;
COMMENT ON FUNCTION core.trigger_update_updated_at() IS 'Automatically updates the updated_at timestamp';

------------------------------------------------------------------------------------------------
-- Table: T001 - validation_rules
-- Description: Stores active validation rules for fields throughout the PARI system.
-- Business Case: This table acts as the central registry for the "Zero-Defect" ingestion strategy.
-- By externalizing validation logic into database configuration, M12 allows operators to deploy
-- new regulatory checks (e.g., a new VAT ID format) without application code changes or
-- downtime. It supports the CMMI Level 5 goal of quantitatively managed process quality by
-- enabling versioning and auditing of every rule change. This decoupling ensures that the
-- validation framework remains agile and responsive to the evolving financial landscape.
-- KPIs: Rule deployment time, Rule execution latency, Active rule count.
-- Feature Reference: F001-F300
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.validation_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    rule_name VARCHAR(255) NOT NULL,
    field_path TEXT NOT NULL, -- JSONPath or dot-notation (e.g., "payment.iban")
    rule_type VARCHAR(50) NOT NULL, -- e.g., 'REGEX', 'RANGE', 'CHECKSUM', 'JSON_SCHEMA'

    -- Configuration
    params JSONB NOT NULL, -- Flexible storage for rule parameters (regex pattern, min/max, etc.)
    error_code_override VARCHAR(50), -- Optional specific error code for this rule

    -- State Management
    is_active BOOLEAN NOT NULL DEFAULT true,
    priority INTEGER NOT NULL DEFAULT 0, -- Higher priority rules run first

    -- Classification
    validation_stage VARCHAR(50) NOT NULL CHECK (validation_stage IN ('INGESTION', 'PERSISTENCE', 'ENRICHMENT')),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT validation_rules_unique_active UNIQUE (field_path, rule_type, is_active) WHERE is_active = true
);

COMMENT ON TABLE core.validation_rules IS 'Central registry of active validation rules for data hygiene';
COMMENT ON COLUMN core.validation_rules.params IS 'JSONB object containing rule-specific parameters (e.g., pattern, min, max)';

------------------------------------------------------------------------------------------------
-- Table: T002 - validation_rule_history
-- Description: Audit history of all changes made to validation rules.
-- Business Case: In a regulated financial environment, every change to data acceptance logic
-- must be attributable. This table provides the forensic trail required for audits, enabling
-- system architects to trace exactly who changed a rule, when, and what the previous parameters
-- were. It supports rollback capabilities and compliance with ISO 27001 change management
-- controls. By maintaining this history, the platform ensures that the integrity of the
-- validation framework is verifiable at all times.
-- KPIs: Audit trail completeness, Mean time to restore (MTTR) for rule errors.
-- Feature Reference: F001-F300
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.validation_rule_history (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- References
    rule_id UUID NOT NULL,

    -- Change Details
    changed_by UUID NOT NULL,
    changed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    change_type VARCHAR(20) NOT NULL CHECK (change_type IN ('CREATE', 'UPDATE', 'DELETE', 'ACTIVATE', 'DEACTIVATE')),

    -- Data Snapshots
    old_params JSONB, -- Previous state of params
    new_params JSONB, -- New state of params
    old_is_active BOOLEAN,
    new_is_active BOOLEAN,

    -- Reasoning
    change_reason TEXT
);

COMMENT ON TABLE core.validation_rule_history IS 'Immutable audit log of validation rule modifications';

------------------------------------------------------------------------------------------------
-- Table: T003 - iso_4217_currencies
-- Description: Reference table for ISO 4217 currency codes and metadata.
-- Business Case: Financial accuracy depends on precise currency handling. This table provides
-- the canonical source of truth for valid currencies, their numeric codes, and decimal precision
-- (minor units). It prevents the acceptance of invalid or deprecated currencies (e.g., obsolete
-- European currencies) and ensures that calculations involving money use the correct scale,
-- preventing rounding errors that could lead to financial discrepancies or tax reporting issues.
-- KPIs: Reference data accuracy, ISO standard alignment.
-- Feature Reference: F002, F017
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.iso_4217_currencies (
    -- Primary Key
    alphabetic_code CHAR(3) PRIMARY KEY, -- e.g., USD, EUR

    -- Attributes
    numeric_code CHAR(3) UNIQUE NOT NULL, -- e.g., 840, 978
    currency_name VARCHAR(100) NOT NULL,
    minor_unit INTEGER NOT NULL CHECK (minor_unit >= 0 AND minor_unit <= 3), -- Exponents, e.g., 2 for cents
    currency_symbol VARCHAR(10),

    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    is_crypto BOOLEAN NOT NULL DEFAULT false,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.iso_4217_currencies IS 'Reference data for ISO 4217 currency standards';

------------------------------------------------------------------------------------------------
-- Table: T004 - iso_3166_countries
-- Description: Reference table for ISO 3166 country codes and regional data.
-- Business Case: Jurisdiction determination is critical for tax (VAT/GST), compliance (sanctions),
-- and formatting (addresses/phone numbers). This table standardizes country identification,
-- ensuring that downstream modules like Tax Engine (M22) and Fraud Detection (M03) operate on
-- consistent geopolitical data. It also supports grouping by region for analytical reporting.
-- KPIs: Reference data coverage.
-- Feature Reference: F009, F014
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.iso_3166_countries (
    -- Primary Key
    alpha_2_code CHAR(2) PRIMARY KEY, -- e.g., US, FR

    -- Attributes
    alpha_3_code CHAR(3) UNIQUE NOT NULL,
    numeric_code CHAR(3) UNIQUE NOT NULL,
    name VARCHAR(100) NOT NULL,
    region VARCHAR(50), -- e.g., Europe, Americas
    sub_region VARCHAR(50),
    continent VARCHAR(50),

    -- Dialing Codes
    calling_code VARCHAR(10),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.iso_3166_countries IS 'Reference data for ISO 3166 country standards';

------------------------------------------------------------------------------------------------
-- Table: T005 - validation_errors_log
-- Description: High-throughput log of all validation failures.
-- Business Case: This table is the telemetry sensor of the M12 immune system. It captures every
-- rejected transaction, the specific rule that failed, and the context. This data is fed into
-- M08 (Operational Analytics) to identify systemic integration issues with specific merchants
-- or banks. By analyzing the payload_hash, the system can detect mass attacks or malfunctioning
-- clients. The existence of this log facilitates the "Corrective Feedback Loop" KPI by alerting
-- developers to new error patterns.
-- KPIs: Data rejection rate, Error distribution by code, Log ingestion latency.
-- Feature Reference: F001-F300
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.validation_errors_log (
    -- Primary Key
    id BIGSERIAL PRIMARY KEY,

    -- Identification
    error_code VARCHAR(50) NOT NULL,
    field_path TEXT, -- Which field failed
    message TEXT NOT NULL,

    -- Source Context
    source_ip INET,
    user_agent TEXT,
    request_id UUID, -- Link to distributed trace
    payload_hash CHAR(64), -- SHA-256 of payload for deduplication/anonymization

    -- Severity
    severity core.enum_error_severity NOT NULL DEFAULT 'MEDIUM',

    -- Timing
    timestamp TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,

    -- Partitioning Key (Year/Month) - Recommended for partitioning in prod
    partition_date DATE GENERATED ALWAYS AS (date(timestamp)) STORED
);

COMMENT ON TABLE core.validation_errors_log IS 'Log of all validation failures for analytics and debugging';
-- Create Indexes for T005
CREATE INDEX idx_validation_errors_log_ts ON core.validation_errors_log(timestamp DESC);
CREATE INDEX idx_validation_errors_log_code ON core.validation_errors_log(error_code);
CREATE INDEX idx_validation_errors_log_hash ON core.validation_errors_log(payload_hash);

------------------------------------------------------------------------------------------------
-- Table: T006 - error_codes_registry
-- Description: Master registry of standardized error codes mapped to human-readable messages.
-- Business Case: To provide specific, actionable feedback to API consumers (Merchants/Devs),
-- error codes must be standardized rather than generic. This registry maps technical codes
-- (e.g., 'VAL_IBAN_CHECKSUM_FAIL') to localized templates defined in E001-E003 language enums.
-- This ensures that a failure in Italy returns an Italian message, while the underlying code
-- remains consistent for metrics. It drives the "User Friction" KPI by improving error clarity.
-- KPIs: Error resolution time (developer), Translation coverage.
-- Feature Reference: F001-F300
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.error_codes_registry (
    -- Primary Key
    code VARCHAR(50) PRIMARY KEY,

    -- Metadata
    http_status INTEGER NOT NULL CHECK (http_status BETWEEN 200 AND 599),
    title VARCHAR(100) NOT NULL,
    message_template TEXT NOT NULL, -- Uses placeholders like {field}, {value}
    severity core.enum_error_severity NOT NULL DEFAULT 'HIGH',

    -- Resolution
    developer_help_url TEXT,
    suggested_action TEXT,

    -- Lifecycle
    is_deprecated BOOLEAN DEFAULT false,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.error_codes_registry is 'Registry of standardized error definitions (RFC 7807)';

------------------------------------------------------------------------------------------------
-- Table: T007 - json_schemas_registry
-- Description: Stores registered JSON-LD and JSON schemas used for complex payload validation.
-- Business Case: Modern financial transactions (ISO 20022 JSON, Taler contracts) are complex
-- nested structures. Simple regex is insufficient. This table stores JSON Schema Draft 7/2020
-- definitions that are loaded by F004. It allows for versioning of schemas, ensuring that if a
-- standard changes (e.g., adding a mandatory field for PSD2), old transactions can still be
-- validated against the old schema while new ones use the new schema.
-- KPIs: Schema validation latency, Schema versioning accuracy.
-- Feature Reference: F004, F210, F211
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.json_schemas_registry (
    -- Primary Key
    schema_id VARCHAR(100) NOT NULL,
    version VARCHAR(20) NOT NULL,
    PRIMARY KEY (schema_id, version),

    -- Definition
    schema_json JSONB NOT NULL, -- The actual JSON Schema object
    description TEXT,

    -- Metadata
    specification_version VARCHAR(20), -- e.g., 'draft-07', '2020-12'

    -- State
    is_active BOOLEAN NOT NULL DEFAULT true,
    deprecation_date TIMESTAMP WITH TIME ZONE,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.json_schemas_registry IS 'Registry for JSON-LD and JSON Schema definitions';

------------------------------------------------------------------------------------------------
-- Table: T008 - regex_patterns
-- Description: Stores reusable regular expressions to avoid hardcoding.
-- Business Case: Regex patterns are often complex and prone to ReDoS (Regular Expression Denial
-- of Service). Storing them centrally allows for security review (F059) before deployment and
-- reuse across multiple validation rules. It centralizes the maintenance of patterns like
-- email, IBAN, and VAT IDs, ensuring that a bug fix in one pattern propagates to all
-- validations using it instantly.
-- KPIs: Pattern reusability, ReDoS prevention success.
-- Feature Reference: F002, F005, F059
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.regex_patterns (
    -- Primary Key
    pattern_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    name VARCHAR(100) NOT NULL UNIQUE, -- e.g., 'IBAN_GENERIC', 'EMAIL_RFC5322'
    pattern TEXT NOT NULL, -- The actual regex

    -- Description & Safety
    description TEXT,
    is_safe_for_user_input BOOLEAN NOT NULL DEFAULT false, -- Has it passed ReDoS analysis?
    max_match_length INTEGER, -- Safety limit

    -- References (Optional mapping to specific features)
    feature_reference VARCHAR(50),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.regex_patterns IS 'Central repository of reusable regular expressions';

------------------------------------------------------------------------------------------------
-- Table: T009 - check_constraints_audit
-- Description: Tracks database-level CHECK constraint definitions.
-- Business Case: While T001 tracks application-level rules, database constraints are the final
-- line of defense. This table acts as a catalog of constraints applied to tables, aiding in
-- documentation and automated schema generation tools. It helps ensure that every critical
-- data column (amounts, dates) has a corresponding database guardrail, satisfying the "Schema
-- Coverage" KPI target of 100%.
-- KPIs: Constraint coverage percentage.
-- Feature Reference: F003, F018
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.check_constraints_audit (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identity
    table_name VARCHAR(255) NOT NULL,
    constraint_name VARCHAR(255) NOT NULL,

    -- Definition
    definition TEXT NOT NULL, -- The SQL CHECK clause
    constraint_type core.enum_check_constraint_type NOT NULL,

    -- State
    is_active BOOLEAN NOT NULL DEFAULT true,

    -- Context
    applies_to_columns TEXT[], -- List of columns affected

    -- Unique Constraint
    CONSTRAINT check_constraints_audit_unique UNIQUE (table_name, constraint_name)
);

COMMENT ON TABLE core.check_constraints_audit IS 'Audit and catalog of database-level constraints';

------------------------------------------------------------------------------------------------
-- Table: T010 - data_type_mappings
-- Description: Maps abstract data types to physical database types.
-- Business Case: Facilitates database-agnostic schema design. When the PARI platform is
-- deployed to different clients (e.g., one using PostgreSQL, another using a cloud-specific
-- fork), this mapping ensures that the abstract definition (DECIMAL(15,2)) is correctly
-- translated to the optimal storage format (NUMERIC). It supports the portability of the
-- validation framework.
-- KPIs: Schema migration success rate.
-- Feature Reference: F001
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.data_type_mappings (
    -- Primary Key
    abstract_type core.enum_data_type PRIMARY KEY,

    -- Mapping
    db_type VARCHAR(50) NOT NULL, -- Postgres type: NUMERIC, VARCHAR, etc.
    max_length INTEGER, -- For VARCHAR types

    -- Validation Rules
    default_value TEXT, -- Representation of default
    is_nullable BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.data_type_mappings IS 'Mapping of abstract types to physical SQL types';

------------------------------------------------------------------------------------------------
-- Table: T011 - email_blacklist
-- Description: Domains blocked for registration or transactions (disposable, spam).
-- Business Case: Prevents fraud and low-quality data ingestion by blocking known disposable
-- email providers (e.g., mailinator.com) or domains associated with bot networks. This
-- reduces the "Garbage In" problem at the source, ensuring that marketing campaigns and user
-- verification processes target real entities, thereby protecting the platform's reputation.
-- KPIs: Fraud reduction rate, Disposable email rejection rate.
-- Feature Reference: F005
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.email_blacklist (
    -- Primary Key
    domain VARCHAR(255) PRIMARY KEY,

    -- Reasoning
    reason VARCHAR(100) NOT NULL, -- e.g., 'DISPOSABLE', 'SPAM_SOURCE', 'BOUNCED'
    source VARCHAR(50), -- Manual entry, automated list import

    -- Lifecycle
    added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    is_active BOOLEAN NOT NULL DEFAULT true
);

COMMENT ON TABLE core.email_blacklist IS 'List of blocked email domains to prevent spam/fraud';
CREATE INDEX idx_email_blacklist_domain ON core.email_blacklist(domain) WHERE is_active = true;

------------------------------------------------------------------------------------------------
-- Table: T012 - phone_whitelist
-- Description: Allowed phone number prefixes or countries for specific operations.
-- Business Case: Restricts operations (like high-value transfers or 2FA delivery) to specific
-- geographic regions or carriers known to be reliable. Conversely, it can be used to block
-- premium-rate numbers used in fraud schemes. This adds a layer of security for operational
-- and SMS delivery costs.
-- KPIs: SMS delivery success rate, Fraud prevention rate.
-- Feature Reference: F010
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.phone_whitelist (
    -- Primary Key
    country_code core.enum_country_code PRIMARY KEY,

    -- Configuration
    is_allowed BOOLEAN NOT NULL DEFAULT true,
    restrictions TEXT[] -- e.g., {'PREMIUM_RATE_BLOCKED', 'LANDLINE_ONLY'}
);

COMMENT ON TABLE core.phone_whitelist IS 'Configuration for allowed phone number origins';

------------------------------------------------------------------------------------------------
-- Table: T013 - iban_registry
-- Description: Valid IBAN lengths, structure, and check digit info per country.
-- Business Case: Validates the structural integrity of IBANs before external payment initiation.
-- While the Modulo-97 check (F006) validates the checksum, this registry ensures the IBAN has
-- the correct length for the claimed country. This prevents malformed payments that would
-- fail downstream, improving transaction success rates.
-- KPIs: Payment routing accuracy.
-- Feature Reference: F006
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.iban_registry (
    -- Primary Key
    country_code CHAR(2) PRIMARY KEY,

    -- Structure
    iban_length INTEGER NOT NULL,
    bban_pattern TEXT NOT NULL, -- e.g., '4!n10!n12!c'
    bank_code_position_start INTEGER,
    bank_code_length INTEGER,

    -- Metadata
    country_name VARCHAR(100)
);

COMMENT ON TABLE core.iban_registry IS 'Reference data for IBAN validation rules per country';

------------------------------------------------------------------------------------------------
-- Table: T014 - swift_bic_registry
-- Description: Reference data for valid BIC codes and bank metadata.
-- Business Case: Enables validation of BIC/SWIFT codes used in international wire transfers.
-- By cross-referencing against this registry, M12 can identify typos in bank codes before
-- the transaction leaves the system, preventing failed transfers and associated fees.
-- KPIs: International transfer success rate.
-- Feature Reference: F042
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.swift_bic_registry (
    -- Primary Key
    bic_code CHAR(11) PRIMARY KEY, -- or 8 chars

    -- Metadata
    bank_name VARCHAR(255) NOT NULL,
    country_code CHAR(2) NOT NULL,
    headquarters_city VARCHAR(100),

    -- Status
    is_active BOOLEAN NOT NULL DEFAULT true,
    last_updated DATE
);

COMMENT ON TABLE core.swift_bic_registry IS 'Registry of valid SWIFT BIC codes for validation';
CREATE INDEX idx_swift_bic_code ON core.swift_bic_registry(bic_code);

------------------------------------------------------------------------------------------------
-- Table: T015 - merchant_category_codes
-- Description: ISO 18245 MCC codes and their descriptions.
-- Business Case: Standardizes the classification of merchants. Correct MCC assignment is
-- vital for interchange fee calculation, fraud risk assessment (e.g., high-risk categories),
-- and tax reporting in specific sectors (e.g., travel vs. retail). This table ensures that
-- only valid MCCs are accepted during merchant onboarding.
-- KPIs: Interchange fee accuracy, Fraud detection precision.
-- Feature Reference: F011
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.merchant_category_codes (
    -- Primary Key
    mcc CHAR(4) PRIMARY KEY, -- Padded numeric

    -- Description
    description TEXT NOT NULL,
    group_id core.enum_mcc_group,
    combined_description TEXT -- e.g., "5411 - Grocery Stores, Supermarkets"
);

COMMENT ON TABLE core.merchant_category_codes IS 'Reference table for ISO 18245 Merchant Category Codes';

------------------------------------------------------------------------------------------------
-- Table: T016 - vat_id_formats
-- Description: Regex and logic for VAT ID validation per country.
-- Business Case: VAT ID formats vary wildly (e.g., UK requires Mod 97, Italy has alphanumeric).
-- This table stores the specific validation logic (regex template and modulus algorithm)
-- required for each country. It ensures that only valid VAT IDs are collected, enabling
-- accurate B2B invoicing and tax reporting within the EU and other jurisdictions.
-- KPIs: Tax reporting accuracy, Invoice rejection rate.
-- Feature Reference: F012
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.vat_id_formats (
    -- Primary Key
    country_code CHAR(2) PRIMARY KEY,

    -- Logic
    regex_template TEXT NOT NULL, -- Basic structure check
    modulus_rule VARCHAR(50), -- 'MOD_97', 'MOD_11', 'MOD_55'
    modulus_weight INTEGER,
    check_digit_position INTEGER,

    -- Metadata
    example_vat_id VARCHAR(50)
);

COMMENT ON TABLE core.vat_id_formats IS 'Validation logic for VAT ID formats by country';

------------------------------------------------------------------------------------------------
-- Table: T017 - banned_usernames
-- Description: List of profane, reserved, or offensive usernames.
-- Business Case: Maintains community standards and prevents impersonation (e.g., banning
-- "admin", "support"). It also filters out offensive language to protect the platform's brand
-- image. Automating this check during registration prevents manual moderation efforts later.
-- KPIs: Moderation queue reduction, Brand safety incidents.
-- Feature Reference: F015
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.banned_usernames (
    -- Primary Key
    username VARCHAR(100) PRIMARY KEY,

    -- Reason
    reason VARCHAR(50) NOT NULL CHECK (reason IN ('PROFANE', 'RESERVED', 'OFFICIAL', 'IP_INFRINGEMENT')),

    -- Lifecycle
    added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    added_by UUID NOT NULL
);

COMMENT ON TABLE core.banned_usernames IS 'List of prohibited usernames for registration';

------------------------------------------------------------------------------------------------
-- Table: T018 - known_sql_injections
-- Description: Signatures of known SQL injection attack strings.
-- Business Case: Provides a signature-based defense layer against SQLi attacks. While
-- parameterized queries (ORM) are the primary defense, this table validates raw text inputs
-- (like search queries or filter parameters) for common attack patterns (e.g., ' OR 1=1, --,
-- UNION SELECT). It acts as a Web Application Firewall (WAF) component at the data layer.
-- KPIs: SQLi attempts blocked.
-- Feature Reference: F028
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.known_sql_injections (
    -- Primary Key
    signature VARCHAR(255) PRIMARY KEY,

    -- Metadata
    pattern_type VARCHAR(50) NOT NULL, -- e.g., 'TAUTOLOGY', 'UNION', 'COMMENT'
    risk_score INTEGER NOT NULL CHECK (risk_score BETWEEN 1 AND 10)
);

COMMENT ON TABLE core.known_sql_injections IS 'Signature database for SQL injection detection';

------------------------------------------------------------------------------------------------
-- Table: T019 - xss_signatures
-- Description: Signatures of known Cross-Site Scripting (XSS) payloads.
-- Business Case: Prevents malicious script injection through user-generated content fields.
-- If an attacker submits a script tag, it could execute in admin dashboards or other user
-- browsers. This table stores patterns (like <script>, javascript:) to sanitize inputs
-- before storage, fulfilling security compliance requirements.
-- KPIs: XSS exploits prevented.
-- Feature Reference: F029
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.xss_signatures (
    -- Primary Key
    signature VARCHAR(255) PRIMARY KEY,

    -- Metadata
    category VARCHAR(50) NOT NULL, -- e.g., 'SCRIPT_TAG', 'EVENT_HANDLER', 'ENCODED_URI'
    severity core.enum_error_severity NOT NULL DEFAULT 'HIGH'
);

COMMENT ON TABLE core.xss_signatures IS 'Signature database for XSS payload detection';

------------------------------------------------------------------------------------------------
-- Table: T020 - allowed_mime_types
-- Description: Mapping of file extensions to accepted MIME types.
-- Business Case: Ensures file upload security. Users often rename malicious executables
-- (.exe) to benign extensions (.jpg). This table defines the expected MIME type for a given
-- extension. The system (F030) verifies the file's "Magic Bytes" match this mapping, rejecting
-- mismatches to prevent malware upload.
-- KPIs: Malware upload attempts blocked.
-- Feature Reference: F030
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.allowed_mime_types (
    -- Primary Key
    extension VARCHAR(20) PRIMARY KEY, -- e.g., 'pdf', 'jpg', 'png'

    -- Attributes
    mime_type VARCHAR(100) NOT NULL, -- e.g., 'application/pdf'
    is_binary BOOLEAN NOT NULL DEFAULT true,
    max_file_size_mb INTEGER DEFAULT 10
);

COMMENT ON TABLE core.allowed_mime_types IS 'Allowed file extensions and their MIME types';

------------------------------------------------------------------------------------------------
-- Table: T021 - magic_bytes
-- Description: File magic numbers for deep file validation.
-- Business Case: The definitive check for file type. Files are identified by the byte sequence
-- at their beginning, not their extension. This table stores the hex signature (offset and
-- bytes) to verify that a claimed image file is actually an image and not a disguised payload.
-- KPIs: Malware interception rate.
-- Feature Reference: F030
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.magic_bytes (
    -- Primary Key
    extension VARCHAR(20) PRIMARY KEY,

    -- Signature
    hex_signature TEXT NOT NULL, -- e.g., '89504E470D0A1A0A' for PNG
    offset INTEGER NOT NULL DEFAULT 0 -- Usually 0
);

COMMENT ON TABLE core.magic_bytes IS 'File signature (magic bytes) definitions for validation';

------------------------------------------------------------------------------------------------
-- Table: T022 - geo_fence_rules
-- Description: Rules for valid coordinate ranges (bounding boxes).
-- Business Case: Defines geographic zones where transactions or services are allowed.
-- Used in logistics and location-based fraud detection. If a transaction claims to happen in
-- a location outside the valid operational bounds, it is rejected. This prevents shipping
-- errors and location spoofing.
-- KPIs: Geo-validation accuracy, Shipping cost reduction.
-- Feature Reference: F031
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.geo_fence_rules (
    -- Primary Key
    boundary_name VARCHAR(100) PRIMARY KEY,

    -- Coordinates
    lat_min NUMERIC(9,6) NOT NULL,
    lat_max NUMERIC(9,6) NOT NULL,
    lon_min NUMERIC(9,6) NOT NULL,
    lon_max NUMERIC(9,6) NOT NULL,

    -- Constraints
    CONSTRAINT geo_fence_valid_lat CHECK (lat_min >= -90 AND lat_max <= 90),
    CONSTRAINT geo_fence_valid_lon CHECK (lon_min >= -180 AND lon_max <= 180),
    CONSTRAINT geo_fence_logical_box CHECK (lat_max > lat_min AND lon_max > lon_min)
);

COMMENT ON TABLE core.geo_fence_rules IS 'Geospatial boundary definitions for validation';

------------------------------------------------------------------------------------------------
-- Table: T023 - semantic_version_policy
-- Description: Rules for valid software version strings.
-- Business Case: Standardizes versioning of API contracts and software components. Ensures
-- that version strings follow SemVer (x.y.z) and enforces policies on valid increments
-- (e.g., preventing a minor version jump from 1.0 to 3.0). This aids in compatibility checks
-- between integrated systems.
-- KPIs: Integration failure rate due to version mismatch.
-- Feature Reference: F033
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.semantic_version_policy (
    -- Primary Key
    component VARCHAR(50) PRIMARY KEY, -- e.g., 'API_CONTRACT', 'CLIENT_SDK'

    -- Rules
    major_min INTEGER DEFAULT 0,
    minor_min INTEGER DEFAULT 0,
    patch_min INTEGER DEFAULT 0,

    -- Format
    allow_prerelease BOOLEAN DEFAULT false,
    allow_metadata BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.semantic_version_policy IS 'Validation rules for semantic versioning';

------------------------------------------------------------------------------------------------
-- Table: T024 - unicode_normalization_forms
-- Description: Supported Unicode normalization forms.
-- Business Case: Ensures text consistency. Unicode characters can be represented in multiple
-- byte sequences (e.g., 'é' as one character or 'e' + combining acute accent). This table
-- configures which form (NFC, NFD) to enforce, preventing "canonicalization mismatches" where
-- two visually identical strings fail equality checks.
-- KPIs: Search accuracy, Data deduplication success.
-- Feature Reference: F041
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.unicode_normalization_forms (
    -- Primary Key
    form_id VARCHAR(10) PRIMARY KEY, -- e.g., 'NFC', 'NFD', 'NFKC', 'NFKD'

    -- Metadata
    name VARCHAR(100),
    description TEXT,
    is_default BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.unicode_normalization_forms IS 'Configuration for Unicode normalization';

------------------------------------------------------------------------------------------------
-- Table: T025 - dns_record_types
-- Description: Valid DNS record types for validation.
-- Business Case: Validates inputs related to network configuration. Ensures that only
-- standard DNS record types (A, AAAA, CNAME, MX, TXT) are accepted in configuration forms,
-- preventing invalid DNS propagation requests that could break services.
-- KPIs: DNS configuration error rate.
-- Feature Reference: F052
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.dns_record_types (
    -- Primary Key
    type_code VARCHAR(10) PRIMARY KEY, -- e.g., 'A', 'AAAA', 'MX'

    description VARCHAR(255)
);

COMMENT ON TABLE core.dns_record_types IS 'Valid DNS record types';

------------------------------------------------------------------------------------------------
-- Table: T026 - wcag_contrast_ratios
-- Description: Contrast requirements for accessibility (WCAG).
-- Business Case: Enforces accessibility standards for user-generated content or UI themes.
-- Validates that text color contrasts against background colors meet WCAG AA or AAA ratios,
-- ensuring the platform remains usable for visually impaired users and avoiding legal liability.
-- KPIs: Accessibility compliance score.
-- Feature Reference: F055
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.wcag_contrast_ratios (
    -- Primary Key
    font_size_category VARCHAR(50) PRIMARY KEY, -- e.g., 'LARGE_TEXT', 'NORMAL_TEXT'

    -- Ratios
    aa_ratio NUMERIC(3,2) NOT NULL, -- e.g., 4.5
    aaa_ratio NUMERIC(3,2) NOT NULL -- e.g., 7.0
);

COMMENT ON TABLE core.wcag_contrast_ratios IS 'WCAG accessibility contrast requirements';

------------------------------------------------------------------------------------------------
-- Table: T027 - priority_levels
-- Description: Valid priority levels for internal tasks/queues.
-- Business Case: Standardizes priority assignment across the platform (High, Medium, Low).
-- Ensures that incoming API requests or background jobs use valid priority descriptors,
-- allowing the task scheduler to correctly weight execution order.
-- KPIs: Task scheduling latency.
-- Feature Reference: F057
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.priority_levels (
    -- Primary Key
    level VARCHAR(20) PRIMARY KEY, -- e.g., 'CRITICAL', 'HIGH', 'MEDIUM', 'LOW'

    rank INTEGER NOT NULL UNIQUE -- Numeric weight for sorting
);

COMMENT ON TABLE core.priority_levels IS 'Standardized priority levels';

------------------------------------------------------------------------------------------------
-- Table: T028 - data_retention_policies
-- Description: Retention periods per data type/classification.
-- Business Case: Enforces GDPR/CCPA "Right to be Forgotten" and data minimization principles.
-- Defines how long different types of data (transaction logs, IP addresses, PII) can be kept.
-- Automated jobs use this table to flag records for deletion or archival.
-- KPIs: Compliance with data retention laws.
-- Feature Reference: F058
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.data_retention_policies (
    -- Primary Key
    data_type VARCHAR(100) PRIMARY KEY, -- e.g., 'TRANSACTION_LOG', 'IP_ADDRESS', 'PII_FINANCIAL'

    -- Rules
    retention_days INTEGER NOT NULL,
    legal_basis TEXT, -- e.g., 'Contract', 'Legal_Obligation'
    archive_before_delete BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.data_retention_policies IS 'Data retention policies by data classification';

------------------------------------------------------------------------------------------------
-- Table: T029 - regex_dos_prevention
-- Description: Configuration to prevent ReDoS (Regex Denial of Service).
-- Business Case: Protects the validation engine from complex regex patterns that could take
-- exponential time to evaluate (e.g., nested quantifiers). This singleton table sets global
-- timeouts and complexity limits for regex evaluation, ensuring the platform remains responsive.
-- KPIs: System availability (SLA).
-- Feature Reference: F059
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.regex_dos_prevention (
    -- Singleton Pattern
    id INTEGER PRIMARY KEY DEFAULT 1,

    -- Limits
    max_steps INTEGER DEFAULT 100000, -- Maximum steps in NFA/DFA
    max_time_ms INTEGER DEFAULT 5000 -- Timeout in milliseconds
);

INSERT INTO core.regex_dos_prevention (id, max_steps, max_time_ms) VALUES (1, 100000, 5000)
ON CONFLICT (id) DO NOTHING;

COMMENT ON TABLE core.regex_dos_prevention IS 'Global settings to prevent Regex Denial of Service (ReDoS)';

------------------------------------------------------------------------------------------------
-- Table: T030 - crypto_algorithms_whitelist
-- Description: Allowed cryptographic hashing and signing algorithms.
-- Business Case: Enforces cryptographic agility and security. Deprecated algorithms (MD5,
-- SHA1) are forbidden. This table ensures that all signatures, hashes, and keys within the
-- system use strong, modern algorithms (SHA256+, Ed25519), protecting against collision
-- attacks and pre-image attacks.
-- KPIs: Cryptographic compliance score.
-- Feature Reference: F065, F075, F132
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.crypto_algorithms_whitelist (
    -- Primary Key
    algo_name VARCHAR(50) PRIMARY KEY, -- e.g., 'SHA256', 'ED25519'

    type VARCHAR(20) NOT NULL CHECK (type IN ('HASH', 'SIGN', 'KDF')),
    is_deprecated BOOLEAN NOT NULL DEFAULT false,
    minimum_key_size INTEGER
);

COMMENT ON TABLE core.crypto_algorithms_whitelist IS 'Allowed cryptographic algorithms';

------------------------------------------------------------------------------------------------
-- Table: T031 - smart_contract_abis
-- Description: Valid ABIs for blockchain interactions.
-- Business Case: Validates that calls to smart contracts match the expected interface. If a
-- merchant integrates a crypto-payment gateway, this table holds the ABI to validate the
-- transaction data structure against the contract's actual functions and events, preventing
-- lost funds in the void.
-- KPIs: Crypto transaction success rate.
-- Feature Reference: F061
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.smart_contract_abis (
    -- Primary Key
    contract_address VARCHAR(42) NOT NULL, -- Ethereum 0x...
    chain_id INTEGER NOT NULL,
    PRIMARY KEY (contract_address, chain_id),

    -- Definition
    abi_json JSONB NOT NULL, -- The Contract ABI
    contract_name VARCHAR(100)
);

COMMENT ON TABLE core.smart_contract_abis IS 'ABI definitions for smart contract validation';

------------------------------------------------------------------------------------------------
-- Table: T032 - blinded_coin_denominations
-- Description: Valid public keys for blinded coin denominations (Taler/Privacy).
-- Business Case: In anonymous payment systems (like Taler used in PARI), denominations have
-- specific public keys. This table stores the active keys. Validating that a coin belongs
-- to a known, unexpired denomination prevents the minting of counterfeit coins or replay of
-- old coins.
-- KPIs: Counterfeit coin detection rate.
-- Feature Reference: F073
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.blinded_coin_denominations (
    -- Primary Key
    denom_pub_hash CHAR(64) PRIMARY KEY, -- Hash of the public key

    -- Metadata
    value NUMERIC(20,4) NOT NULL,
    currency CHAR(3) NOT NULL,
    expire_start TIMESTAMP WITH TIME ZONE NOT NULL,
    expire_end TIMESTAMP WITH TIME ZONE NOT NULL,

    -- Status
    is_revoked BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.blinded_coin_denominations IS 'Valid denomination keys for blinded anonymous coins';

------------------------------------------------------------------------------------------------
-- Table: T033 - merchant_public_keys
-- Description: Registered public keys of merchants for signature verification.
-- Business Case: Ensures authenticity of webhooks and API requests from merchants. By storing
-- the merchant's public keys (or fingerprints), M12 can verify signatures on incoming payloads
-- (F132), ensuring the request actually came from the merchant and not a man-in-the-middle.
-- KPIs: Spoofing attempts blocked.
-- Feature Reference: F079, F132
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.merchant_public_keys (
    -- Primary Key
    merchant_id UUID NOT NULL,
    key_id VARCHAR(100) NOT NULL,
    PRIMARY KEY (merchant_id, key_id),

    -- Key Data
    public_key TEXT NOT NULL, -- PEM or other format
    key_algorithm VARCHAR(20) NOT NULL, -- e.g., 'RSA', 'ED25519'

    -- Lifecycle
    valid_from TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    revoked_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.merchant_public_keys IS 'Public keys for verifying merchant signatures';

------------------------------------------------------------------------------------------------
-- Table: T034 - exchange_wire_fees
-- Description: Structure for exchange wire fee configurations.
-- Business Case: Defines the fees that exchanges charge for wire transfers. Validating incoming
-- fee structures against this table ensures that users (wallets) are not overcharged and that
-- the fees conform to the agreed-upon service level agreement (SLA) with the liquidity provider.
-- KPIs: Billing accuracy, Revenue leakage prevention.
-- Feature Reference: F082
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.exchange_wire_fees (
    -- Primary Key
    exchange_url VARCHAR(255) NOT NULL,
    start_date TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (exchange_url, start_date),

    -- Fees
    fees_jsonb JSONB NOT NULL, -- e.g., {"wire": "SEPA", "fee": "0.01", "fraction": "0"}

    -- Validity
    end_date TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.exchange_wire_fees IS 'Wire fee configurations per exchange';

------------------------------------------------------------------------------------------------
-- Table: T035 - account_restriction_flags
-- Description: Definition of restriction flags (SHADOW, FROZEN).
-- Business Case: Centralizes the definition of account states. By storing the flags and their
-- associated KYC level requirements, the validation logic can enforce these restrictions
-- uniformly. For example, ensuring a "FROZEN" account cannot initiate new transactions.
-- KPIs: Compliance violation count.
-- Feature Reference: F084
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.account_restriction_flags (
    -- Primary Key
    flag_name VARCHAR(50) PRIMARY KEY, -- e.g., 'FROZEN', 'SHADOW', 'DEPOSIT_ONLY'

    -- Definition
    description TEXT NOT NULL,
    requires_kyc_level core.enum_kyc_level, -- Min level to lift this flag?

    -- Logic
    blocks_debit BOOLEAN DEFAULT false,
    blocks_credit BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.account_restriction_flags IS 'Definitions of account restriction flags';

------------------------------------------------------------------------------------------------
-- Table: T036 - aml_score_thresholds
-- Description: Thresholds for AML (Anti-Money Laundering) action triggers.
-- Business Case: Defines the score ranges that trigger specific actions. E.g., 0-50 is pass,
-- 50-80 is manual review, 80+ is block. Validating the AML score returned by M03 against these
-- ranges ensures that the system responds proportionally to risk levels.
-- KPIs: False positive rate in AML blocking.
-- Feature Reference: F086
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.aml_score_thresholds (
    -- Primary Key
    id SERIAL PRIMARY KEY,

    -- Range
    score_min INTEGER NOT NULL,
    score_max INTEGER NOT NULL,

    -- Action
    action VARCHAR(50) NOT NULL CHECK (action IN ('ALLOW', 'REVIEW', 'BLOCK', 'FREEZE')),

    -- Constraints
    CHECK (score_max > score_min),
    EXCLUDE USING gist (int4range(score_min, score_max) WITH &&)
);

COMMENT ON TABLE core.aml_score_thresholds IS 'Thresholds for AML score actions';

------------------------------------------------------------------------------------------------
-- Table: T037 - sanctions_lists
-- Description: Cached data from sanctions screening APIs (OFAC, EU, UN).
-- Business Case: Maintains a local, searchable copy of sanctions lists (SDN, etc.) for
-- real-time validation of names and countries. This ensures that no transaction is processed
-- for a sanctioned entity, which would result in massive legal penalties for the platform.
-- KPIs: Sanctioned entity interception rate.
-- Feature Reference: F087
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.sanctions_lists (
    -- Primary Key
    list_name VARCHAR(50) NOT NULL, -- e.g., 'OFAC_SDN', 'EU_CONSOLIDATED'
    entry_id VARCHAR(100) NOT NULL,
    PRIMARY KEY (list_name, entry_id),

    -- Data
    data_jsonb NOT NULL, -- Name, DOB, Country, Address info
    last_updated TIMESTAMP WITH TIME ZONE NOT NULL
);

COMMENT ON TABLE core.sanctions_lists IS 'Cached entries from global sanctions lists';

------------------------------------------------------------------------------------------------
-- Table: T038 - psd2_sca_exemptions
-- Description: Valid SCA (Strong Customer Authentication) exemption codes.
-- Business Case: Under PSD2, certain low-risk transactions are exempt from SCA. This table
-- stores the valid exemption codes (e.g., 'TRUSTED_BENEFICIARY', 'LOW_VALUE'). Validation
-- ensures merchants only send valid exemption reasons, preventing compliant payment rejections.
-- KPIs: SCA exemption approval rate.
-- Feature Reference: F089
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.psd2_sca_exemptions (
    -- Primary Key
    exemption_code VARCHAR(50) PRIMARY KEY, -- e.g., 'LOW_VALUE', 'SECURE_CORPORATE'

    -- Description
    description TEXT,
    max_amount_eur NUMERIC(10,2) -- Some exemptions have value caps
);

COMMENT ON TABLE core.psd2_sca_exemptions IS 'Valid PSD2 SCA exemption codes';

------------------------------------------------------------------------------------------------
-- Table: T039 - oidc_providers
-- Description: Registered OpenID Connect providers (Identity Providers).
-- Business Case: Stores configuration for 3rd party login (Google, Auth0, BankID). This
-- includes issuer URLs and JWKS endpoints. Validation ensures that authentication tokens
-- (JWS) are issued by known, trusted providers before allowing access.
-- KPIs: Identity fraud prevention.
-- Feature Reference: F090
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.oidc_providers (
    -- Primary Key
    issuer_url VARCHAR(255) PRIMARY KEY, -- e.g., 'https://accounts.google.com'

    -- Configuration
    client_id VARCHAR(255) NOT NULL,
    jwks_endpoint TEXT NOT NULL,

    -- Security
    tls_verify BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.oidc_providers IS 'Registered OpenID Connect providers';

------------------------------------------------------------------------------------------------
-- Table: T040 - eidas_attributes
-- Description: Allowed eIDAS (Electronic Identification And Trust Services) attributes.
-- Business Case: Standardizes digital identity attributes across the EU. Validates that
-- identity verification responses contain only recognized and allowed attributes (e.g.,
-- 'FirstName', 'DateOfBirth'), preventing injection of malicious data during eIDAS integration.
-- KPIs: eIDAS integration success rate.
-- Feature Reference: F091
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.eidas_attributes (
    -- Primary Key
    attribute_name VARCHAR(100) PRIMARY KEY, -- e.g., 'PersonIdentifier'

    -- Metadata
    friendly_name VARCHAR(255),
    is_required BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.eidas_attributes IS 'Allowed eIDAS attributes';

------------------------------------------------------------------------------------------------
-- Table: T041 - specific_bank_formats
-- Description: Validator logic for specific national bank IDs.
-- Business Case: Banking formats (e.g., UK Account/Sort, German BLZ/Konto) are highly
-- specific. This table maps country codes to specific regex or logic rules, extending the
-- generic validation framework to cover local peculiarities.
-- KPIs: Local payment format accuracy.
-- Feature Reference: F093-F110
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.specific_bank_formats (
    -- Primary Key
    country_code CHAR(2) NOT NULL,
    format_name VARCHAR(50) NOT NULL,
    PRIMARY KEY (country_code, format_name),

    -- Logic
    validation_regex TEXT, -- If regex is sufficient
    validation_logic TEXT, -- If custom SQL logic is needed (pseudo-code)

    -- Metadata
    example_value VARCHAR(50)
);

COMMENT ON TABLE core.specific_bank_formats IS 'Validation rules for national-specific bank formats';

------------------------------------------------------------------------------------------------
-- Table: T042 - card_bin_ranges
-- Description: IIN (Issuer Identification Number) ranges for card brand identification.
-- Business Case: The first 6-8 digits of a card identify the issuer and brand. This table
-- stores these ranges. By looking up the BIN, the system can determine the card brand
-- (Visa, MC) and whether it is a debit or credit card to apply specific logic (F117, F118).
-- KPIs: Card routing accuracy.
-- Feature Reference: F118
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.card_bin_ranges (
    -- Primary Key
    bin_start VARCHAR(8) NOT NULL, -- Usually 6 or 8 digits
    bin_end VARCHAR(8) NOT NULL,

    -- Attributes
    brand core.enum_card_brand NOT NULL,
    card_type VARCHAR(20) CHECK (card_type IN ('DEBIT', 'CREDIT', 'PREPAID')),
    bank_name VARCHAR(255),
    country_code CHAR(2),

    -- Constraints
    EXCLUDE USING gist (
        int4range(bin_start::BIGINT, bin_end::BIGINT) WITH &&
    )
);

COMMENT ON TABLE core.card_bin_ranges IS 'BIN ranges for card identification';

------------------------------------------------------------------------------------------------
-- Table: T043 - emv_tags
-- Description: Valid EMV tags and formats for contactless/chip payments.
-- Business Case: EMV tags define the data elements in a chip card transaction. Validating
-- that tags like '9F02' (Amount, Authorized) have the correct format (numeric, 6 bytes)
-- ensures the message structure is valid before sending to the processor.
-- KPIs: POS terminal success rate.
-- Feature Reference: F120
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.emv_tags (
    -- Primary Key
    tag_number VARCHAR(4) PRIMARY KEY, -- Hex tag, e.g., '9F02'

    -- Metadata
    name VARCHAR(100),
    format VARCHAR(20) CHECK (format IN ('n', 'an', 'ans', 'cn', 'b')), -- EMV format codes
    length VARCHAR(20) -- e.g., '6', '..12'
);

COMMENT ON TABLE core.emv_tags IS 'Valid EMV tags and format definitions';

------------------------------------------------------------------------------------------------
-- Table: T044 - payment_methods
-- Description: Allowed payment methods and their validation rules.
-- Business Case: Defines the whitelist of payment methods supported by the platform (SEPA,
-- SWIFT, Card, Crypto). Links them to the specific validation module or function required.
-- Ensures that unsupported methods are rejected immediately at the API edge.
-- KPIs: Payment method availability.
-- Feature Reference: F114
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.payment_methods (
    -- Primary Key
    method_id VARCHAR(50) PRIMARY KEY, -- e.g., 'SEPA_CREDIT_TRANSFER'

    -- Attributes
    name VARCHAR(100) NOT NULL,
    validation_module VARCHAR(100), -- Reference to code/logic
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.payment_methods IS 'Supported payment methods';

------------------------------------------------------------------------------------------------
-- Table: T045 - promo_codes
-- Description: Valid promo/voucher codes and business logic.
-- Business Case: Ensures that promo codes applied to transactions are valid, active, and not
-- exhausted. It checks the code format, usage limits, and expiration. Prevents revenue loss
-- from abused or expired codes.
-- KPIs: Promo abuse rate, Fraudulent discount usage.
-- Feature Reference: F124
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.promo_codes (
    -- Primary Key
    code VARCHAR(50) PRIMARY KEY,

    -- Logic
    discount_type VARCHAR(20) CHECK (discount_type IN ('PERCENT', 'FIXED', 'BOGO')),
    value NUMERIC(10,2) NOT NULL,

    -- Limits
    max_uses INTEGER,
    current_uses INTEGER DEFAULT 0,
    expires_at TIMESTAMP WITH TIME ZONE,

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.promo_codes IS 'Valid promotional codes and rules';

------------------------------------------------------------------------------------------------
-- Table: T046 - webhook_endpoints
-- Description: Registered webhook URLs and secrets for merchants.
-- Business Case: Securely manages the endpoints where the platform sends events. Stores the
-- secret used to sign payloads (HMAC). Validates that URLs are HTTPS and reachable (F131).
-- KPIs: Webhook delivery success rate.
-- Feature Reference: F131, F132
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.webhook_endpoints (
    -- Primary Key
    url VARCHAR(2048) PRIMARY KEY,

    -- Security
    secret_hash VARCHAR(255) NOT NULL, -- Hash of the signing secret

    -- Events
    events TEXT[] NOT NULL, -- List of subscribed events
    merchant_id UUID NOT NULL,

    -- Metadata
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.webhook_endpoints IS 'Registered webhook endpoints';

------------------------------------------------------------------------------------------------
-- Table: T047 - api_keys
-- Description: API keys and their associated scopes/quotas.
-- Business Case: Controls access to the PARI API. Keys are hashed and stored with their
-- assigned scopes (e.g., 'read:transactions', 'write:payments'). Validation ensures that
-- an incoming request has the necessary permission for the endpoint (F133).
-- KPIs: Unauthorized access attempts blocked.
-- Feature Reference: F133, F134
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.api_keys (
    -- Primary Key
    key_hash VARCHAR(64) PRIMARY KEY, -- SHA-256 of the key

    -- Configuration
    scopes TEXT[] NOT NULL, -- e.g., {'transaction:read', 'user:write'}
    quota_limit INTEGER, -- Requests per hour/day

    -- Attribution
    owner_id UUID NOT NULL, -- User or Service Account
    tenant_id UUID NOT NULL, -- Multi-tenant isolation

    -- State
    is_active BOOLEAN DEFAULT true,
    last_used_at TIMESTAMP WITH TIME ZONE,

    -- Indexes
    CONSTRAINT api_keys_tenant_idx UNIQUE (tenant_id, key_hash)
);

COMMENT ON TABLE core.api_keys IS 'API Keys for authentication and authorization';

-- Row Level Security for T047 (API Keys)
ALTER TABLE core.api_keys ENABLE ROW LEVEL SECURITY;
CREATE POLICY api_keys_tenant_isolation ON core.api_keys
    USING (tenant_id = current_setting('app.current_tenant_id')::UUID);

------------------------------------------------------------------------------------------------
-- Table: T048 - tenants
-- Description: Multi-tenant configuration and isolation.
-- Business Case: Isolates data and configuration per client (e.g., different Banks or
-- Merchants using the PARI infrastructure). Stores settings specific to the tenant, such
-- as default currency or compliance level.
-- KPIs: Tenant onboarding time.
-- Feature Reference: F135
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.tenants (
    -- Primary Key
    tenant_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Info
    name VARCHAR(255) NOT NULL,
    domain VARCHAR(255), -- Custom domain

    -- Config
    settings_jsonb JSONB, -- Flexible settings

    -- State
    status VARCHAR(20) CHECK (status IN ('ACTIVE', 'SUSPENDED', 'PENDING')),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.tenants IS 'Multi-tenant configurations';

------------------------------------------------------------------------------------------------
-- Table: T049 - feature_flags
-- Description: Feature toggles for the platform.
-- Business Case: Enables canary releases and A/B testing of features. By storing flags here,
-- M12 can validate if a specific feature is enabled for a tenant before processing a request
-- that depends on it. It allows gradual rollout of new validation rules or logic.
-- KPIs: Deployment failure rate (reduced via flags).
-- Feature Reference: F142
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.feature_flags (
    -- Primary Key
    flag_key VARCHAR(100) PRIMARY KEY,

    -- Configuration
    is_enabled BOOLEAN NOT NULL DEFAULT false,
    rollout_percentage INTEGER DEFAULT 0 CHECK (rollout_percentage >= 0 AND rollout_percentage <= 100),
    allowed_tenant_ids UUID[]
);

COMMENT ON TABLE core.feature_flags IS 'Feature flag definitions';

------------------------------------------------------------------------------------------------
-- Table: T050 - experiment_configs
-- Description: A/B test configurations.
-- Business Case: Configures experiments for testing new validation logic or UI changes.
-- Validates that a user belongs to a specific bucket for an experiment.
-- KPIs: Experiment population accuracy.
-- Feature Reference: F143
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.experiment_configs (
    -- Primary Key
    experiment_name VARCHAR(100) PRIMARY KEY,

    -- Config
    bucket_count INTEGER NOT NULL DEFAULT 2, -- Control vs Variant
    targeting_rule TEXT, -- SQL snippet or JSON logic for inclusion

    -- State
    is_active BOOLEAN DEFAULT true,
    start_date TIMESTAMP WITH TIME ZONE,
    end_date TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.experiment_configs IS 'Configuration for A/B testing experiments';

-- ================================================================================================
-- 5. ENTITY RELATIONSHIPS AND CONSTRAINTS (Foreign Keys)
-- ================================================================================================

-- T002 (validation_rule_history) references T001 (validation_rules)
ALTER TABLE core.validation_rule_history
    ADD CONSTRAINT fk_val_history_rule
    FOREIGN KEY (rule_id) REFERENCES core.validation_rules(id) ON DELETE CASCADE;

-- T013 (iban_registry) references T004 (iso_3166_countries)
ALTER TABLE core.iban_registry
    ADD CONSTRAINT fk_iban_country
    FOREIGN KEY (country_code) REFERENCES core.iso_3166_countries(alpha_2_code) ON DELETE RESTRICT;

-- T016 (vat_id_formats) references T004 (iso_3166_countries)
ALTER TABLE core.vat_id_formats
    ADD CONSTRAINT fk_vat_country
    FOREIGN KEY (country_code) REFERENCES core.iso_3166_countries(alpha_2_code) ON DELETE RESTRICT;

-- T014 (swift_bic_registry) references T004 (iso_3166_countries)
ALTER TABLE core.swift_bic_registry
    ADD CONSTRAINT fk_bic_country
    FOREIGN KEY (country_code) REFERENCES core.iso_3166_countries(alpha_2_code) ON DELETE RESTRICT;

-- T041 (specific_bank_formats) references T004 (iso_3166_countries)
ALTER TABLE core.specific_bank_formats
    ADD CONSTRAINT_fk_bank_format_country
    FOREIGN KEY (country_code) REFERENCES core.iso_3166_countries(alpha_2_code) ON DELETE RESTRICT;

-- T042 (card_bin_ranges) references T004 (iso_3166_countries)
ALTER TABLE core.card_bin_ranges
    ADD CONSTRAINT fk_bin_country
    FOREIGN KEY (country_code) REFERENCES core.iso_3166_countries(alpha_2_code) ON DELETE SET NULL;

-- T033 (merchant_public_keys) references T048 (tenants) [Implicit via Merchant ID usually, assuming Tenant ID for FK]
ALTER TABLE core.api_keys
    ADD CONSTRAINT fk_api_key_tenant
    FOREIGN KEY (tenant_id) REFERENCES core.tenants(tenant_id) ON DELETE CASCADE;

-- ================================================================================================
-- 6. TRIGGERS FOR AUDIT COLUMNS
-- ================================================================================================

-- Apply the update_updated_at trigger to all tables with updated_at column
DO $$ DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT table_name
             FROM information_schema.tables
             WHERE table_schema = 'core'
             AND table_name IN (
                 'validation_rules', 'validation_rule_history', 'iso_4217_currencies',
                 'iso_3166_countries', 'error_codes_registry', 'json_schemas_registry',
                 'regex_patterns', 'data_type_mappings', 'tenants'
             )
    LOOP
        EXECUTE format('CREATE TRIGGER trigger_update_%s BEFORE UPDATE ON core.%I FOR EACH ROW EXECUTE FUNCTION core.trigger_update_updated_at()', r.table_name, r.table_name);
    END LOOP;
END$$;

