-- ================================================================================================
-- 4. DDL STATEMENTS (TABLES T051 - T100)
-- ================================================================================================

------------------------------------------------------------------------------------------------
-- Table: T051 - bot_signatures
-- Description: User-Agent signatures and patterns for identifying automated bots.
-- Business Case: Malicious bots often scrape APIs, perform credential stuffing, or initiate DDoS
-- attacks. This table stores signatures (known User-Agent strings or regex patterns) that are
-- flagged as bots. Validating incoming requests against this list allows the validation layer
-- (M12) to reject bot traffic immediately, conserving resources for legitimate users and
-- protecting against fraud. It supports the "Zero-Defect" goal by ensuring high-quality traffic
-- ingestion and reduces noise in downstream analytics.
-- KPIs: Bot traffic rejection rate, API abuse prevention.
-- Feature Reference: F145
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.bot_signatures (
    -- Primary Key
    signature TEXT PRIMARY KEY, -- String or Regex

    -- Metadata
    bot_name VARCHAR(100), -- e.g., 'GoogleBot', 'Scripthunter'
    pattern_type VARCHAR(20) NOT NULL CHECK (pattern_type IN ('EXACT', 'REGEX')),

    -- State
    is_whitelisted BOOLEAN DEFAULT false, -- Allow GoogleBot, block others
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.bot_signatures IS 'Signatures for identifying and managing bot traffic';

------------------------------------------------------------------------------------------------
-- Table: T052 - cors_origins
-- Description: Allowed Cross-Origin Resource Sharing (CORS) origins.
-- Business Case: Browsers enforce Same-Origin Policy. This table defines which frontend
-- domains (origins) are permitted to access the PARI API. Validating the `Origin` header
-- against this whitelist prevents Cross-Site Request Forgery (CSRF) attacks and unauthorized
-- data access from malicious websites. It ensures that only trusted client applications can
-- interact with the platform.
-- KPIs: Unauthorized CORS attempt block rate.
-- Feature Reference: F154
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cors_origins (
    -- Primary Key
    origin_pattern VARCHAR(255) PRIMARY KEY, -- e.g., 'https://app.merchant.com'

    -- Configuration
    allowed_methods TEXT[] CHECK (array_length(allowed_methods, 1) > 0), -- {'GET', 'POST'}
    allowed_headers TEXT[],
    allow_credentials BOOLEAN DEFAULT false,
    max_age_seconds INTEGER DEFAULT 3600,

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.cors_origins IS 'Allowed CORS origins for API security';

------------------------------------------------------------------------------------------------
-- Table: T053 - tls_versions
-- Description: Allowed TLS protocol versions for internal and external service communication.
-- Business Case: Enforces strong encryption standards for data in transit. By storing
-- allowed versions (e.g., TLS 1.2, TLS 1.3), the system ensures that deprecated or
-- insecure protocols (SSLv3, TLS 1.0/1.1) are rejected. This is critical for PCI-DSS and
-- GDPR compliance, preventing man-in-the-middle attacks that exploit weak protocol
-- configurations.
-- KPIs: Security compliance score.
-- Feature Reference: F185
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.tls_versions (
    -- Primary Key
    version_name VARCHAR(20) PRIMARY KEY, -- e.g., 'TLSv1.3'

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.tls_versions IS 'Allowed TLS protocol versions';

------------------------------------------------------------------------------------------------
-- Table: T054 - cipher_suites
-- Description: Allowed cryptographic cipher suites for TLS.
-- Business Case: Defines which encryption algorithms are acceptable for establishing secure
-- connections. Disabling weak ciphers (e.g., those using RC4 or SHA1) prevents decryption
-- of traffic by attackers. This table allows granular control over the cryptographic stack,
-- ensuring the highest level of security based on current cryptographic best practices.
-- KPIs: Cryptographic strength score.
-- Feature Reference: F186
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cipher_suites (
    -- Primary Key
    suite_name VARCHAR(100) PRIMARY KEY, -- OpenSSL name, e.g., 'TLS_AES_256_GCM_SHA384'

    -- Attributes
    security_score INTEGER NOT NULL CHECK (security_score BETWEEN 1 AND 100),

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.cipher_suites IS 'Allowed TLS cipher suites';

------------------------------------------------------------------------------------------------
-- Table: T055 - certificate_pinning
-- Description: Known certificate fingerprints for pinning.
-- Business Case: Certificate Pinning prevents Man-in-the-Middle (MITM) attacks by ensuring
-- the server presents a certificate with a specific hash (pin). This table stores the
-- expected hashes for critical endpoints. If the validation layer detects a mismatch, it
-- aborts the connection, protecting sensitive payment data from interception.
-- KPIs: MITM attack prevention count.
-- Feature Reference: F187
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.certificate_pinning (
    -- Primary Key
    domain VARCHAR(255) NOT NULL,

    -- Pin Data
    pin_hash VARCHAR(64) NOT NULL, -- SHA-256 hash of SPKI fingerprint
    backup_pin_hash VARCHAR(64), -- Backup pin for rotation

    -- Expiry
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,

    -- Unique Constraint
    CONSTRAINT cert_pin_domain UNIQUE (domain, pin_hash)
);

CREATE INDEX idx_cert_pinning_domain ON core.certificate_pinning(domain);
COMMENT ON TABLE core.certificate_pinning IS 'Certificate pins for MITM prevention';

------------------------------------------------------------------------------------------------
-- Table: T056 - docker_image_registry
-- Description: Allowed Docker registries and specific image digests.
-- Business Case: Controls the supply chain security of the infrastructure. By whitelisting
-- specific registries and image digests, M12 ensures that only signed, verified images are
-- deployed in the PARI environment. This prevents the execution of compromised or malicious
-- containers, a critical requirement for maintaining the integrity of the payment processing
-- platform.
-- KPIs: Container deployment compliance.
-- Feature Reference: F196
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.docker_image_registry (
    -- Primary Key
    registry_url VARCHAR(255) NOT NULL,
    image_name VARCHAR(255) NOT NULL,
    digest VARCHAR(100) NOT NULL, -- sha256:...
    PRIMARY KEY (registry_url, image_name, digest),

    -- Metadata
    signature_verified BOOLEAN DEFAULT true,

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.docker_image_registry IS 'Allowed Docker images for deployment';

------------------------------------------------------------------------------------------------
-- Table: T057 - kubernetes_namespaces
-- Description: Valid Kubernetes namespaces for workload deployment.
-- Business Case: Enforces resource segmentation. Workloads must be deployed to pre-defined,
-- validated namespaces (e.g., `production`, `staging`, `payments`). Validating deployment
-- targets against this table prevents accidental deployments to restricted or shared
-- namespaces, ensuring strict isolation of financial data processing.
-- KPIs: Deployment error reduction.
-- Feature Reference: F199
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.kubernetes_namespaces (
    -- Primary Key
    namespace_name VARCHAR(100) PRIMARY KEY,

    -- Context
    environment VARCHAR(20) NOT NULL CHECK (environment IN ('DEVELOPMENT', 'STAGING', 'PRODUCTION')),
    resource_quota_cpu VARCHAR(20),
    resource_quota_mem VARCHAR(20)
);

COMMENT ON TABLE core.kubernetes_namespaces IS 'Valid Kubernetes namespaces';

------------------------------------------------------------------------------------------------
-- Table: T058 - terraform_state_buckets
-- Description: Allowed S3 buckets for Terraform state storage.
-- Business Case: Terraform state files contain sensitive infrastructure configuration,
-- including secrets. Restricting where this state can be stored ensures that it resides in
-- compliant, encrypted, and access-controlled buckets defined by the security team.
-- KPIs: Infrastructure security compliance.
-- Feature Reference: F200
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.terraform_state_buckets (
    -- Primary Key
    bucket_name VARCHAR(255) PRIMARY KEY,

    -- Attributes
    region VARCHAR(50) NOT NULL,
    is_encrypted BOOLEAN DEFAULT true,
    versioning_enabled BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.terraform_state_buckets IS 'Allowed S3 buckets for Terraform state';

------------------------------------------------------------------------------------------------
-- Table: T059 - cloudformation_stacks
-- Description: Tracked AWS CloudFormation stacks.
-- Business Case: Monitors the existence and status of infrastructure stacks defined as code.
-- Validation logic can use this table to ensure dependencies (e.g., a payments stack) are
-- active and in a `CREATE_COMPLETE` state before allowing traffic routing or feature
-- activation.
-- KPIs: Infrastructure availability.
-- Feature Reference: F201
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cloudformation_stacks (
    -- Primary Key
    stack_name VARCHAR(255) NOT NULL,
    region VARCHAR(50) NOT NULL,
    PRIMARY KEY (stack_name, region),

    -- Attributes
    template_url TEXT,
    last_status VARCHAR(50), -- e.g., CREATE_COMPLETE, UPDATE_ROLLBACK_COMPLETE

    -- Index
    CONSTRAINT cfn_stack_status_unique UNIQUE (stack_name, region)
);

COMMENT ON TABLE core.cloudformation_stacks IS 'Tracked CloudFormation stacks';

------------------------------------------------------------------------------------------------
-- Table: T060 - graphql_persisted_queries
-- Description: Valid persisted GraphQL queries.
-- Business Case: Improves performance and security for GraphQL APIs. By whitelisting query
-- hashes, the server rejects unknown or malformed queries immediately (Query Whitelisting),
-- significantly reducing the attack surface for Denial of Service (DoS) via complex
-- nested queries (F165).
-- KPIs: GraphQL query latency, DoS prevention.
-- Feature Reference: F165
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.graphql_persisted_queries (
    -- Primary Key
    query_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    query_hash VARCHAR(64) UNIQUE NOT NULL, -- SHA-256 hash of the query string
    query_text TEXT NOT NULL,

    -- Metadata
    client_name VARCHAR(100),
    version VARCHAR(50)
);

COMMENT ON TABLE core.graphql_persisted_queries IS 'Persisted GraphQL queries for performance/security';

------------------------------------------------------------------------------------------------
-- Table: T061 - api_rate_limits
-- Description: Rate limit definitions per endpoint.
-- Business Case: Protects the platform from abuse and overload. Defines quotas (requests per
-- minute/hour) for specific API endpoints. The validation layer (M12) checks these limits
-- against a distributed counter (Redis) to throttle abusive traffic, ensuring fair usage and
-- system stability for all merchants.
-- KPIs: API uptime, Abuse traffic blocked.
-- Feature Reference: F134
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.api_rate_limits (
    -- Primary Key
    endpoint VARCHAR(255) NOT NULL,
    method VARCHAR(10) NOT NULL, -- GET, POST, etc.
    PRIMARY KEY (endpoint, method),

    -- Limits
    requests_per_minute INTEGER NOT NULL DEFAULT 60,
    requests_per_hour INTEGER NOT NULL DEFAULT 1000,
    burst_limit INTEGER DEFAULT 10
);

COMMENT ON TABLE core.api_rate_limits IS 'Rate limit configurations per API endpoint';

------------------------------------------------------------------------------------------------
-- Table: T062 - request_id_tracking
-- Description: Tracks request IDs for idempotency keys.
-- Business Case: Ensures that replaying a request (due to network errors) does not result
-- in duplicate transactions. This table stores the `Idempotency-Key` and the resulting
-- response hash. If a client retries with the same key, M12 returns the cached response
-- instead of reprocessing, which is crucial for financial integrity.
-- KPIs: Duplicate transaction prevention rate.
-- Feature Reference: F127
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.request_id_tracking (
    -- Primary Key
    request_id UUID PRIMARY KEY,

    -- State
    response_hash VARCHAR(64), -- Hash of the response payload
    response_code INTEGER,
    expiry TIMESTAMP WITH TIME ZONE NOT NULL
);

-- Create index for TTL cleanup (simulated via application or pg_cron)
CREATE INDEX idx_request_id_expiry ON core.request_id_tracking(expiry);
COMMENT ON TABLE core.request_id_tracking IS 'Idempotency key tracking to prevent duplicate processing';

------------------------------------------------------------------------------------------------
-- Table: T063 - validation_metrics
-- Description: Daily aggregates of validation statistics.
-- Business Case: Provides the quantitative data needed for CMMI Level 5 process management.
-- Stores daily counts of total requests, rejections, and reasons. This powers the M08
-- (Operational Analytics) dashboards, allowing engineers to spot trends in data quality
-- issues and measure the effectiveness of the validation framework over time.
-- KPIs: Data quality trend, Validation accuracy.
-- Feature Reference: F001-F300
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.validation_metrics (
    -- Primary Key
    date DATE NOT NULL,

    -- Metrics
    total_requests BIGINT DEFAULT 0,
    rejected_count BIGINT DEFAULT 0,
    rejection_reason JSONB, -- e.g., {"IBAN": 50, "AMOUNT": 10}

    -- Unique
    CONSTRAINT validation_metrics_date PRIMARY KEY (date)
);

COMMENT ON TABLE core.validation_metrics IS 'Daily aggregated validation metrics';

------------------------------------------------------------------------------------------------
-- Table: T064 - data_quality_scorecards
-- Description: Scores per data domain to assess overall health.
-- Business Case: Assigns a "health score" to different data domains (e.g., 'User_Profile',
-- 'Transaction_Log'). This high-level metric helps stakeholders quickly assess which areas
-- of the data ecosystem are degrading and require attention, supporting proactive governance.
-- KPIs: Domain health scores.
-- Feature Reference: F001-F300
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.data_quality_scorecards (
    -- Primary Key
    domain_name VARCHAR(100) NOT NULL,
    timestamp TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (domain_name, timestamp),

    -- Score
    score NUMERIC(3,0) CHECK (score BETWEEN 0 AND 100), -- 0 to 100

    -- Details
    issues_count INTEGER
);

COMMENT ON TABLE core.data_quality_scorecards IS 'Quality scores for different data domains';

------------------------------------------------------------------------------------------------
-- Table: T065 - address_validation_rules
-- Description: Rules for parsing and validating addresses by country.
-- Business Case: Addresses vary wildly in format globally (e.g., Zip code position, street
-- naming conventions). This table stores the JSON schema or regex templates required to
-- validate and standardize addresses for a specific country, ensuring successful logistics
-- and regulatory compliance.
-- KPIs: Address validation success rate.
-- Feature Reference: F014
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.address_validation_rules (
    -- Primary Key
    country_code CHAR(2) PRIMARY KEY, -- References T004

    -- Structure
    required_fields TEXT[] NOT NULL, -- {'street', 'city', 'postal_code'}
    format_template TEXT, -- e.g., "{street}\n{city} {postal_code}"
    postal_code_regex TEXT
);

COMMENT ON TABLE core.address_validation_rules IS 'Country-specific address validation rules';

------------------------------------------------------------------------------------------------
-- Table: T066 - company_identifiers
-- Description: Reference for Company Registration Numbers.
-- Business Case: Validates legal entity identifiers (e.g., LEI, Companies House ID). Ensures
-- that B2B transactions are conducted between registered, verifiable entities, reducing
-- counterparty risk and satisfying KYC (Know Your Business) requirements.
-- KPIs: KYB compliance rate.
-- Feature Reference: F093-F110
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.company_identifiers (
    -- Primary Key
    country_code CHAR(2) NOT NULL,
    identifier_name VARCHAR(50) NOT NULL, -- e.g., 'LEI', 'SIRET'
    PRIMARY KEY (country_code, identifier_name),

    -- Validation
    regex TEXT,
    length INTEGER,
    check_digit_algorithm VARCHAR(50)
);

COMMENT ON TABLE core.company_identifiers IS 'Reference for company registration identifiers';

------------------------------------------------------------------------------------------------
-- Table: T067 - identity_documents
-- Description: Supported ID document types (Passport, Driver's License).
-- Business Case: Defines the metadata for ID documents accepted for identity verification.
-- Includes country, type, and data extraction points. This ensures that OCR and validation
-- processes (M09) are configured correctly for the specific document being scanned.
-- KPIs: Identity verification success rate.
-- Feature Reference: F262-F276
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.identity_documents (
    -- Primary Key
    country_code CHAR(2) NOT NULL,
    doc_type VARCHAR(50) NOT NULL, -- 'PASSPORT', 'DRIVING_LICENSE'
    PRIMARY KEY (country_code, doc_type),

    -- Attributes
    is_primary BOOLEAN DEFAULT false, -- Most common ID for this country
    mrz_supported BOOLEAN DEFAULT false,
    min_expiry_years INTEGER DEFAULT 0
);

COMMENT ON TABLE core.identity_documents IS 'Supported identity document types';

------------------------------------------------------------------------------------------------
-- Table: T068 - transaction_types
-- Description: Valid transaction types (Credit, Debit, Refund).
-- Business Case: Standardizes the classification of financial movements. Ensures that only
-- valid types are used, which is essential for correct ledger posting and tax reporting
-- (e.g., distinguishing a 'REFUND' from a 'PAYMENT' affects VAT reversal logic).
-- KPIs: Ledger accuracy.
-- Feature Reference: F019
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.transaction_types (
    -- Primary Key
    type_code VARCHAR(50) PRIMARY KEY, -- e.g., 'CREDIT', 'DEBIT', 'REFUND', 'CHARGEBACK'

    -- Attributes
    description TEXT,
    affects_inventory BOOLEAN DEFAULT false,
    is_reversal BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.transaction_types IS 'Valid transaction type codes';

------------------------------------------------------------------------------------------------
-- Table: T069 - currencies_active
-- Description: Subset of ISO 4217 currently active in the system.
-- Business Case: Not all supported currencies may be active for trading or settlement in a
-- specific deployment or tenant. This junction-like table filters the master list (T003)
-- to reflect the operational reality, preventing UI display of currencies that cannot be
-- processed.
-- KPIs: Currency display accuracy.
-- Feature Reference: F002
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.currencies_active (
    -- Primary Key
    currency_code CHAR(3) PRIMARY KEY REFERENCES core.iso_4217_currencies(alphabetic_code),

    -- Operational Config
    is_crypto BOOLEAN NOT NULL DEFAULT false,
    settlement_enabled BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.currencies_active IS 'Active subset of supported currencies';

------------------------------------------------------------------------------------------------
-- Table: T070 - locale_settings
-- Description: Localization settings (Date/Time format) per locale.
-- Business Case: Ensures that data is presented to users in a format familiar to them.
-- Stores formats for dates, numbers (decimal separator), and currencies. Validation ensures
-- inputs from a user in a specific locale match these expectations (e.g., DD/MM/YYYY vs
-- MM/DD/YYYY).
-- KPIs: User experience localization score.
-- Feature Reference: F050
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.locale_settings (
    -- Primary Key
    locale_code VARCHAR(10) PRIMARY KEY, -- e.g., 'en-US', 'fr-FR'

    -- Formats
    date_format VARCHAR(20), -- PostgreSQL format string
    number_format VARCHAR(10), -- 'COMMA_DOT' or 'DOT_COMMA'
    currency_symbol_position CHAR(1) -- 'P' or 'S' (Prefix/Suffix)
);

COMMENT ON TABLE core.locale_settings IS 'Locale-specific formatting settings';

------------------------------------------------------------------------------------------------
-- Table: T071 - timezone_mappings
-- Description: Mappings from IANA to Windows timezone IDs.
-- Business Case: Cross-platform compatibility. Linux systems use IANA (Europe/Berlin),
-- while Windows uses IDs (W. Europe Standard Time). This table ensures that scheduled
-- jobs and timestamps are correctly interpreted across different infrastructure components.
-- KPIs: Scheduling accuracy.
-- Feature Reference: F051
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.timezone_mappings (
    -- Primary Key
    iana_zone VARCHAR(50) PRIMARY KEY,

    -- Mapping
    windows_zone VARCHAR(100)
);

COMMENT ON TABLE core.timezone_mappings IS 'IANA to Windows Timezone mappings';

------------------------------------------------------------------------------------------------
-- Table: T072 - notification_channels
-- Description: Configuration for push/SMS notifications.
-- Business Case: Validates the payload required to send notifications via specific channels
-- (APNS, FCM, SMS providers). Ensures that tokens or phone numbers are valid for the
-- selected channel before queuing the message.
-- KPIs: Notification delivery success rate.
-- Feature Reference: F163
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.notification_channels (
    -- Primary Key
    channel_type VARCHAR(50) PRIMARY KEY, -- 'PUSH_IOS', 'PUSH_ANDROID', 'SMS_TWILIO'

    -- Validation
    validation_requirements JSONB, -- e.g., {"token_format": "HEX"}
    max_payload_size INTEGER
);

COMMENT ON TABLE core.notification_channels IS 'Configuration for notification channel validation';

------------------------------------------------------------------------------------------------
-- Table: T073 - file_storage_buckets
-- Description: Allowed S3 buckets for user uploads.
-- Business Case: Controls where user-generated content (receipts, IDs) is stored. Restricts
-- uploads to specific, secured buckets with lifecycle policies to ensure data is stored
-- cost-effectively and compliantly (e.g., data residency).
-- KPIs: Storage cost efficiency, Security compliance.
-- Feature Reference: F160
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.file_storage_buckets (
    -- Primary Key
    bucket_name VARCHAR(255) PRIMARY KEY,

    -- Config
    max_file_size_mb INTEGER DEFAULT 10,
    allowed_mime_types TEXT[], -- References T020

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.file_storage_buckets IS 'Allowed S3 buckets for user uploads';

------------------------------------------------------------------------------------------------
-- Table: T074 - o_auth_clients
-- Description: Registered OAuth2 clients.
-- Business Case: Manages applications acting as OAuth2 clients. Stores redirect URIs,
-- grant types (Authorization Code, Client Credentials), and scopes. Validation ensures that
-- authorization requests come from registered clients with valid redirect URIs, preventing
-- open redirects and token theft.
-- KPIs: OAuth security incidents prevented.
-- Feature Reference: F090
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.o_auth_clients (
    -- Primary Key
    client_id VARCHAR(255) PRIMARY KEY,

    -- Configuration
    client_secret_hash VARCHAR(255), -- BCrypt hash
    redirect_uris TEXT[] NOT NULL, -- Enforce strict matching
    grant_types TEXT[] NOT NULL,
    scopes TEXT[] NOT NULL,

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.o_auth_clients IS 'Registered OAuth2 Client IDs';

------------------------------------------------------------------------------------------------
-- Table: T075 - saml_providers
-- Description: SAML Identity Provider metadata.
-- Business Case: Stores metadata (SAML 2.0 XML or endpoint URLs) for corporate identity
-- providers (Okta, ADFS). Enables Single Sign-On (SSO) for enterprise users, validating
-- SAML assertions against known issuer certificates.
-- KPIs: SSO integration success rate.
-- Feature Reference: F093
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.saml_providers (
    -- Primary Key
    provider_id VARCHAR(100) PRIMARY KEY,

    -- Metadata
    metadata_url TEXT,
    entity_id VARCHAR(255),
    sso_url TEXT,
    x509_cert TEXT, -- PEM formatted certificate

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.saml_providers IS 'SAML Identity Provider configurations';

------------------------------------------------------------------------------------------------
-- Table: T076 - bank_routing_directories
-- Description: Aggregator for routing numbers and bank details.
-- Business Case: Provides a lookup service for routing numbers (ABA, Sort Code, etc.) to
-- validate the existence of the target bank and ensure the routing number is valid for the
-- claimed country. Reduces failed transactions due to typo'd routing details.
-- KPIs: Payment routing success rate.
-- Feature Reference: F042-F110
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.bank_routing_directories (
    -- Primary Key
    routing_code VARCHAR(50) PRIMARY KEY, -- Can be numeric (ABA) or alphanumeric (BIC)

    -- Attributes
    bank_name VARCHAR(255) NOT NULL,
    country CHAR(2) NOT NULL,
    address TEXT,

    -- Indexes
    CONSTRAINT bank_routing_country_idx UNIQUE (country, routing_code)
);

COMMENT ON TABLE core.bank_routing_directories IS 'Aggregated directory of bank routing numbers';

------------------------------------------------------------------------------------------------
-- Table: T077 - exchange_rates
-- Description: Cached reference rates for amount validation and conversion.
-- Business Case: While exchange engines exist, this table provides a quick validation check.
-- If a user claims a transaction amount of 100 USD is equivalent to 1 EUR (an obvious error),
-- this table (updated daily) can flag the discrepancy, preventing gross calculation errors
-- before the complex conversion logic runs.
-- KPIs: Conversion error detection rate.
-- Feature Reference: F003
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.exchange_rates (
    -- Primary Key
    source_currency CHAR(3) NOT NULL,
    target_currency CHAR(3) NOT NULL,
    timestamp TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (source_currency, target_currency, timestamp),

    -- Rate
    rate NUMERIC(20, 10) NOT NULL CHECK (rate > 0),

    -- Source
    source_provider VARCHAR(50) -- 'ECB', 'FIXER'
);

COMMENT ON TABLE core.exchange_rates IS 'Cached reference exchange rates for validation';

------------------------------------------------------------------------------------------------
-- Table: T078 - validation_test_cases
-- Description: Test cases for validation rules (QA).
-- Business Case: Stores sample payloads and expected outcomes to validate the correctness
-- of the M12 rules themselves. This supports TDD (Test Driven Development) and regression
-- testing, ensuring that new rules do not inadvertently break existing logic.
-- KPIs: Test coverage percentage.
-- Feature Reference: F001-F300
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.validation_test_cases (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Case Data
    rule_id UUID REFERENCES core.validation_rules(id),
    input_payload JSONB NOT NULL,
    expected_result VARCHAR(20) NOT NULL CHECK (expected_result IN ('VALID', 'INVALID')),
    expected_error_code VARCHAR(50) -- If invalid
);

COMMENT ON TABLE core.validation_test_cases IS 'Test cases for validating validation logic';

------------------------------------------------------------------------------------------------
-- Table: T079 - anomaly_detection_config
-- Description: Configuration for ML-based anomaly detection (F087 logic).
-- Business Case: Stores thresholds and sensitivity settings for machine learning models that
-- flag semantic anomalies (e.g., transaction frequency outliers). Adjusting settings here
-- allows tuning the False Positive rate without re-deploying code.
-- KPIs: False positive rate tuning.
-- Feature Reference: F087
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.anomaly_detection_config (
    -- Primary Key
    model_name VARCHAR(100) PRIMARY KEY,

    -- Tuning
    threshold NUMERIC(5,2), -- Z-score or probability threshold
    sensitivity VARCHAR(20) CHECK (sensitivity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),

    -- Metadata
    last_trained_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.anomaly_detection_config IS 'Configuration for ML anomaly detection models';

------------------------------------------------------------------------------------------------
-- Table: T080 - data_governance_policies
-- Description: Policies linking data classification to validation requirements.
-- Business Case: Defines strictness levels. For example, 'PII' data might require
-- validation of encryption fields, while 'PUBLIC' data might not. This table enforces the
-- governance framework by automating rule application based on data sensitivity.
-- KPIs: Governance policy adherence.
-- Feature Reference: F087
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.data_governance_policies (
    -- Primary Key
    sensitivity_level VARCHAR(50) PRIMARY KEY, -- 'PII', 'FINANCIAL', 'PUBLIC'

    -- Requirements
    validation_level VARCHAR(20) NOT NULL, -- 'STRICT', 'STANDARD', 'LOOSE'
    requires_encryption BOOLEAN DEFAULT false,
    retention_class_id INTEGER REFERENCES core.data_retention_policies(2) -- T028 has no ID? Assuming integer PK if added or mapping logic. (Adjusted to reference T028 logic conceptually)
    -- Note: T028 uses 'data_type' as PK. We will assume a mapping logic or link via data_type.
);

COMMENT ON TABLE core.data_governance_policies IS 'Policies linking classification to validation';

------------------------------------------------------------------------------------------------
-- Table: T081 - pii_classification
-- Description: Definition of PII (Personally Identifiable Information) fields.
-- Business Case: Catalogs which database fields contain PII. This is critical for GDPR
-- "Right to be Forgotten" requests and for ensuring PII is not logged to T005
-- (validation_errors_log) without masking.
-- KPIs: GDPR compliance accuracy.
-- Feature Reference: F087
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.pii_classification (
    -- Primary Key
    field_path TEXT PRIMARY KEY, -- e.g., 'user.email', 'payment.card_number'

    -- Definition
    is_pii BOOLEAN NOT NULL DEFAULT true,
    masking_rule VARCHAR(50) -- 'FULL_MASK', 'PARTIAL_MASK', 'HASH'
);

COMMENT ON TABLE core.pii_classification IS 'Catalog of PII fields';

------------------------------------------------------------------------------------------------
-- Table: T082 - audit_trail_config
-- Description: Config for audit logging of valid data.
-- Business Case: Determines which tables and events require full audit trails (Who changed
-- What, When). Not all data changes are critical enough for full auditing. This table
-- configures the scope, balancing performance with compliance requirements.
-- KPIs: Audit completeness vs Performance impact.
-- Feature Reference: F087
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.audit_trail_config (
    -- Primary Key
    table_name VARCHAR(100) PRIMARY KEY,

    -- Config
    is_audited BOOLEAN DEFAULT false,
    audit_columns TEXT[], -- Specific columns to track, or NULL for all
    triggers_enabled BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.audit_trail_config IS 'Configuration for table-level audit trails';

------------------------------------------------------------------------------------------------
-- Table: T083 - encryption_keys
-- Description: Metadata for keys used in data validation (e.g., verifying HMAC).
-- Business Case: Stores the metadata (Key ID, Usage, Status, Version) for cryptographic
-- keys used by the validation framework (e.g., for webhook signature verification).
-- It ensures that keys are rotated and expired keys are not accepted.
-- KPIs: Key rotation compliance.
-- Feature Reference: F132
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.encryption_keys (
    -- Primary Key
    key_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Metadata
    key_usage VARCHAR(50) NOT NULL, -- 'WEBHOOK_SIGNING', 'DATA_ENCRYPTION'
    key_algorithm VARCHAR(20) REFERENCES core.crypto_algorithms_whitelist(algo_name),
    status VARCHAR(20) CHECK (status IN ('ACTIVE', 'REVOKED', 'EXPIRED', 'PENDING')),
    expires_at TIMESTAMP WITH TIME ZONE,

    -- Security Note: Actual key material is stored in a KMS/Vault, not here.
    kms_key_id VARCHAR(255)
);

COMMENT ON TABLE core.encryption_keys IS 'Metadata for cryptographic keys';

------------------------------------------------------------------------------------------------
-- Table: T084 - api_specifications
-- Description: Stored OpenAPI/Swagger specs.
-- Business Case: Stores the official API contract documents. The validation layer uses this
-- to verify that incoming requests match the defined paths, parameters, and schemas. This
-- "Contract-First" enforcement ensures that clients cannot send unexpected payloads.
-- KPIs: API contract compliance.
-- Feature Reference: F205
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.api_specifications (
    -- Primary Key
    spec_name VARCHAR(100) NOT NULL,
    version VARCHAR(20) NOT NULL,
    PRIMARY KEY (spec_name, version),

    -- Content
    spec_json JSONB NOT NULL,

    -- State
    is_published BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.api_specifications IS 'Stored OpenAPI/Swagger specifications';

------------------------------------------------------------------------------------------------
-- Table: T085 - service_discovery
-- Description: Internal service endpoints for validation.
-- Business Case: Dynamic service discovery. As the platform scales microservices, this
-- table (or query to it) helps locate services (like M22 Tax Engine) to validate dependencies
-- (e.g., "Is the tax service available to validate this transaction?").
-- KPIs: Service availability checks.
-- Feature Reference: F135
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.service_discovery (
    -- Primary Key
    service_name VARCHAR(100) PRIMARY KEY,

    -- Network
    endpoint_url TEXT NOT NULL,
    health_check_url TEXT NOT NULL,

    -- State
    is_healthy BOOLEAN DEFAULT false,
    last_heartbeat TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.service_discovery IS 'Internal service registry';

------------------------------------------------------------------------------------------------
-- Table: T086 - load_balancer_config
-- Description: Config for validating requests behind proxies.
-- Business Case: Defines trusted IP ranges for Load Balancers (LBs). The validation layer
-- (F155) inspects headers like `X-Forwarded-For`. This table ensures we only trust the `IP`
-- if it comes from a known LB, preventing IP spoofing attacks.
-- KPIs: Spoofing attack prevention.
-- Feature Reference: F155
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.load_balancer_config (
    -- Primary Key
    lb_name VARCHAR(100) PRIMARY KEY,

    -- Trust
    trusted_ip_range INET NOT NULL, -- CIDR block, e.g., 10.0.0.0/8
    protocol VARCHAR(10) CHECK (protocol IN ('HTTP', 'TCP', 'GRPC'))
);

COMMENT ON TABLE core.load_balancer_config IS 'Trusted Load Balancer configurations';

------------------------------------------------------------------------------------------------
-- Table: T087 - cache_invalidation_rules
-- Description: Rules for cache invalidation.
-- Business Case: Ensures data consistency. When reference data (e.g., exchange rates,
-- sanctions lists) changes, caches must be purged. This table defines events that trigger
-- invalidation, ensuring the validation framework doesn't use stale data.
-- KPIs: Cache consistency rate.
-- Feature Reference: F002 (implied)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cache_invalidation_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rule
    table_name VARCHAR(100) NOT NULL,
    trigger_event VARCHAR(50) NOT NULL CHECK (trigger_event IN ('INSERT', 'UPDATE', 'DELETE')),
    cache_key_pattern TEXT NOT NULL -- Wildcard for keys to delete
);

COMMENT ON TABLE core.cache_invalidation_rules IS 'Rules for invalidating caches on data change';

------------------------------------------------------------------------------------------------
-- Table: T088 - database_shards
-- Description: Mapping of logical shards to physical databases.
-- Business Case: Manages horizontal scaling. The validation layer may need to know which
-- physical shard holds a specific Tenant ID to verify existence constraints (F036). This
-- table provides that routing map.
-- KPIs: Query routing latency.
-- Feature Reference: F001
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.database_shards (
    -- Primary Key
    shard_id INTEGER NOT NULL,

    -- Mapping
    db_host VARCHAR(255) NOT NULL,
    db_name VARCHAR(100) NOT NULL,
    db_port INTEGER DEFAULT 5432,

    PRIMARY KEY (shard_id)
);

COMMENT ON TABLE core.database_shards IS 'Mapping of logical shards to physical database hosts';

------------------------------------------------------------------------------------------------
-- Table: T089 - connection_pools
-- Description: Validation of DB pool settings.
-- Business Case: Defines the maximum number of connections allowed per service. Validation
-- ensures that service configurations do not request pool sizes that exceed the database
-- capacity (Max Connections), preventing database exhaustion.
-- KPIs: Database connection health.
-- Feature Reference: F001
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.connection_pools (
    -- Primary Key
    pool_name VARCHAR(100) PRIMARY KEY,

    -- Settings
    max_connections INTEGER NOT NULL,
    timeout_seconds INTEGER NOT NULL,

    -- Constraints
    CONSTRAINT pool_positive CHECK (max_connections > 0)
);

COMMENT ON TABLE core.connection_pools IS 'Connection pool configuration limits';

------------------------------------------------------------------------------------------------
-- Table: T090 - partition_schemes
-- Description: Table partition definitions.
-- Business Case: Metadata for partitioned tables (like T005 validation_errors_log). Stores
-- the partition key (e.g., `timestamp`) and interval (e.g., `1 day`). The validation
-- framework can check this to ensure data routing or retention queries align with the
-- physical partition structure.
-- KPIs: Partition management efficiency.
-- Feature Reference: F001
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.partition_schemes (
    -- Primary Key
    table_name VARCHAR(100) PRIMARY KEY,

    -- Scheme
    partition_key VARCHAR(100) NOT NULL,
    interval VARCHAR(50) NOT NULL -- '1 day', '1 month'
);

COMMENT ON TABLE core.partition_schemes IS 'Definitions for table partitioning';

------------------------------------------------------------------------------------------------
-- Table: T091 - index_usage_stats
-- Description: Statistics on unused or valid indexes.
-- Business Case: Monitors query performance. Tracks which indexes are used and how often.
-- Validates that new queries introduced by the application are using the correct indexes,
-- preventing performance degradation as the data volume grows (Feature F001-F300 context).
-- KPIs: Database query latency.
-- Feature Reference: F001
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.index_usage_stats (
    -- Primary Key
    index_name VARCHAR(255) NOT NULL,
    table_name VARCHAR(255) NOT NULL,
    PRIMARY KEY (index_name, table_name),

    -- Stats
    usage_count BIGINT DEFAULT 0,
    last_used TIMESTAMP WITH TIME ZONE,
    size_bytes BIGINT
);

COMMENT ON TABLE core.index_usage_stats IS 'Statistics on index usage';

------------------------------------------------------------------------------------------------
-- Table: T092 - lock_definitions
-- Description: Advisory locks for distributed validation.
-- Business Case: Prevents race conditions in distributed processing. Defines lock keys
-- used to ensure that only one node processes a specific validation task (e.g.,
-- validating a specific batch file) at a time.
-- KPIs: Processing collision rate.
-- Feature Reference: F038
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.lock_definitions (
    -- Primary Key
    lock_key VARCHAR(255) PRIMARY KEY,

    -- State
    acquired_by UUID, -- Service or Worker ID
    expiry TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.lock_definitions IS 'Advisory lock definitions for distributed tasks';

------------------------------------------------------------------------------------------------
-- Table: T093 - scheduled_jobs
-- Description: Validation of cron job configurations.
-- Business Case: Ensures that automated tasks (e.g., daily sanitization, report generation)
-- are configured correctly. Validates the Cron Expression syntax (F038) to prevent job
-- scheduling errors or resource overload from misconfigured frequencies.
-- KPIs: Job execution success rate.
-- Feature Reference: F038
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.scheduled_jobs (
    -- Primary Key
    job_name VARCHAR(100) PRIMARY KEY,

    -- Configuration
    cron_expression VARCHAR(100) NOT NULL,
    timeout_seconds INTEGER,

    -- State
    is_active BOOLEAN DEFAULT true,
    last_run_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.scheduled_jobs IS 'Configuration and validation of scheduled jobs';

------------------------------------------------------------------------------------------------
-- Table: T094 - background_tasks
-- Description: Validation of async task payloads.
-- Business Case: Validates payloads queued for background processing (e.g., heavy validation
-- of a 1GB CSV upload). Ensures that the task definition and payload structure are correct
-- before a worker picks it up, saving worker resources.
-- KPIs: Background task error rate.
-- Feature Reference: F038
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.background_tasks (
    -- Primary Key
    task_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Payload
    payload_jsonb JSONB NOT NULL,
    task_type VARCHAR(50) NOT NULL,

    -- State
    status VARCHAR(20) NOT NULL CHECK (status IN ('PENDING', 'PROCESSING', 'FAILED', 'COMPLETED')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.background_tasks IS 'Validation and state of background tasks';

------------------------------------------------------------------------------------------------
-- Table: T095 - message_queue_topics
-- Description: Valid Kafka topics.
-- Business Case: Defines the topics used in the event streaming architecture. Validation
-- ensures that producers only write to valid topics and that topic naming conventions are
-- followed, preventing data silos.
-- KPIs: Messaging success rate.
-- Feature Reference: F173
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.message_queue_topics (
    -- Primary Key
    topic_name VARCHAR(255) PRIMARY KEY,

    -- Configuration
    partitions INTEGER NOT NULL CHECK (partitions > 0),
    replication_factor INTEGER NOT NULL CHECK (replication_factor > 0),

    -- Metadata
    retention_ms BIGINT,
    cleanup_policy VARCHAR(20) CHECK (cleanup_policy IN ('DELETE', 'COMPACT'))
);

COMMENT ON TABLE core.message_queue_topics IS 'Valid Kafka topic configurations';

------------------------------------------------------------------------------------------------
-- Table: T096 - consumer_groups
-- Description: Valid consumer group offsets.
-- Business Case: Tracks the progress of consumers reading from Kafka topics. Validates that
-- consumers are lagging too far behind, which could indicate processing failure or
-- performance bottlenecks, triggering alerts in M08.
-- KPIs: Consumer lag monitoring.
-- Feature Reference: F173
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.consumer_groups (
    -- Primary Key
    group_id VARCHAR(255) NOT NULL,
    topic_name VARCHAR(255) NOT NULL REFERENCES core.message_queue_topics(topic_name),
    PRIMARY KEY (group_id, topic_name),

    -- Offset
    current_lag BIGINT DEFAULT 0,
    last_commit_timestamp TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.consumer_groups IS 'Consumer group lag tracking';

------------------------------------------------------------------------------------------------
-- Table: T097 - schema_evolution_history
-- Description: History of DB schema changes (Migrations).
-- Business Case: Immutable log of all schema changes (DDL). This is critical for rollback
-- planning, auditing, and ensuring that all environments (Dev, Staging, Prod) are
-- synchronized. The checksum ensures the migration was applied correctly.
-- KPIs: Migration success rate.
-- Feature Reference: F001
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.schema_evolution_history (
    -- Primary Key
    migration_id VARCHAR(255) PRIMARY KEY,

    -- Details
    applied_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    checksum VARCHAR(64), -- SHA-256 of the migration script
    script_name VARCHAR(255)
);

COMMENT ON TABLE core.schema_evolution_history IS 'History of schema migrations';

------------------------------------------------------------------------------------------------
-- Table: T098 - view_dependencies
-- Description: Dependency graph for materialized views.
-- Business Case: Ensures that refresh logic for materialized views happens in the correct
-- order. If View A depends on View B, B must be refreshed first. This table defines that
-- graph to prevent stale data in views.
-- KPIs: Data freshness in views.
-- Feature Reference: F001
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.view_dependencies (
    -- Primary Key
    view_name VARCHAR(255) NOT NULL,
    dependent_on VARCHAR(255) NOT NULL, -- Table or View
    PRIMARY KEY (view_name, dependent_on),

    -- Type
    object_type VARCHAR(20) CHECK (object_type IN ('TABLE', 'VIEW', 'MATERIALIZED_VIEW'))
);

COMMENT ON TABLE core.view_dependencies IS 'Dependency graph for views';

------------------------------------------------------------------------------------------------
-- Table: T099 - trigger_definitions
-- Description: Validation of trigger logic.
-- Business Case: Registry of database triggers. Ensures that critical business logic
-- (e.g., updating `updated_at`) is enforced at the database level. It allows validation
-- of the trigger function code or logic constraints.
-- KPIs: Trigger execution count.
-- Feature Reference: F001
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.trigger_definitions (
    -- Primary Key
    trigger_name VARCHAR(100) PRIMARY KEY,

    -- Mapping
    table_name VARCHAR(100) NOT NULL,
    function_name VARCHAR(100) NOT NULL,

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.trigger_definitions IS 'Registry of database triggers';

------------------------------------------------------------------------------------------------
-- Table: T100 - stored_procedures
-- Description: Registry of stored procedures.
-- Business Case: Catalog of all PL/pgSQL functions used by the platform (M12 and others).
-- Stores input/output parameters and return types. This metadata is used for validation
-- of internal API calls or dynamic SQL execution contexts.
-- KPIs: Procedure availability.
-- Feature Reference: F001
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.stored_procedures (
    -- Primary Key
    proc_name VARCHAR(255) PRIMARY KEY,

    -- Signature
    input_params JSONB, -- [{"name": "p_id", "type": "UUID"}]
    return_type VARCHAR(50),

    -- Metadata
    description TEXT,
    is_security_sensitive BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.stored_procedures IS 'Registry of stored procedures';

-- ================================================================================================
-- 5. ENTITY RELATIONSHIPS AND CONSTRAINTS (Foreign Keys - Part 2)
-- ================================================================================================

-- T065 (address_validation_rules) references T004 (iso_3166_countries)
ALTER TABLE core.address_validation_rules
    ADD CONSTRAINT fk_addr_country
    FOREIGN KEY (country_code) REFERENCES core.iso_3166_countries(alpha_2_code) ON DELETE RESTRICT;

-- T066 (company_identifiers) references T004 (iso_3166_countries)
ALTER TABLE core.company_identifiers
    ADD CONSTRAINT fk_co_id_country
    FOREIGN KEY (country_code) REFERENCES core.iso_3166_countries(alpha_2_code) ON DELETE RESTRICT;

-- T067 (identity_documents) references T004 (iso_3166_countries)
ALTER TABLE core.identity_documents
    ADD CONSTRAINT fk_id_doc_country
    FOREIGN KEY (country_code) REFERENCES core.iso_3166_countries(alpha_2_code) ON DELETE RESTRICT;

-- T069 (currencies_active) references T003 (iso_4217_currencies)
ALTER TABLE core.currencies_active
    ADD CONSTRAINT fk_curr_active_ref
    FOREIGN KEY (currency_code) REFERENCES core.iso_4217_currencies(alphabetic_code) ON DELETE CASCADE;

-- T076 (bank_routing_directories) references T004 (iso_3166_countries)
ALTER TABLE core.bank_routing_directories
    ADD CONSTRAINT fk_bank_dir_country
    FOREIGN KEY (country_code) REFERENCES core.iso_3166_countries(alpha_2_code) ON DELETE RESTRICT;

-- T095 (message_queue_topics) is referenced by T096 (consumer_groups)

-- ================================================================================================
-- 6. TRIGGERS FOR AUDIT COLUMNS (Part 2)
-- ================================================================================================

-- Apply the update_updated_at trigger to Part 2 tables
DO $$ DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT table_name
             FROM information_schema.tables
             WHERE table_schema = 'core'
             AND table_name IN (
                 'bot_signatures', 'cors_origins', 'docker_image_registry',
                 'anomaly_detection_config', 'encryption_keys', 'api_specifications',
                 'service_discovery', 'connection_pools', 'scheduled_jobs',
                 'consumer_groups'
             )
    LOOP
        EXECUTE format('CREATE TRIGGER trigger_update_%s BEFORE UPDATE ON core.%I FOR EACH ROW EXECUTE FUNCTION core.trigger_update_updated_at()', r.table_name, r.table_name);
    END LOOP;
END$$;

