-- ================================================================================================
-- 4. DDL STATEMENTS (TABLES T101 - T150)
-- ================================================================================================

------------------------------------------------------------------------------------------------
-- Table: T101 - fedwire_routing_rules
-- Description: Configuration rules for validating US Fedwire routing numbers.
-- Business Case: Fedwire is the primary real-time gross settlement system in the US. Validating
-- the 9-digit Fedwire routing number (RTN) is critical for high-value, time-sensitive transfers.
-- This table stores the specific validation rules, including the check digit algorithm and
-- clearing system codes, ensuring that funds are not sent to non-existent or closed
-- correspondent banks, which would cause severe liquidity delays.
-- KPIs: Fedwire transaction accuracy, Failed transfer rate.
-- Feature Reference: F101
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.fedwire_routing_rules (
    -- Primary Key
    routing_number VARCHAR(9) PRIMARY KEY, -- The RTN

    -- Attributes
    bank_name VARCHAR(255) NOT NULL,
    office_code CHAR(1) CHECK (office_code IN ('0', '1', '2')), -- Main office or branch
    servicer_frb_number VARCHAR(9), -- Federal Reserve Bank Servicer
    record_type_code CHAR(1), -- 0 for Fedwire
    revision_date DATE,

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.fedwire_routing_rules IS 'Validation rules for US Fedwire routing numbers';

------------------------------------------------------------------------------------------------
-- Table: T102 - chips_uid_rules
-- Description: Configuration rules for validating CHIPS UIDs (Clearing House Interbank Payments System).
-- Business Case: CHIPS handles a large percentage of USD international payments. Unlike Fedwire,
-- CHIPS uses a UID (Universal Identifier). This table stores the mapping and validation rules
-- for CHIPS UIDs to ensure that large-value interbank payments are routed correctly through
-- this private clearing system.
-- KPIs: CHIPS routing success rate.
-- Feature Reference: F102
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.chips_uid_rules (
    -- Primary Key
    uid VARCHAR(6) PRIMARY KEY, -- CHIPS UID is typically 6 digits

    -- Attributes
    participant_name VARCHAR(255) NOT NULL,
    status VARCHAR(20) CHECK (status IN ('ACTIVE', 'INACTIVE', 'SUSPENDED')),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.chips_uid_rules IS 'Validation rules for CHIPS UIDs';

------------------------------------------------------------------------------------------------
-- Table: T103 - ifsc_validation_rules
-- Description: Configuration rules for validating Indian IFSC codes.
-- Business Case: The Indian Financial System Code (IFSC) is an 11-character alphanumeric code
-- used by NEFT and RTGS. This table stores the valid bank codes and branch codes to validate
-- that an IFSC exists and corresponds to the correct bank, preventing transfers to invalid
-- Indian branches.
-- KPIs: Indian payment routing accuracy.
-- Feature Reference: F103
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.ifsc_validation_rules (
    -- Primary Key
    ifsc_code CHAR(11) PRIMARY KEY, -- 4 letters (Bank) + 0 + 6 digits (Branch)

    -- Attributes
    bank_name VARCHAR(255) NOT NULL,
    bank_code CHAR(4) NOT NULL,
    branch_name VARCHAR(255) NOT NULL,
    branch_code VARCHAR(7) NOT NULL,
    address TEXT,
    city VARCHAR(100),
    district VARCHAR(100),
    state VARCHAR(100),

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.ifsc_validation_rules IS 'Validation rules for Indian IFSC codes';
CREATE INDEX idx_ifsc_bank_code ON core.ifsc_validation_rules(bank_code);

------------------------------------------------------------------------------------------------
-- Table: T104 - uk_sort_code_rules
-- Description: Configuration rules for validating UK sort codes.
-- Business Case: UK sort codes are 6-digit numbers identifying the bank and branch. This table
-- validates the existence of a sort code to ensure Faster Payments or BACS transfers are
-- routed to a valid UK banking institution.
-- KPIs: UK payment routing success rate.
-- Feature Reference: F104
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.uk_sort_code_rules (
    -- Primary Key
    sort_code CHAR(6) PRIMARY KEY,

    -- Attributes
    bank_name VARCHAR(255) NOT NULL,
    branch_name VARCHAR(255) NOT NULL,
    settlement_bank VARCHAR(50), -- Bank of England, Barclays, etc.
    bacs_status VARCHAR(20),

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.uk_sort_code_rules IS 'Validation rules for UK Sort Codes';

------------------------------------------------------------------------------------------------
-- Table: T105 - uk_account_modulus_rules
-- Description: Rules for performing modulus checks on UK account numbers.
-- Business Case: UK banking relies heavily on Modulus Weighting algorithms to validate the
-- mathematical integrity of an Account Number against its Sort Code. This table stores the
-- weights and exceptions (e.g., Mod 10, Mod 11, DBLAL) required to perform the
-- calculations in F105.
-- KPIs: Account validation accuracy.
-- Feature Reference: F105
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.uk_account_modulus_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Sort Code Range (or specific code)
    sort_code_start CHAR(6),
    sort_code_end CHAR(6),

    -- Algorithm Details
    modulus_algorithm VARCHAR(10) NOT NULL, -- 'MOD10', 'MOD11'
    weightings INTEGER[] NOT NULL, -- Array of weights (usually 14 digits)
    exception INTEGER DEFAULT 0, -- Exception code

    -- Constraints
    CONSTRAINT uk_modulus_range_check CHECK (sort_code_end >= sort_code_start),
    EXCLUDE USING gist (int4range(sort_code_start::BIGINT, sort_code_end::BIGINT) WITH &&)
);

COMMENT ON TABLE core.uk_account_modulus_rules IS 'Modulus weighting rules for UK Account Number validation';

------------------------------------------------------------------------------------------------
-- Table: T106 - australian_bsb_rules
-- Description: Configuration rules for validating Australian BSB (Bank-State-Branch) numbers.
-- Business Case: BSB is a 6-digit code used in Australia for routing payments. This table
-- validates BSB codes to ensure they map to valid financial institutions and states,
-- preventing failed payments in the Australian banking network (BPAY/NPP).
-- KPIs: Australian payment routing accuracy.
-- Feature Reference: F106
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.australian_bsb_rules (
    -- Primary Key
    bsb_code CHAR(6) PRIMARY KEY,

    -- Attributes
    bank_name VARCHAR(255) NOT NULL,
    branch_name VARCHAR(255),
    state VARCHAR(50), -- NSW, VIC, QLD, etc.
    post_code VARCHAR(10),
    suburb VARCHAR(100),

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.australian_bsb_rules IS 'Validation rules for Australian BSB codes';

------------------------------------------------------------------------------------------------
-- Table: T107 - canadian_transit_rules
-- Description: Configuration rules for validating Canadian transit numbers.
-- Business Case: Canadian transit numbers identify the specific branch where an account is held.
-- This table validates the 5-digit transit code to ensure funds are routed correctly within
-- the Canadian financial system (EFT/Interac).
-- KPIs: Canadian payment routing accuracy.
-- Feature Reference: F107
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.canadian_transit_rules (
    -- Primary Key
    transit_number VARCHAR(5) PRIMARY KEY,

    -- Attributes
    bank_name VARCHAR(255) NOT NULL,
    branch_address TEXT,
    city VARCHAR(100),
    province VARCHAR(50),

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.canadian_transit_rules IS 'Validation rules for Canadian transit numbers';

------------------------------------------------------------------------------------------------
-- Table: T108 - mexican_clabe_rules
-- Description: Configuration rules for validating Mexican CLABE numbers (18 digits).
-- Business Case: CLABE (Clave Bancaria Estandarizada) is required for interbank transfers in Mexico.
-- This table validates the structure and calculates the control digit (Modulo 11) to ensure
-- the account number is mathematically valid before initiating a SPEI transfer.
-- KPIs: Mexican payment routing accuracy.
-- Feature Reference: F043, F108
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.mexican_clabe_rules (
    -- Primary Key
    bank_code CHAR(3) PRIMARY KEY, -- The first 3 digits of CLABE

    -- Attributes
    bank_name VARCHAR(255) NOT NULL,
    city VARCHAR(100),
    state VARCHAR(50),

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.mexican_clabe_rules IS 'Validation rules for Mexican CLABE bank codes';

------------------------------------------------------------------------------------------------
-- Table: T109 - argentine_cbu_rules
-- Description: Configuration rules for validating Argentine CBU (Clave Bancaria Uniforme).
-- Business Case: CBU is a 22-digit code used for identifying bank accounts in Argentina. This
-- table stores the logic for validating the check digit (Modulo 10) to ensure the CBU
-- corresponds to a valid account, preventing failed transfers within the Argentine system.
-- KPIs: Argentine payment routing accuracy.
-- Feature Reference: F043, F109
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.argentine_cbu_rules (
    -- Primary Key
    bank_code CHAR(3) PRIMARY KEY, -- First 3 digits of CBU identify the bank

    -- Attributes
    bank_name VARCHAR(255) NOT NULL,

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.argentine_cbu_rules IS 'Validation rules for Argentine CBU bank codes';

------------------------------------------------------------------------------------------------
-- Table: T110 - brazil_pix_key_rules
-- Description: Configuration rules for validating Brazilian PIX keys (CPF, CNPJ, Email, Phone).
-- Business Case: PIX is the instant payment system in Brazil. Keys can be various formats
-- (random string, phone, email). This table stores the regex and validation logic for each
-- key type (e.g., validating CPF checksum, checking if email is disposable), ensuring that
-- instant payments reach the correct recipient.
-- KPIs: PIX transaction success rate.
-- Feature Reference: F110
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.brazil_pix_key_rules (
    -- Primary Key
    key_type VARCHAR(20) PRIMARY KEY CHECK (key_type IN ('CPF', 'CNPJ', 'PHONE', 'EMAIL', 'RANDOM'))

    -- Attributes
    validation_regex TEXT NOT NULL,
    checksum_algorithm VARCHAR(20), -- 'MOD11' for CPF
    length_constraint INTEGER, -- For Random keys

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.brazil_pix_key_rules IS 'Validation rules for Brazilian PIX keys';

------------------------------------------------------------------------------------------------
-- Table: T111 - mexican_spei_rules
-- Description: Configuration rules for validating SPEI account specifics.
-- Business Case: SPEI (Sistema de Pagos Electrónicos Interbancarios) relies on the CLABE
-- but may have specific formatting rules for participating institutions. This table stores
-- any additional validation or restrictions specific to SPEI processing beyond standard CLABE
-- checks.
-- KPIs: SPEI message reject rate.
-- Feature Reference: F111
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.mexican_spei_rules (
    -- Primary Key
    bank_code CHAR(3) PRIMARY KEY REFERENCES core.mexican_clabe_rules(bank_code),

    -- Attributes
    spei_participant_code VARCHAR(10),
    is_direct_participant BOOLEAN DEFAULT false,

    -- Constraints
    spei_validation_json JSONB, -- Specific overrides

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.mexican_spei_rules IS 'Additional validation rules for Mexican SPEI participants';

------------------------------------------------------------------------------------------------
-- Table: T112 - nigerian_nuban_rules
-- Description: Configuration rules for validating Nigerian NUBAN numbers.
-- Business Case: NUBAN (Nigeria Uniform Bank Account Number) is a 10-digit code used for
-- electronic payments in Nigeria. This table stores the bank codes and helps calculate the
-- check digit (Modulo 10 algorithm) to ensure account validity.
-- KPIs: Nigerian payment routing accuracy.
-- Feature Reference: F112
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.nigerian_nuban_rules (
    -- Primary Key
    bank_code CHAR(3) PRIMARY KEY,

    -- Attributes
    bank_name VARCHAR(255) NOT NULL,

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.nigerian_nuban_rules IS 'Validation rules for Nigerian NUBAN bank codes';

------------------------------------------------------------------------------------------------
-- Table: T113 - uk_bank_account_combo_check
-- Description: Valid combinations of UK Sort Codes and Account Number formats.
-- Business Case: While Modulus checks (F105) handle math, some banks have specific non-standard
-- account number lengths (e.g., 7, 8, or 9 digits) based on the Sort Code. This table provides
-- the definitive source for "Is this account number length valid for this sort code?",
-- catching structural errors that pass modulus checks but fail at the bank.
-- KPIs: UK validation precision.
-- Feature Reference: F113
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.uk_bank_account_combo_check (
    -- Primary Key
    sort_code_start CHAR(6) NOT NULL,
    sort_code_end CHAR(6) NOT NULL,
    account_length INTEGER NOT NULL,

    -- Attributes
    weight_table CHAR(2), -- Reference to specific weight set
    exception_code INTEGER,

    -- Constraints
    CONSTRAINT uk_combo_primary UNIQUE (sort_code_start, sort_code_end, account_length),
    CONSTRAINT uk_combo_range CHECK (sort_code_end >= sort_code_start)
);

COMMENT ON TABLE core.uk_bank_account_combo_check IS 'Valid Sort Code and Account Number length combinations';

------------------------------------------------------------------------------------------------
-- Table: T114 - pan_luhn_config
-- Description: Configuration for validating Primary Account Numbers (PAN) using Luhn algorithm.
-- Business Case: While the Luhn algorithm is standard, its application varies slightly across
-- card issuers. This table configures the strictness of the Luhn check and handles edge cases
-- where specific card BINs might not follow standard Luhn (rare but possible in closed loop
-- systems).
-- KPIs: Card validation error rate.
-- Feature Reference: F114
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.pan_luhn_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Config
    apply_luhn_check BOOLEAN NOT NULL DEFAULT true,
    allow_test_numbers BOOLEAN DEFAULT false, -- Allow '4242...'

    -- Exception Ranges
    bin_range_exception_start VARCHAR(16),
    bin_range_exception_end VARCHAR(16),

    -- Constraints
    EXCLUDE USING gist (int4range(bin_range_exception_start::BIGINT, bin_range_exception_end::BIGINT) WITH &&)
);

COMMENT ON TABLE core.pan_luhn_config IS 'Configuration for PAN Luhn algorithm validation';

------------------------------------------------------------------------------------------------
-- Table: T115 - card_expiry_config
-- Description: Configuration for validating card expiry dates.
-- Business Case: Ensures that card expiry dates are logically sound (not in the past) and not
-- unreasonably far in the future (which could indicate fraud or a typo). This table
-- defines the maximum allowable months into the future.
-- KPIs: Card validation precision.
-- Feature Reference: F115
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.card_expiry_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    allow_past_dates BOOLEAN DEFAULT false,
    max_months_future INTEGER NOT NULL DEFAULT 120, -- 10 years cap
    warning_months_threshold INTEGER DEFAULT 6 -- Warn if expiring soon
);

COMMENT ON TABLE core.card_expiry_config IS 'Configuration for card expiry date validation';

------------------------------------------------------------------------------------------------
-- Table: T116 - card_cvv_config
-- Description: Configuration for validating Card Verification Value (CVV) codes.
-- Business Case: CVV length varies by brand (3 for Visa/MC, 4 for Amex). This table maps
-- card brands to their expected CVV lengths and validates that the input matches the card
-- type, preventing authorization failures due to mismatched security codes.
-- KPIs: Authorization success rate.
-- Feature Reference: F116
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.card_cvv_config (
    -- Primary Key
    brand VARCHAR(50) PRIMARY KEY, -- References E008

    -- Attributes
    cvv_length INTEGER NOT NULL, -- 3 or 4
    cvv_label VARCHAR(10) -- CVV2, CVC, CID
);

COMMENT ON TABLE core.card_cvv_config IS 'Configuration for CVV length per card brand';

------------------------------------------------------------------------------------------------
-- Table: T117 - card_mii_ranges
-- Description: Major Industry Identifier (MII) ranges for card validation.
-- Business Case: The first digit of a card number identifies the industry (Airlines, Banking,
-- Government). This table stores these mappings. Validating MII helps catch typos (e.g.,
-- entering a credit card number starting with 3, which is Travel/Entertainment, into a
-- banking system).
-- KPIs: Card type detection accuracy.
-- Feature Reference: F117
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.card_mii_ranges (
    -- Primary Key
    mii_digit CHAR(1) PRIMARY KEY,

    -- Attributes
    industry_category VARCHAR(100) NOT NULL, -- e.g., 'Airlines', 'Banking and Financial'
    description TEXT
);

COMMENT ON TABLE core.card_mii_ranges IS 'Major Industry Identifier ranges';

------------------------------------------------------------------------------------------------
-- Table: T118 - card_brand_identification
-- Description: Logic for identifying card brands from the PAN.
-- Business Case: This table provides the rules (prefix ranges) to identify if a card is
-- Visa, Mastercard, Amex, etc. This is critical for routing the transaction to the correct
-- processor (F118).
-- KPIs: Routing accuracy.
-- Feature Reference: F118
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.card_brand_identification (
    -- Primary Key
    id SERIAL PRIMARY KEY,

    -- Attributes
    brand core.enum_card_brand NOT NULL,
    prefix_start VARCHAR(6) NOT NULL,
    prefix_end VARCHAR(6),
    card_length INTEGER NOT NULL,

    -- Constraints
    CONSTRAINT brand_range_check CHECK (prefix_end >= prefix_start),
    EXCLUDE USING gist (int4range(prefix_start::BIGINT, prefix_end::BIGINT) WITH &&)
);

COMMENT ON TABLE core.card_brand_identification IS 'Rules for identifying card brand from BIN/PAN';

------------------------------------------------------------------------------------------------
-- Table: T119 - card_3ds_versions_config
-- Description: Configuration for allowed 3D Secure protocol versions.
-- Business Case: 3D Secure (3DS) protocol versions have evolved (1.0 to 2.x). PSD2 mandates
-- 3DS 2.0 for SCA compliance, but some regions might still support 1.0. This table
-- configures which versions are accepted per card brand or region.
-- KPIs: SCA compliance rate.
-- Feature Reference: F119
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.card_3ds_versions_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Config
    version VARCHAR(10) NOT NULL CHECK (version IN ('1.0.2', '2.1.0', '2.2.0')),
    is_mandatory BOOLEAN DEFAULT false,
    supported_message_versions TEXT[]
);

COMMENT ON TABLE core.card_3ds_versions_config IS 'Configuration for allowed 3DS versions';

------------------------------------------------------------------------------------------------
-- Table: T120 - emv_cryptogram_validation
-- Description: Validation rules for EMV cryptograms (ARQC/ARPC).
-- Business Case: EMV cryptograms are generated by the chip card to prove possession of the
-- card. This table defines the expected format and length of these cryptograms (usually
-- binary strings represented as Hex) to ensure they haven't been tampered with during
-- transmission to the processor.
-- KPIs: POS authentication success rate.
-- Feature Reference: F120
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.emv_cryptogram_validation (
    -- Primary Key
    cryptogram_type VARCHAR(20) PRIMARY KEY, -- 'ARQC', 'ARPC', 'AAC', 'TC'

    -- Attributes
    expected_length INTEGER NOT NULL, -- In bytes
    encoding VARCHAR(10) DEFAULT 'HEX'
);

COMMENT ON TABLE core.emv_cryptogram_validation IS 'Rules for validating EMV cryptogram formats';

------------------------------------------------------------------------------------------------
-- Table: T121 - nfc_ndef_record_rules
-- Description: Validation rules for NFC Data Exchange Format (NDEF) records.
-- Business Case: Contactless payments use NDEF records to encapsulate payment data. This
-- table defines the valid TNF (Type Name Format) and payload structures for NDEF records
-- to ensure they are readable and compliant with NFC Forum standards.
-- KPIs: Contactless transaction success rate.
-- Feature Reference: F121
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.nfc_ndef_record_rules (
    -- Primary Key
    record_type_name VARCHAR(50) PRIMARY KEY, -- e.g., 'Sp', 'U', 'T'

    -- Attributes
    tnf_value SMALLINT NOT NULL, -- Type Name Format (0-6)
    payload_format_rule TEXT
);

COMMENT ON TABLE core.nfc_ndef_record_rules IS 'Validation rules for NFC NDEF records';

------------------------------------------------------------------------------------------------
-- Table: T122 - loyalty_card_formats
-- Description: Formats and validation logic for proprietary loyalty card numbers.
-- Business Case: Merchants often use custom numbering schemes for loyalty programs. This
-- table stores the regex and length rules for these proprietary formats so the PARI system
-- can accept and validate them correctly without hardcoding merchant-specific logic.
-- KPIs: Loyalty transaction success rate.
-- Feature Reference: F122
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.loyalty_card_formats (
    -- Primary Key
    merchant_id UUID NOT NULL,
    card_format_name VARCHAR(100),
    PRIMARY KEY (merchant_id, card_format_name),

    -- Attributes
    validation_regex TEXT NOT NULL,
    check_digit_algorithm VARCHAR(50),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.loyalty_card_formats IS 'Formats for proprietary loyalty cards';

------------------------------------------------------------------------------------------------
-- Table: T123 - gift_card_pin_formats
-- Description: Validation rules for Gift Card PINs.
-- Business Case: Gift cards often require a PIN for redemption. This table defines the
-- allowed formats (numeric length, alphanumeric) for these PINs to ensure they match
-- the issuer's generation algorithm, preventing validation errors at checkout.
-- KPIs: Gift card redemption success rate.
-- Feature Reference: F123
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.gift_card_pin_formats (
    -- Primary Key
    card_program_id VARCHAR(50) NOT NULL,

    -- Attributes
    pin_length INTEGER NOT NULL,
    pin_type VARCHAR(20) CHECK (pin_type IN ('NUMERIC', 'ALPHANUMERIC')),
    blocked_patterns TEXT[], -- e.g., '0000', '1234'

    PRIMARY KEY (card_program_id, pin_length)
);

COMMENT ON TABLE core.gift_card_pin_formats IS 'Validation rules for Gift Card PINs';

------------------------------------------------------------------------------------------------
-- Table: T124 - voucher_code_patterns
-- Description: Validation patterns for promotional voucher codes.
-- Business Case: Voucher codes often follow specific patterns (e.g., prefix for campaign).
-- This table stores the regex for these patterns. Validating against this table ensures that
-- invalid codes (typos or hallucinated codes) are rejected immediately, saving database
-- lookups against the actual voucher table (T045).
-- KPIs: Voucher validation efficiency.
-- Feature Reference: F124
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.voucher_code_patterns (
    -- Primary Key
    campaign_id VARCHAR(50) NOT NULL,

    -- Attributes
    pattern_regex TEXT NOT NULL,
    example_code VARCHAR(50),

    PRIMARY KEY (campaign_id, pattern_regex)
);

COMMENT ON TABLE core.voucher_code_patterns IS 'Regex patterns for promotional vouchers';

------------------------------------------------------------------------------------------------
-- Table: T125 - receipt_hash_config
-- Description: Configuration for validating digital receipt hashes.
-- Business Case: Digital receipts are often hashed for integrity checks (F125). This table
-- stores the allowed hashing algorithms (e.g., SHA-256) and format (Hex vs Base64) to ensure
-- that the hash received can be recomputed and matched successfully for dispute resolution.
-- KPIs: Dispute resolution success rate.
-- Feature Reference: F125
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.receipt_hash_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Attributes
    algorithm VARCHAR(20) NOT NULL REFERENCES core.crypto_algorithms_whitelist(algo_name),
    output_encoding VARCHAR(10) CHECK (output_encoding IN ('HEX', 'BASE64')),
    length INTEGER NOT NULL
);

COMMENT ON TABLE core.receipt_hash_config IS 'Configuration for receipt hash validation';

------------------------------------------------------------------------------------------------
-- Table: T126 - timestamp_sync_config
-- Description: Configuration for validating client-server timestamp synchronization.
-- Business Case: Clients with skewed clocks can cause replay attacks or ordering issues.
-- This table defines the maximum allowable drift (in seconds) between the client's timestamp
-- and the server's timestamp, rejecting requests that fall outside this window (F126).
-- KPIs: Replay attack prevention.
-- Feature Reference: F126
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.timestamp_sync_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    max_drift_seconds INTEGER NOT NULL DEFAULT 300, -- 5 minutes
    allow_future_timestamps BOOLEAN DEFAULT false,
    max_future_seconds INTEGER DEFAULT 0
);

COMMENT ON TABLE core.timestamp_sync_config IS 'Configuration for timestamp drift validation';

------------------------------------------------------------------------------------------------
-- Table: T127 - idempotency_config
-- Description: Configuration for validating Idempotency Key formats.
-- Business Case: Idempotency Keys ensure safe retries. This table defines the valid formats
-- (e.g., must be a UUID v4, or a specific string pattern) for these keys (F127), preventing
-- clients from using malformed keys that fail to deduplicate correctly.
-- KPIs: Duplicate processing prevention.
-- Feature Reference: F127
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.idempotency_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    key_format VARCHAR(20) NOT NULL CHECK (key_format IN ('UUID_V4', 'UUID_V1', 'CUSTOM_ALPHANUM')),
    custom_regex TEXT,
    key_expiration_hours INTEGER NOT NULL DEFAULT 24
);

COMMENT ON TABLE core.idempotency_config IS 'Configuration for idempotency key validation';

------------------------------------------------------------------------------------------------
-- Table: T128 - pagination_config
-- Description: Configuration for validating API pagination tokens.
-- Business Case: Pagination prevents data overload. This table validates the format of
-- pagination cursors or tokens (F128) to ensure they are signed or encoded correctly and
-- not tampered with by the client.
-- KPIs: API security.
-- Feature Reference: F128
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.pagination_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    token_type VARCHAR(20) NOT NULL CHECK (token_type IN ('CURSOR', 'OFFSET_LIMIT', 'NEXT_PAGE_TOKEN')),
    encoding VARCHAR(20) DEFAULT 'BASE64',
    signature_required BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.pagination_config IS 'Configuration for pagination token validation';

------------------------------------------------------------------------------------------------
-- Table: T129 - api_sort_whitelist
-- Description: Allowed columns for sorting API results.
-- Business Case: Prevents SQL injection via sort parameters (ORDER BY). This table defines
-- which columns are safe to sort by (F129). Any request attempting to sort by a column not
-- in this list is rejected.
-- KPIs: API security incident count.
-- Feature Reference: F129
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.api_sort_whitelist (
    -- Primary Key
    endpoint_path VARCHAR(255) NOT NULL,
    column_name VARCHAR(100) NOT NULL,

    -- Attributes
    column_type VARCHAR(20), -- 'TEXT', 'NUMERIC', 'DATE'
    default_direction VARCHAR(4) CHECK (default_direction IN ('ASC', 'DESC')),

    PRIMARY KEY (endpoint_path, column_name)
);

COMMENT ON TABLE core.api_sort_whitelist IS 'Allowed columns for API sorting (SQLi prevention)';

------------------------------------------------------------------------------------------------
-- Table: T130 - api_field_whitelist
-- Description: Allowed fields for sparse fieldset projection (GraphQL style).
-- Business Case: Clients often request only specific fields to reduce bandwidth. This table
-- (F130) defines which fields are "public" and allowed to be requested. Trying to request
-- sensitive fields (like internal IDs or PII) that aren't whitelisted results in rejection.
-- KPIs: Data leakage prevention.
-- Feature Reference: F130
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.api_field_whitelist (
    -- Primary Key
    resource_name VARCHAR(100) NOT NULL,
    field_name VARCHAR(100) NOT NULL,

    -- Attributes
    is_public BOOLEAN DEFAULT false,
    requires_scope TEXT[],

    PRIMARY KEY (resource_name, field_name)
);

COMMENT ON TABLE core.api_field_whitelist IS 'Allowed fields for sparse fieldsets';

------------------------------------------------------------------------------------------------
-- Table: T131 - webhook_url_security_rules
-- Description: Security rules for validating webhook URLs.
-- Business Case: Ensures webhooks are sent to secure endpoints. This table (F131) enforces
-- rules such as "Must be HTTPS", "Cannot be localhost", or "Cannot be private IP range",
-- preventing data exfiltration or insecure transmissions.
-- KPIs: Data security compliance.
-- Feature Reference: F131
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.webhook_url_security_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    require_https BOOLEAN DEFAULT true,
    allow_private_ip BOOLEAN DEFAULT false,
    blocked_domains TEXT[], -- e.g., 'internal.local'
    max_url_length INTEGER DEFAULT 2048
);

COMMENT ON TABLE core.webhook_url_security_rules IS 'Security rules for Webhook URLs';

------------------------------------------------------------------------------------------------
-- Table: T132 - webhook_signature_algos
-- Description: Supported algorithms for webhook signature verification.
-- Business Case: Verifies that webhook payloads actually came from the merchant (F132).
-- This table lists supported HMAC algorithms (e.g., SHA-256) to match the hash header sent
-- by the client.
-- KPIs: Webhook spoofing prevention.
-- Feature Reference: F132
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.webhook_signature_algos (
    -- Primary Key
    algo_name VARCHAR(20) PRIMARY KEY REFERENCES core.crypto_algorithms_whitelist(algo_name),

    -- Attributes
    signature_header_name VARCHAR(50), -- e.g., 'X-Signature'
    requires_base64_decoding BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.webhook_signature_algos IS 'Supported algorithms for webhook signatures';

------------------------------------------------------------------------------------------------
-- Table: T133 - api_scope_definitions
-- Description: Definitions and hierarchy of API scopes.
-- Business Case: Scopes define permissions (F133). This table defines what each scope means,
-- its description, and if it implies other scopes (e.g., 'admin' implies 'read'). This aids
-- in validating if an API key has sufficient rights for an endpoint.
-- KPIs: Authorization accuracy.
-- Feature Reference: F133
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.api_scope_definitions (
    -- Primary Key
    scope_name VARCHAR(100) PRIMARY KEY,

    -- Attributes
    description TEXT,
    implies_scopes TEXT[], -- Auto-inherits these scopes
    requires_tenant BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.api_scope_definitions IS 'Definitions of API scopes for authorization';

------------------------------------------------------------------------------------------------
-- Table: T134 - api_quota_rules
-- Description: Quota limits per API plan or endpoint.
-- Business Case: Prevents abuse and manages load (F134). This table defines the limits
-- (requests per day/month) associated with different API keys or plans. The validation layer
-- checks counters against these rules to throttle over-usage.
-- KPIs: API abuse prevention.
-- Feature Reference: F134
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.api_quota_rules (
    -- Primary Key
    plan_name VARCHAR(50) NOT NULL,
    resource_type VARCHAR(50) NOT NULL, -- 'GLOBAL', 'STORAGE', 'COMPUTE'
    PRIMARY KEY (plan_name, resource_type),

    -- Attributes
    limit_per_hour INTEGER,
    limit_per_day INTEGER,
    limit_per_month INTEGER,

    -- Constraints
    CONSTRAINT quota_positive_limit CHECK (
        (limit_per_hour IS NOT NULL AND limit_per_hour > 0) OR
        (limit_per_day IS NOT NULL AND limit_per_day > 0) OR
        (limit_per_month IS NOT NULL AND limit_per_month > 0)
    )
);

COMMENT ON TABLE core.api_quota_rules IS 'Quota rules per API plan';

------------------------------------------------------------------------------------------------
-- Table: T135 - tenant_id_config
-- Description: Configuration for validating Tenant ID formats.
-- Business Case: In a multi-tenant SaaS model, the Tenant ID is crucial for isolation.
-- This table (F135) defines the valid format (e.g., must be a UUID, or a specific string
-- prefix) for Tenant IDs, preventing cross-tenant data access via malformed IDs.
-- KPIs: Tenant isolation integrity.
-- Feature Reference: F135
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.tenant_id_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    id_format VARCHAR(20) NOT NULL CHECK (id_format IN ('UUID_V4', 'UUID_V5', 'CUSTOM')),
    custom_validation_regex TEXT,
    reserved_ids TEXT[] -- e.g., 'common', 'system'
);

COMMENT ON TABLE core.tenant_id_config IS 'Configuration for Tenant ID format validation';

------------------------------------------------------------------------------------------------
-- Table: T136 - trace_id_config
-- Description: Configuration for validating distributed tracing IDs.
-- Business Case: Trace IDs (F136) link requests across microservices. This table defines the
-- expected format (e.g., W3C Trace Context format) to ensure that tracing instrumentation
-- is functioning correctly and IDs are valid.
-- KPIs: Observability coverage.
-- Feature Reference: F136
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.trace_id_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    format_standard VARCHAR(20) DEFAULT 'W3C', -- W3C Trace Context
    expected_length INTEGER DEFAULT 32, -- Hex chars
    encoding VARCHAR(10) DEFAULT 'HEX'
);

COMMENT ON TABLE core.trace_id_config IS 'Configuration for Trace ID validation';

------------------------------------------------------------------------------------------------
-- Table: T137 - span_id_config
-- Description: Configuration for validating Parent Span IDs.
-- Business Case: Span IDs identify individual operations within a trace. This table (F137)
-- defines the format and length (usually 64-bit Hex) to ensure that the parent-child
-- relationship in the trace tree is valid.
-- KPIs: Observability reliability.
-- Feature Reference: F137
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.span_id_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    expected_length INTEGER DEFAULT 16, -- 64-bit Hex
    encoding VARCHAR(10) DEFAULT 'HEX',
    allow_zero_id BOOLEAN DEFAULT false -- 0000... is usually invalid as a real ID
);

COMMENT ON TABLE core.span_id_config IS 'Configuration for Span ID validation';

------------------------------------------------------------------------------------------------
-- Table: T138 - logging_level_config
-- Description: Valid log levels and their hierarchy.
-- Business Case: Validates log levels in configuration or API requests (F138). Ensures that
-- only standard levels (DEBUG, INFO, WARN, ERROR) are used, which is critical for log parsing
-- and alerting systems.
-- KPIs: Logging reliability.
-- Feature Reference: F138
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.logging_level_config (
    -- Primary Key
    level_name VARCHAR(20) PRIMARY KEY, -- DEBUG, INFO, WARN, ERROR, FATAL

    -- Attributes
    severity_rank INTEGER NOT NULL UNIQUE, -- DEBUG=10, INFO=20... Used for comparison
    is_verbose BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.logging_level_config IS 'Configuration for valid log levels';

------------------------------------------------------------------------------------------------
-- Table: T139 - metric_naming_conventions
-- Description: Rules for naming metrics (Prometheus/StatsD).
-- Business Case: Metrics need to be consistent to be queryable. This table (F139) defines
-- the regex for valid metric names (e.g., snake_case, specific prefixes), preventing the
-- creation of unqueryable or messy metric data.
-- KPIs: Monitoring data quality.
-- Feature Reference: F139
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.metric_naming_conventions (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    format_regex TEXT NOT NULL, -- e.g., '^[a-zA-Z_:][a-zA-Z0-9_:]*$'
    reserved_prefixes TEXT[] -- e.g., '__internal', 'temp_'
);

COMMENT ON TABLE core.metric_naming_conventions IS 'Rules for metric naming conventions';

------------------------------------------------------------------------------------------------
-- Table: T140 - alert_severity_rules
-- Description: Valid alert severity levels.
-- Business Case: Categorizes alerts to drive the right response (F140). This table defines
-- levels (Info, Warning, Critical) and mapping to notification channels (e.g., Email for
-- Warning, PagerDuty for Critical).
-- KPIs: Alert MTTR (Mean Time To Resolve).
-- Feature Reference: F140
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.alert_severity_rules (
    -- Primary Key
    level_name VARCHAR(50) PRIMARY KEY,

    -- Attributes
    rank INTEGER NOT NULL UNIQUE,
    auto_resolve_hours INTEGER,
    notification_channel_types TEXT[], -- e.g., {'EMAIL', 'SLACK', 'SMS'}
);

COMMENT ON TABLE core.alert_severity_rules IS 'Definition of alert severity levels';

------------------------------------------------------------------------------------------------
-- Table: T141 - application_config_schemas
-- Description: JSON Schemas for validating application configuration at startup.
-- Business Case: Invalid configuration can crash applications at startup (F141). This table
-- stores the JSON Schema for application configs. The boot process validates the config
-- JSON against this schema before starting.
-- KPIs: Application uptime.
-- Feature Reference: F141
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.application_config_schemas (
    -- Primary Key
    app_name VARCHAR(100) NOT NULL,
    config_version VARCHAR(20) NOT NULL,
    PRIMARY KEY (app_name, config_version),

    -- Attributes
    json_schema JSONB NOT NULL,
    is_default BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.application_config_schemas IS 'JSON Schemas for application configuration validation';

------------------------------------------------------------------------------------------------
-- Table: T142 - feature_flag_naming_rules
-- Description: Naming conventions for feature flags.
-- Business Case: Ensures feature flags are named consistently (F142) so they are discoverable
-- and manageable. This table defines the regex (e.g., `feature_toggles_<module>_<name>`) to
-- prevent arbitrary or confusing flag names.
-- KPIs: Feature flag manageability.
-- Feature Reference: F142
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.feature_flag_naming_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    allowed_prefixes TEXT[], -- e.g., {'merchant', 'payment', 'ui'}
    max_length INTEGER DEFAULT 100,
    forbidden_words TEXT[] -- e.g., {'test', 'delete', 'kill'}
);

COMMENT ON TABLE core.feature_flag_naming_rules IS 'Naming rules for feature flags';

------------------------------------------------------------------------------------------------
-- Table: T143 - ab_test_bucket_logic
-- Description: Logic for A/B test bucket validation.
-- Business Case: Validates that a user falls into a valid bucket (F143). This table defines
-- the hash modulus (e.g., mod 100 for 100 buckets) and ensures that the bucket ID requested
-- by the client falls within the valid range.
-- KPIs: A/B testing integrity.
-- Feature Reference: F143
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.ab_test_bucket_logic (
    -- Primary Key
    experiment_name VARCHAR(100) NOT NULL,

    -- Attributes
    bucket_count INTEGER NOT NULL,
    bucketing_algorithm VARCHAR(50) DEFAULT 'MOD_HASH',

    -- State
    is_active BOOLEAN DEFAULT true,
    PRIMARY KEY (experiment_name, is_active)
);

COMMENT ON TABLE core.ab_test_bucket_logic IS 'Logic for A/B test bucket assignment';

------------------------------------------------------------------------------------------------
-- Table: T144 - experiment_cohort_rules
-- Description: Validation rules for experiment cohort membership.
-- Business Case: Ensures that only valid cohorts (F144) are assigned to experiments. This table
-- defines the criteria (e.g., `country = 'US' AND `tier = 'PREMIUM'`) which the validation
-- layer checks to ensure the user's cohort is valid for the experiment they are being
-- targeted by.
-- KPIs: Experiment targeting accuracy.
-- Feature Reference: F144
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.experiment_cohort_rules (
    -- Primary Key
    cohort_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Attributes
    cohort_name VARCHAR(100) NOT NULL,
    logic_criteria JSONB NOT NULL, -- e.g., {"tier": "PREMIUM"}

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.experiment_cohort_rules IS 'Rules for validating experiment cohorts';

------------------------------------------------------------------------------------------------
-- Table: T145 - user_agent_validation_rules
-- Description: Rules for validating User-Agent strings.
-- Business Case: Basic sanity check on User-Agents (F145). While T51 handles bots, this table
-- enforces structural rules (e.g., minimum length, containing a browser name) to reject
-- malformed or script-generated User-Agents.
-- KPIs: API hygiene.
-- Feature Reference: F145
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.user_agent_validation_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    min_length INTEGER DEFAULT 10,
    max_length INTEGER DEFAULT 500,
    required_patterns TEXT[] -- e.g., {'Mozilla/', 'Chrome', 'Safari'}
);

COMMENT ON TABLE core.user_agent_validation_rules IS 'Basic validation rules for User-Agent strings';

------------------------------------------------------------------------------------------------
-- Table: T146 - content_language_rules
-- Description: Validation rules for Accept-Language headers.
-- Business Case: Ensures that the client's requested language is supported (F146). This table
-- maps allowed language codes (e.g., 'en-US', 'es-ES') to supported locales, rejecting
-- requests for languages the platform doesn't support.
-- KPIs: Localization accuracy.
-- Feature Reference: F146
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.content_language_rules (
    -- Primary Key
    language_tag VARCHAR(20) PRIMARY KEY, -- e.g., 'en-US', 'fr'

    -- Attributes
    is_native_supported BOOLEAN DEFAULT false,
    fallback_language_tag VARCHAR(20) REFERENCES core.content_language_rules(language_tag)
);

COMMENT ON TABLE core.content_language_rules IS 'Rules for validating Accept-Language headers';

------------------------------------------------------------------------------------------------
-- Table: T147 - accept_encoding_rules
-- Description: Validation rules for Accept-Encoding headers.
-- Business Case: Ensures the server and client agree on compression (F147). This table defines
-- supported encodings (GZIP, BR, DEFLATE). If a client sends an unsupported encoding, the
-- system can reject or reset to identity.
-- KPIs: Compression ratio, Bandwidth savings.
-- Feature Reference: F147
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.accept_encoding_rules (
    -- Primary Key
    encoding_name VARCHAR(20) PRIMARY KEY, -- gzip, compress, deflate, br

    -- Attributes
    is_enabled BOOLEAN DEFAULT true,
    priority INTEGER DEFAULT 0 -- For negotiation
);

COMMENT ON TABLE core.accept_encoding_rules IS 'Supported content encodings';

------------------------------------------------------------------------------------------------
-- Table: T148 - cache_control_directives
-- Description: Valid directives for Cache-Control headers.
-- Business Case: Validates Cache-Control headers (F148) to prevent poisoning or invalid cache
-- behavior. This table lists valid directives (no-cache, max-age, private) to ensure
-- only safe and compliant values are passed to the CDN or browser.
-- KPIs: Cache hit rate.
-- Feature Reference: F148
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cache_control_directives (
    -- Primary Key
    directive_name VARCHAR(50) PRIMARY KEY, -- max-age, no-cache, must-revalidate

    -- Attributes
    requires_value BOOLEAN DEFAULT false, -- e.g., max-age=3600 needs value
    applicable_to_responses BOOLEAN DEFAULT true,
    applicable_to_requests BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.cache_control_directives IS 'Valid Cache-Control directives';

------------------------------------------------------------------------------------------------
-- Table: T149 - etag_config
-- Description: Configuration for ETag validation.
-- Business Case: ETags are used for concurrency control (F149). This table defines the
-- valid format (Weak vs Strong, opaque identifier, quoted string) to ensure that ETags
-- provided by clients (If-Match) are syntactically correct.
-- KPIs: Concurrency collision detection.
-- Feature Reference: F149
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.etag_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    allow_weak_etags BOOLEAN DEFAULT true, -- W/""
    require_quotes BOOLEAN DEFAULT true,
    max_length INTEGER DEFAULT 128
);

COMMENT ON TABLE core.etag_config IS 'Configuration for ETag validation';

------------------------------------------------------------------------------------------------
-- Table: T150 - last_modified_config
-- Description: Configuration for validating Last-Modified headers.
-- Business Case: Validates date formats for conditional requests (F150). This table ensures
-- that the date string adheres to RFC 1123 format (e.g., 'Wed, 21 Oct 2015 07:28:00 GMT')
-- to prevent parsing errors in the HTTP stack.
-- KPIs: Conditional request success rate.
-- Feature Reference: F150
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.last_modified_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    allowed_formats TEXT[] DEFAULT ARRAY['RFC_1123', 'RFC_850', 'asctime'], -- Common formats
    max_future_skew_minutes INTEGER DEFAULT 0 -- Should not be in the future
);

COMMENT ON TABLE core.last_modified_config IS 'Configuration for Last-Modified date validation';

