-- Apply the update_updated_at trigger to Part 3 tables
DO $$ DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT table_name
             FROM information_schema.tables
             WHERE table_schema = 'core'
             AND table_name IN (
                 'fedwire_routing_rules', 'chips_uid_rules', 'ifsc_validation_rules',
                 'uk_sort_code_rules', 'australian_bsb_rules', 'canadian_transit_rules',
                 'mexican_clabe_rules', 'argentine_cbu_rules', 'mexican_spei_rules',
                 'nigerian_nuban_rules', 'loyalty_card_formats',
                 'metric_naming_conventions', 'experiment_cohort_rules'
             )
    LOOP
        EXECUTE format('CREATE TRIGGER trigger_update_%s BEFORE UPDATE ON core.%I FOR EACH ROW EXECUTE FUNCTION core.trigger_update_updated_at()', r.table_name, r.table_name);
    END LOOP;
END$$;

