------------------------------------------------------------------------------------------------
-- Table: T151 - if_match_rules
-- Description: Configuration for validating conditional request headers (If-Match/If-None-Match).
-- Business Case: Conditional requests are essential for concurrency control (optimistic locking)
-- and bandwidth efficiency (304 Not Modified). This table defines the rules for validating
-- ETags in these headers (F151). It ensures that ETag values match the expected format
-- (Weak vs. Strong) and that multiple ETags are correctly parsed, preventing synchronization
-- conflicts in distributed systems.
-- KPIs: Concurrency collision rate, Bandwidth savings (304 responses).
-- Feature Reference: F151
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.if_match_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Configuration
    allow_weak_etags BOOLEAN DEFAULT true, -- Allow W/"..."
    allow_star BOOLEAN DEFAULT true, -- Allow "*" (matches any resource)
    max_etags_per_request INTEGER DEFAULT 20, -- Limit against DoS via massive lists

    -- Validation Logic
    strict_format_checking BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.if_match_rules IS 'Rules for validating conditional request ETags';

------------------------------------------------------------------------------------------------
-- Table: T152 - content_disposition_rules
-- Description: Configuration for validating Content-Disposition headers (filenames).
-- Business Case: The Content-Disposition header specifies presentation (inline/attachment) and
-- filename. Browsers differ in handling filenames (RFC 5987 encoding). This table (F152)
-- stores the allowed encoding parameters and filename length limits, ensuring that files are
-- served with correct names and preventing header injection or XSS via malicious filenames.
-- KPIs: File download success rate, XSS prevention.
-- Feature Reference: F152
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.content_disposition_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    require_rfc5987_encoding BOOLEAN DEFAULT true, -- For non-ASCII filenames
    max_filename_length INTEGER DEFAULT 255,
    allow_special_chars BOOLEAN DEFAULT false, -- Block /, \, etc.

    -- Security
    sanitize_filename BOOLEAN DEFAULT true -- Remove/replace unsafe chars
);

COMMENT ON TABLE core.content_disposition_rules IS 'Rules for validating Content-Disposition filenames';

------------------------------------------------------------------------------------------------
-- Table: T153 - cookie_attribute_rules
-- Description: Rules for validating Set-Cookie attributes (HttpOnly, Secure, SameSite).
-- Business Case: Cookie attributes are critical for session security (F153). This table enforces
-- policies such as `Secure` must be `true` for auth cookies, and `SameSite` must be `Strict`
-- or `Lax`. Validating outgoing or incoming cookie attributes against this table prevents
-- Cross-Site Scripting (XSS) from stealing cookies or Cross-Site Request Forgery (CSRF).
-- KPIs: Security compliance (CSRF/XSS reduction).
-- Feature Reference: F153
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cookie_attribute_rules (
    -- Primary Key
    cookie_name_prefix VARCHAR(50) PRIMARY KEY, -- e.g., 'session_', 'auth_'

    -- Attributes
    require_secure BOOLEAN DEFAULT true,
    require_httponly BOOLEAN DEFAULT true,
    samesite_policy VARCHAR(10) CHECK (samesite_policy IN ('STRICT', 'LAX', 'NONE')),

    -- Constraints
    max_age_seconds INTEGER
);

COMMENT ON TABLE core.cookie_attribute_rules IS 'Security rules for Cookie attributes';

------------------------------------------------------------------------------------------------
-- Table: T154 - cors_origin_policies
-- Description: Specific policy enforcement for Origin header validation.
-- Business Case: While T052 defines the whitelist, this table (F154) defines the *policy* for
-- how to handle mismatches. It specifies whether to reject, allow with credentials, or log
-- warnings when an Origin header is present but not explicitly whitelisted, allowing fine-tuned
-- control of CORS behavior for different API endpoints.
-- KPIs: CORS error rate, Security breach prevention.
-- Feature Reference: F154
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cors_origin_policies (
    -- Primary Key
    endpoint_pattern VARCHAR(255) PRIMARY KEY,

    -- Policy
    policy_mode VARCHAR(20) NOT NULL CHECK (policy_mode IN ('WHITELIST_STRICT', 'WHITELIST_WARN', 'OPEN')),
    allow_credentials BOOLEAN DEFAULT false,
    max_age_preflight INTEGER DEFAULT 600
);

COMMENT ON TABLE core.cors_origin_policies IS 'Policy enforcement for CORS Origin headers';

------------------------------------------------------------------------------------------------
-- Table: T155 - x_forwarded_for_rules
-- Description: Rules for validating and parsing the X-Forwarded-For header chain.
-- Business Case: Behind load balancers, the client IP is in the `X-Forwarded-For` header.
-- Malicious clients can spoof this. This table (F155) defines the maximum number of hops
-- (proxies) allowed and the logic for finding the *real* client IP, ensuring that rate
-- limiting (F134) and geo-blocking are applied to the correct IP address.
-- KPIs: Geo-location accuracy, Rate limiting efficacy.
-- Feature Reference: F155
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.x_forwarded_for_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Parsing Logic
    max_hops INTEGER NOT NULL DEFAULT 10, -- Max number of IPs in chain
    trusted_proxy_count INTEGER DEFAULT 1, -- From right side, skip N trusted proxies
    invalid_ip_action VARCHAR(20) CHECK (invalid_ip_action IN ('REJECT', 'USE_LAST', 'USE_FIRST'))
);

COMMENT ON TABLE core.x_forwarded_for_rules IS 'Rules for parsing X-Forwarded-For IP chain';

------------------------------------------------------------------------------------------------
-- Table: T156 - real_client_ip_config
-- Description: Configuration for extracting the real client IP.
-- Business Case: Defines the extraction strategy (F156). Depending on the architecture
-- (Cloudflare, AWS ALB, Nginx), the real IP might be in `CF-Connecting-IP`,
-- `X-Real-IP`, or `X-Forwarded-For`. This table configures the header priority map to
-- ensure accurate IP detection for validation (F023) and analytics.
-- KPIs: IP detection accuracy.
-- Feature Reference: F156
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.real_client_ip_config (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Priority List
    header_priority TEXT[] NOT NULL DEFAULT ARRAY{'CF-Connecting-IP', 'X-Real-IP', 'X-Forwarded-For'},
    fallback_to_remote_addr BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.real_client_ip_config IS 'Configuration for extracting real client IP';

------------------------------------------------------------------------------------------------
-- Table: T157 - dnt_header_rules
-- Description: Rules for validating the DNT (Do Not Track) header.
-- Business Case: Respects user privacy preferences. While PARI must track for fraud prevention,
-- it validates the DNT header (F157) to ensure it is either '0', '1', or null.
-- Correct parsing of this header is required for GDPR privacy compliance where marketing
-- cookies might be involved.
-- KPIs: Privacy compliance tracking.
-- Feature Reference: F157
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.dnt_header_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Validation
    allow_null BOOLEAN DEFAULT true,
    enforce_respect BOOLEAN DEFAULT false -- If true, must disable marketing
);

COMMENT ON TABLE core.dnt_header_rules IS 'Configuration for DNT header validation';

------------------------------------------------------------------------------------------------
-- Table: T158 - client_hints_rules
-- Description: Rules for validating Sec-CH-UA (Client Hints) headers.
-- Business Case: Client Hints allow servers to proactively negotiate content. This table (F158)
-- defines which hints are accepted and validates their values. Ensuring only valid hints
-- are processed prevents header bloat and potential parsing errors in the security layer.
-- KPIs: Content negotiation efficiency.
-- Feature Reference: F158
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.client_hints_rules (
    -- Primary Key
    hint_name VARCHAR(50) PRIMARY KEY, -- e.g., 'Sec-CH-UA-Mobile'

    -- Attributes
    is_required BOOLEAN DEFAULT false,
    validation_regex TEXT,
    data_type VARCHAR(20) CHECK (data_type IN ('BOOLEAN', 'STRING', 'FLOAT'))
);

COMMENT ON TABLE core.client_hints_rules IS 'Rules for validating Sec-CH-UA headers';

------------------------------------------------------------------------------------------------
-- Table: T159 - download_tokens
-- Description: One-time download tokens validation and storage.
-- Business Case: Secures file downloads (e.g., invoices, sensitive docs). This table (F159)
-- stores the hash of the token, the associated file path, and expiration status. Validating
-- the token against this table ensures that the download link is one-time use or expires,
-- preventing unauthorized sharing of sensitive links.
-- KPIs: Data breach prevention, Link abuse tracking.
-- Feature Reference: F159
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.download_tokens (
    -- Primary Key
    token_hash CHAR(64) PRIMARY KEY, -- SHA-256

    -- Metadata
    file_path TEXT NOT NULL,
    file_type VARCHAR(50),

    -- Lifecycle
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    max_uses INTEGER DEFAULT 1,
    current_uses INTEGER DEFAULT 0,

    -- State
    is_consumed BOOLEAN DEFAULT false,
    created_by UUID NOT NULL
);

CREATE INDEX idx_download_tokens_expiry ON core.download_tokens(expires_at) WHERE is_consumed = false;
COMMENT ON TABLE core.download_tokens IS 'Validation and state of one-time download tokens';

------------------------------------------------------------------------------------------------
-- Table: T160 - resumable_upload_rules
-- Description: Configuration for validating resumable upload chunk offsets.
-- Business Case: Large files (e.g., transaction logs) are uploaded in chunks. This table (F160)
-- validates the `offset` and `total_size` of each chunk request. It ensures that chunks
-- are sequential, don't overlap, and don't exceed the declared total size, preventing
-- disk exhaustion or corrupted file reconstruction.
-- KPIs: Upload success rate, Storage integrity.
-- Feature Reference: F160
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.resumable_upload_rules (
    -- Primary Key
    upload_id UUID PRIMARY KEY,

    -- State
    total_size_bytes BIGINT NOT NULL,
    chunk_size_min INTEGER DEFAULT 1024,
    chunk_size_max INTEGER DEFAULT 10485760, -- 10MB
    allowed_mime_types TEXT[],

    -- Tracking
    uploaded_ranges TSTZRANGE NOT NULL DEFAULT tstzrange(NULL, NULL), -- Track uploaded byte ranges
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.resumable_upload_rules IS 'Configuration for resumable upload validation';

------------------------------------------------------------------------------------------------
-- Table: T161 - pwa_manifest_rules
-- Description: Rules for validating Web App Manifest files.
-- Business Case: Progressive Web Apps (PWAs) require a valid manifest.json. This table (F161)
-- stores the JSON Schema to validate the manifest structure (icons, start_url, display mode).
-- Ensuring the manifest is valid guarantees that the PWA is installable and behaves
-- correctly on mobile devices.
-- KPIs: PWA installation success rate.
-- Feature Reference: F161
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.pwa_manifest_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Schema
    json_schema JSONB NOT NULL, -- Schema for manifest.json
    required_fields TEXT[] NOT NULL, -- e.g., {'name', 'start_url', 'icons'}
);

COMMENT ON TABLE core.pwa_manifest_rules IS 'JSON Schema for PWA manifest validation';

------------------------------------------------------------------------------------------------
-- Table: T162 - service_worker_rules
-- Description: Validation rules for Service Worker script URLs and scopes.
-- Business Case: Service Workers must have a valid scope and URL. This table (F162) defines
-- allowed scopes (e.g., `/` or `/app/`) and ensures the service worker script is served
-- from the same origin, preventing malicious scripts from intercepting network traffic.
-- KPIs: PWA security compliance.
-- Feature Reference: F162
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.service_worker_rules (
    -- Primary Key
    scope_path VARCHAR(255) PRIMARY KEY,

    -- Constraints
    max_scope_depth INTEGER DEFAULT 5,
    require_https BOOLEAN DEFAULT true,
    allowed_file_extensions TEXT[] DEFAULT ARRAY{'js'}
);

COMMENT ON TABLE core.service_worker_rules IS 'Rules for Service Worker scope validation';

------------------------------------------------------------------------------------------------
-- Table: T163 - push_subscriptions
-- Description: Validation rules and storage for Push API subscription objects.
-- Business Case: Web Push requires valid subscription objects (endpoint + keys). This table
-- (F163) validates the structure of the VAPID keys and ensures the endpoint is a valid URL.
-- Storing the hash of the subscription allows deduplication to prevent spamming a user with
-- multiple notifications for the same device.
-- KPIs: Notification delivery success, Duplicate prevention.
-- Feature Reference: F163
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.push_subscriptions (
    -- Primary Key
    subscription_hash CHAR(64) PRIMARY KEY,

    -- Data
    endpoint TEXT NOT NULL,
    keys_json JSONB NOT NULL, -- p256dh and auth

    -- Audit
    user_id UUID NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.push_subscriptions IS 'Validation and storage of Push API subscriptions';

------------------------------------------------------------------------------------------------
-- Table: T164 - content_negotiation_rules
-- Description: Rules for validating Accept headers (Media Type Negotiation).
-- Business Case: Determines how the server responds (JSON vs XML vs HTML). This table (F164)
-- maps requested MIME types to supported internal representations. Validating the Accept header
-- ensures that the client understands the response format, preventing 406 (Not Acceptable)
-- errors and API confusion.
-- KPIs: Content negotiation success rate.
-- Feature Reference: F164
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.content_negotiation_rules (
    -- Primary Key
    media_type_pattern VARCHAR(100) PRIMARY KEY, -- e.g., 'application/json', 'text/*'

    -- Mapping
    response_format VARCHAR(50) NOT NULL, -- 'JSON', 'XML'
    priority INTEGER DEFAULT 1,

    -- Constraints
    charset VARCHAR(20) DEFAULT 'UTF-8'
);

COMMENT ON TABLE core.content_negotiation_rules IS 'Rules for Accept header validation';

------------------------------------------------------------------------------------------------
-- Table: T165 - graphql_complexity_rules
-- Description: Rules for limiting GraphQL query complexity (DoS protection).
-- Business Case: GraphQL queries can be infinitely nested. Without limits, a single query can
-- crash the server (DoS). This table (F165) defines max depth, max node count, and max cost
-- (weighted complexity). The validation engine calculates query cost and rejects it if it
-- exceeds these thresholds.
-- KPIs: API stability, DoS prevention.
-- Feature Reference: F165
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.graphql_complexity_rules (
    -- Primary Key
    endpoint VARCHAR(100) NOT NULL,
    role_level VARCHAR(50) DEFAULT 'DEFAULT', -- Different limits for Admin vs Guest
    PRIMARY KEY (endpoint, role_level),

    -- Limits
    max_query_depth INTEGER DEFAULT 7,
    max_node_count INTEGER DEFAULT 500,
    max_cost_score INTEGER DEFAULT 1000,

    -- Costs
    object_cost INTEGER DEFAULT 1,
    list_cost_multiplier INTEGER DEFAULT 10
);

COMMENT ON TABLE core.graphql_complexity_rules IS 'Complexity limits for GraphQL queries (DoS protection)';

------------------------------------------------------------------------------------------------
-- Table: T166 - graphql_argument_types
-- Description: Validation rules for GraphQL argument types.
-- Business Case: Ensures that inputs to GraphQL mutations/queries conform to the schema types.
-- This table (F166) maps argument names to expected scalar or enum types (Int, String, Date).
-- Validation against this table prevents runtime errors during query execution and prevents
-- injection of incompatible types.
-- KPIs: GraphQL execution error rate.
-- Feature Reference: F166
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.graphql_argument_types (
    -- Primary Key
    field_name VARCHAR(255) NOT NULL,
    argument_name VARCHAR(100) NOT NULL,
    PRIMARY KEY (field_name, argument_name),

    -- Type
    expected_type VARCHAR(50) NOT NULL, -- Int, String, CustomScalar
    is_nullable BOOLEAN DEFAULT true,

    -- Constraints
    regex_pattern TEXT -- For scalar validation like Email or URL
);

COMMENT ON TABLE core.graphql_argument_types IS 'Type definitions for GraphQL arguments';

------------------------------------------------------------------------------------------------
-- Table: T167 - graphql_mutation_rules
-- Description: Validation rules for GraphQL mutation payloads.
-- Business Case: Mutations change state, so they require stricter validation than queries. This
-- table (F167) defines the JSON Schema or structural rules for mutation input objects. It
-- ensures that required fields are present and inputs are semantically valid before committing
-- them to the transaction log.
-- KPIs: Data integrity in mutations.
-- Feature Reference: F167
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.graphql_mutation_rules (
    -- Primary Key
    mutation_name VARCHAR(255) PRIMARY KEY,

    -- Validation
    input_schema JSONB, -- Schema for the input object
    required_fields TEXT[],
    side_effects TEXT[] -- 'CREATES_TRANSACTION', 'SENDS_EMAIL'
);

COMMENT ON TABLE core.graphql_mutation_rules IS 'Validation rules for GraphQL mutations';

------------------------------------------------------------------------------------------------
-- Table: T168 - grpc_message_limits
-- Description: Configuration for validating gRPC message sizes.
-- Business Case: Protobuf messages (F168) are efficient but can still be maliciously large.
-- This table defines the maximum message size (in bytes) for different services. Validating
-- size at the edge prevents memory exhaustion attacks against the gRPC gateway.
-- KPIs: Gateway stability.
-- Feature Reference: F168
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.grpc_message_limits (
    -- Primary Key
    service_name VARCHAR(100) NOT NULL,
    method_name VARCHAR(100) NOT NULL,
    PRIMARY KEY (service_name, method_name),

    -- Limits
    max_request_bytes BIGINT DEFAULT 4194304, -- 4MB
    max_response_bytes BIGINT DEFAULT 4194304,

    -- State
    enforce_limit BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.grpc_message_limits IS 'Size limits for gRPC messages';

------------------------------------------------------------------------------------------------
-- Table: T169 - grpc_metadata_rules
-- Description: Rules for validating gRPC metadata (headers).
-- Business Case: gRPC metadata keys must be lowercase ASCII (F169). Values can be binary.
-- This table validates the structure of incoming metadata to prevent protocol violations or
-- injection of illegal characters that could crash the gRPC parser.
-- KPIs: gRPC request success rate.
-- Feature Reference: F169
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.grpc_metadata_rules (
    -- Primary Key
    key_name VARCHAR(255) PRIMARY KEY,

    -- Rules
    key_format_regex VARCHAR(50) DEFAULT '^[a-z0-9._-]+$',
    max_value_length INTEGER DEFAULT 8192,

    -- Security
    is_binary BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.grpc_metadata_rules IS 'Rules for gRPC metadata key/value validation';

------------------------------------------------------------------------------------------------
-- Table: T170 - websocket_protocol_rules
-- Description: Rules for validating WebSocket Subprotocol headers.
-- Business Case: The `Sec-WebSocket-Protocol` header negotiates the subprotocol (e.g., chat,
-- v1.stomp). This table (F170) defines the allowed protocols. Validating against this list
-- ensures that the server and client agree on the message format, preventing connection failures.
-- KPIs: WebSocket handshake success rate.
-- Feature Reference: F170
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.websocket_protocol_rules (
    -- Primary Key
    protocol_name VARCHAR(50) PRIMARY KEY,

    -- Configuration
    version VARCHAR(20),
    is_default BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.websocket_protocol_rules IS 'Allowed WebSocket subprotocols';

------------------------------------------------------------------------------------------------
-- Table: T171 - mqtt_topic_rules
-- Description: Validation rules for MQTT topics and wildcards.
-- Business Case: MQTT uses hierarchical topics (F171). This table defines which wildcard
-- characters (`+` for single level, `#` for multi-level) are allowed and where. It also
-- validates topic lengths to prevent buffer overflows in IoT brokers.
-- KPIs: IoT message routing success.
-- Feature Reference: F171
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.mqtt_topic_rules (
    -- Primary Key
    topic_pattern VARCHAR(255) PRIMARY KEY,

    -- Rules
    allow_multi_level_wildcard BOOLEAN DEFAULT true, -- #
    allow_single_level_wildcard BOOLEAN DEFAULT true, -- +
    max_depth_levels INTEGER DEFAULT 10,

    -- Constraints
    min_length INTEGER DEFAULT 1,
    max_length INTEGER DEFAULT 65535
);

COMMENT ON TABLE core.mqtt_topic_rules IS 'Validation rules for MQTT topics and wildcards';

------------------------------------------------------------------------------------------------
-- Table: T172 - amqp_routing_rules
-- Description: Validation rules for AMQP routing keys.
-- Business Case: AMQP routing keys define message paths (F172). This table validates the syntax
-- of routing keys (dot-separated words) and ensures they match the binding keys of exchanges.
-- Correct validation prevents messages from being routed to "black holes" (queues with no
-- bindings).
-- KPIs: Message delivery success rate.
-- Feature Reference: F172
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.amqp_routing_rules (
    -- Primary Key
    routing_key_pattern VARCHAR(255) PRIMARY KEY,

    -- Rules
    separator CHAR(1) DEFAULT '.',
    allow_wildcards BOOLEAN DEFAULT false, -- AMQP usually matches exact or specific patterns
    max_word_length INTEGER DEFAULT 255
);

COMMENT ON TABLE core.amqp_routing_rules IS 'Validation rules for AMQP routing keys';

------------------------------------------------------------------------------------------------
-- Table: T173 - kafka_topic_config
-- Description: Validation rules for Kafka topic naming (Part 2 T095 existed, this is stricter naming).
-- Business Case: Kafka topics have naming conventions (F173) regarding legal characters and
-- length. This table enforces these rules (e.g., no spaces, no special chars except dot,
-- underscore, hyphen) at the producer level to prevent Kafka broker errors.
-- KPIs: Kafka producer success rate.
-- Feature Reference: F173
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.kafka_topic_config (
    -- Primary Key
    topic_name VARCHAR(255) PRIMARY KEY, -- Reference to T095

    -- Naming Rules
    regex_pattern VARCHAR(100) DEFAULT '^[a-zA-Z0-9._-]+$',
    min_length INTEGER DEFAULT 1,
    max_length INTEGER DEFAULT 249,

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.kafka_topic_config IS 'Naming conventions for Kafka topics';

------------------------------------------------------------------------------------------------
-- Table: T174 - avro_schema_ids
-- Description: Mapping of Avro schema IDs to their definitions.
-- Business Case: Avro requires readers and writers to agree on schema IDs (F174). This table
-- stores the ID returned by the Schema Registry and the actual Avro JSON schema. The
-- validation layer uses this to ensure that incoming binary Avro data corresponds to a known
-- schema ID, preventing deserialization crashes.
-- KPIs: Deserialization success rate.
-- Feature Reference: F174
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.avro_schema_ids (
    -- Primary Key
    schema_id INTEGER NOT NULL,

    -- Definition
    schema_json JSONB NOT NULL,

    -- Context
    topic_name VARCHAR(255),

    -- Unique Constraint
    CONSTRAINT avro_id_topic_unique UNIQUE (schema_id, topic_name)
);

COMMENT ON TABLE core.avro_schema_ids IS 'Avro Schema ID mapping for validation';

------------------------------------------------------------------------------------------------
-- Table: T175 - protobuf_descriptors
-- Description: Validation rules for Protobuf descriptor sets.
-- Business Case: Protobuf uses `.proto` descriptors (F175). This table stores the hashes or
-- signatures of allowed descriptor sets. Validating incoming binary data against these
-- descriptors ensures the message structure matches the expected `.proto` file, preventing
-- corruption.
-- KPIs: Protobuf parsing accuracy.
-- Feature Reference: F175
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.protobuf_descriptors (
    -- Primary Key
    descriptor_hash CHAR(64) PRIMARY KEY, -- Hash of descriptor set

    -- Metadata
    proto_file_name VARCHAR(255),
    message_type VARCHAR(255),

    -- Binary
    descriptor_bytes BYTEA NOT NULL
);

COMMENT ON TABLE core.protobuf_descriptors IS 'Protobuf descriptor sets for validation';

------------------------------------------------------------------------------------------------
-- Table: T176 - flatbuffers_identifiers
-- Description: Validation rules for FlatBuffers file identifiers.
-- Business Case: FlatBuffers starts with a file identifier (F176). This table stores the
-- allowed 4-character identifiers. Validating the identifier ensures the binary blob is
-- of the expected schema version before attempting to access offsets.
-- KPIs: Binary parsing safety.
-- Feature Reference: F176
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.flatbuffers_identifiers (
    -- Primary Key
    file_identifier CHAR(4) PRIMARY KEY

    -- Attributes
    schema_name VARCHAR(255) NOT NULL,
    version VARCHAR(50)
);

COMMENT ON TABLE core.flatbuffers_identifiers IS 'Valid FlatBuffers file identifiers';

------------------------------------------------------------------------------------------------
-- Table: T177 - capn_proto_rules
-- Description: Validation rules for Cap'n Proto struct pointers.
-- Business Case: Cap'n Proto relies on pointers (F177). This table defines the expected pointer
-- offsets and struct sizes for known message types. It ensures that the data structure is
-- valid, preventing out-of-bounds reads when traversing the Cap'n Proto message.
-- KPIs: Data safety in parsing.
-- Feature Reference: F177
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.capn_proto_rules (
    -- Primary Key
    struct_id BIGINT PRIMARY KEY, -- Cap'n Proto ID

    -- Validation
    struct_name VARCHAR(255),
    data_section_size_bytes INTEGER,
    pointer_section_size_bytes INTEGER
);

COMMENT ON TABLE core.capn_proto_rules IS 'Rules for Cap'n Proto struct validation';

------------------------------------------------------------------------------------------------
-- Table: T178 - messagepack_rules
-- Description: Validation rules for MessagePack bin/ext formats.
-- Business Case: MessagePack is a binary format (F178). This table defines the valid format
-- families (bin, ext, fixarray) and their length limits. Validation ensures that custom
-- MessagePack payloads do not exploit parsers with malformed lengths or types.
-- KPIs: Parsing reliability.
-- Feature Reference: F178
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.messagepack_rules (
    -- Primary Key
    format_family VARCHAR(20) PRIMARY KEY, -- bin8, bin16, ext8

    -- Constraints
    max_length INTEGER DEFAULT 4294967295,
    is_fixed_size BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.messagepack_rules IS 'Rules for MessagePack binary formats';

------------------------------------------------------------------------------------------------
-- Table: T179 - cbor_rules
-- Description: Validation rules for CBOR tags and data types.
-- Business Case: CBOR is a superset of JSON, used in constrained environments (F179). This table
-- defines the allowed semantic tags (e.g., epoch date, bignum) and data types. Validating
-- tags ensures that decoders handle the data correctly and that unknown or dangerous tags
-- are rejected.
-- KPIs: Data integrity in IoT.
-- Feature Reference: F179
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cbor_rules (
    -- Primary Key
    data_tag INTEGER PRIMARY KEY, -- CBOR Semantic Tag

    -- Attributes
    description TEXT,
    is_standard BOOLEAN DEFAULT true,
    is_dangerous BOOLEAN DEFAULT false -- e.g., unassigned tags in strict mode
);

COMMENT ON TABLE core.cbor_rules IS 'Rules for CBOR tag and data type validation';

------------------------------------------------------------------------------------------------
-- Table: T180 - asn1_validators
-- Description: Validation rules for ASN.1 encoded data (X.509, etc.).
-- Business Case: ASN.1 is used in PKI (F180). This table stores the OIDs (Object Identifiers)
-- and structure rules for certificates and other PKI data. Validating that a certificate
-- contains only permitted extensions (OIDs) prevents malicious certificate injection or
-- parsing of invalid structures.
-- KPIs: PKI security compliance.
-- Feature Reference: F180
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.asn1_validators (
    -- Primary Key
    oid VARCHAR(255) PRIMARY KEY, -- e.g., 2.5.4.3 (Common Name)

    -- Attributes
    oid_name VARCHAR(255),
    is_critical BOOLEAN DEFAULT false,

    -- Validation
    allowed_value_types TEXT[] -- {'UTF8String', 'PrintableString'}
);

COMMENT ON TABLE core.asn1_validators IS 'Rules for validating ASN.1 OID structures';

------------------------------------------------------------------------------------------------
-- Table: T181 - der_encoding_rules
-- Description: Rules for validating Distinguished Encoding Rules (DER) syntax.
-- Business Case: DER is a strict subset of BER (F181). This table enforces strict DER
-- encoding rules (e.g., lengths must be minimal form). Rejecting non-strict BER encoding
-- prevents signature malleability attacks and ensures compatibility with strict cryptographic
-- libraries.
-- KPIs: Cryptographic interoperability.
-- Feature Reference: F181
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.der_encoding_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Constraints
    enforce_minimal_length BOOLEAN DEFAULT true, -- DER requirement
    enforce_constructed_encoding BOOLEAN DEFAULT true, -- Specific checks for SET vs SEQUENCE
);

COMMENT ON TABLE core.der_encoding_rules IS 'Strict DER encoding validation rules';

------------------------------------------------------------------------------------------------
-- Table: T182 - pem_boundaries
-- Description: Validation rules for PEM certificate boundaries.
-- Business Case: PEM files are Base64 with headers (F182). This table validates the header
-- (e.g., `-----BEGIN CERTIFICATE-----`) and footer boundaries. It also checks for common
-- formatting errors like extra spaces or incorrect line wrapping, ensuring the certificate
-- is readable by the security layer.
-- KPIs: Certificate load success rate.
-- Feature Reference: F182
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.pem_boundaries (
    -- Primary Key
    type_name VARCHAR(50) PRIMARY KEY, -- CERTIFICATE, PRIVATE KEY, RSA PUBLIC KEY

    -- Headers
    header_template TEXT NOT NULL, -- -----BEGIN {type}-----
    footer_template TEXT NOT NULL,

    -- Format
    line_length INTEGER DEFAULT 64
);

COMMENT ON TABLE core.pem_boundaries IS 'Validation rules for PEM header/footer boundaries';

------------------------------------------------------------------------------------------------
-- Table: T183 - crl_validators
-- Description: Validation rules for CRL (Certificate Revocation List) Distribution Points.
-- Business Case: CRLs check certificate validity (F183). This table stores the valid URL
-- schemes (HTTP/LDAP) and formats for CRL distribution points found in certificates.
-- Validating the URL ensures the system can download and check the CRL to honor revoked
-- certificates.
-- KPIs: Revocation check success rate.
-- Feature Reference: F183
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.crl_validators (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- URL Rules
    allowed_schemes TEXT[] DEFAULT ARRAY{'http', 'https'},
    max_url_length INTEGER DEFAULT 256,

    -- Constraints
    require_https BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.crl_validators IS 'Rules for validating CRL distribution points';

------------------------------------------------------------------------------------------------
-- Table: T184 - ocsp_validators
-- Description: Validation rules for OCSP (Online Certificate Status Protocol) responses.
-- Business Case: OCSP provides real-time status (F184). This table defines the valid
-- response statuses (GOOD, REVOKED, UNKNOWN) and structure. It ensures that the OCSP
-- response is properly signed and matches the nonce/request, preventing replay attacks.
-- KPIs: OCSP verification success.
-- Feature Reference: F184
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.ocsp_validators (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Validation
    require_signature_check BOOLEAN DEFAULT true,
    allowed_next_update_skew_seconds INTEGER DEFAULT 300, -- Tolerance for clock drift
    max_response_age_seconds INTEGER DEFAULT 10
);

COMMENT ON TABLE core.ocsp_validators IS 'Rules for validating OCSP responses';

------------------------------------------------------------------------------------------------
-- Table: T185 - tls_versions
-- Description: Valid TLS protocol versions (Duplicate of T053).
-- Business Case: Enforces strong encryption standards for data in transit. This table ensures
-- that only TLS 1.2 and TLS 1.3 are permitted. Validation checks that the Client Hello
-- or Server Hello indicates a supported version, preventing the negotiation of insecure
-- protocols like SSLv3 or TLS 1.0.
-- KPIs: Security compliance, Encrypted connection rate.
-- Feature Reference: F185
-- Note: Table creation uses IF NOT EXISTS to ensure idempotency.
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.tls_versions (
    version_name VARCHAR(20) PRIMARY KEY, -- e.g., 'TLSv1.3'
    is_active BOOLEAN DEFAULT true
);
COMMENT ON TABLE core.tls_versions IS 'Allowed TLS protocol versions (Configuration)';

------------------------------------------------------------------------------------------------
-- Table: T186 - cipher_suites
-- Description: Allowed cryptographic cipher suites (Duplicate of T054).
-- Business Case: Defines which encryption algorithms are acceptable. This table prevents the
-- use of weak ciphers (e.g., RC4) by validating the cipher suite negotiated during the
-- TLS handshake. This is critical for maintaining a high security posture and preventing
-- decryption of traffic.
-- KPIs: Cipher suite strength.
-- Feature Reference: F186
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cipher_suites (
    suite_name VARCHAR(100) PRIMARY KEY,
    security_score INTEGER NOT NULL CHECK (security_score BETWEEN 1 AND 100),
    is_active BOOLEAN DEFAULT true
);
COMMENT ON TABLE core.cipher_suites IS 'Allowed TLS cipher suites (Configuration)';

------------------------------------------------------------------------------------------------
-- Table: T187 - certificate_pinning
-- Description: Known certificate fingerprints for pinning (Duplicate of T055).
-- Business Case: Prevents Man-in-the-Middle attacks by validating the server certificate
-- fingerprint against a known whitelist. This table (F187) stores the pins (SHA-256 of SPKI).
-- Validation ensures the connection is to the genuine server, not an attacker spoofing the
-- DNS.
-- KPIs: MITM prevention rate.
-- Feature Reference: F187
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.certificate_pinning (
    domain VARCHAR(255) NOT NULL,
    pin_hash VARCHAR(64) NOT NULL,
    backup_pin_hash VARCHAR(64),
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT cert_pin_domain UNIQUE (domain, pin_hash)
);
COMMENT ON TABLE core.certificate_pinning IS 'Certificate pins for MITM prevention (Configuration)';

------------------------------------------------------------------------------------------------
-- Table: T188 - dnssec_validators
-- Description: Validation rules for DNSSEC signature records (RRSIG).
-- Business Case: DNSSEC secures DNS lookups (F188). This table defines the rules for validating
-- RRSIG records (Signature Expiration, Inception, Key Tag). Validating these ensures that
-- the DNS response is authentic and hasn't been tampered with.
-- KPIs: DNS authentication success.
-- Feature Reference: F188
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.dnssec_validators (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Validation
    max_clock_skew_seconds INTEGER DEFAULT 3600, -- Allow 1 hr drift
    require_key_match BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.dnssec_validators IS 'Rules for validating DNSSEC signatures';

------------------------------------------------------------------------------------------------
-- Table: T189 - dane_validators
-- Description: Validation rules for DANE TLSA records.
-- Business Case: DANE binds certificates to DNS (F189). This table validates TLSA records
-- (Certificate Usage, Selector, Matching Type). It ensures that the TLSA record in DNS
-- correctly matches the server's certificate chain, providing a robust trust anchor.
-- KPIs: DANE verification success.
-- Feature Reference: F189
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.dane_validators (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Validation
    allowed_usages TEXT[] DEFAULT ARRAY{'3', '0'}, -- DANE-EE or DANE-TA
    allowed_selectors TEXT[] DEFAULT ARRAY{'0', '1'}, -- Full cert or public key
    allowed_matching_types TEXT[] DEFAULT ARRAY{'1', '2'} -- SHA-256 or SHA-512
);

COMMENT ON TABLE core.dane_validators IS 'Rules for validating DANE TLSA records';

------------------------------------------------------------------------------------------------
-- Table: T190 - ssh_known_hosts
-- Description: Validation rules for SSH host keys.
-- Business Case: SSH connections (e.g., SFTP, Git) require known host keys (F190). This table
-- stores the expected fingerprints for server hosts. Validation ensures the client connects
-- to the trusted server, preventing Man-in-the-Middle attacks during infrastructure tasks
-- (deployments, data transfers).
-- KPIs: SSH security integrity.
-- Feature Reference: F190
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.ssh_known_hosts (
    -- Primary Key
    host_key_fingerprint VARCHAR(64) PRIMARY KEY, -- SHA-256 fingerprint

    -- Attributes
    host_name VARCHAR(255) NOT NULL,
    key_type VARCHAR(20) NOT NULL, -- RSA, ED25519
    key_value TEXT NOT NULL, -- The public key
    trusted_since TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.ssh_known_hosts IS 'Known SSH host keys for validation';

------------------------------------------------------------------------------------------------
-- Table: T191 - gpg_signatures
-- Description: Validation rules for GPG/PGP signatures.
-- Business Case: GPG is used for code signing and email (F191). This table validates the GPG
-- signature packet structure (Signature type, Key ID). It ensures that the signature is
-- cryptographically valid and issued by a trusted keyring member.
-- KPIs: Signature verification success.
-- Feature Reference: F191
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.gpg_signatures (
    -- Primary Key
    key_id VARCHAR(40) PRIMARY KEY, -- GPG Key ID (hex)

    -- Attributes
    owner_name VARCHAR(255),
    key_algorithm VARCHAR(20), -- RSA, ELG-E, DSA
    key_length INTEGER,
    is_trusted BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.gpg_signatures IS 'Trusted GPG keys for signature validation';

------------------------------------------------------------------------------------------------
-- Table: T192 - jar_signatures
-- Description: Validation rules for signed JAR files.
-- Business Case: JAR signing is required for Java applets and some libraries (F192). This table
-- defines the required digest algorithms (SHA-256) and checks the signature file (.SF) and
-- block file (.DSA) integrity. Validation prevents the execution of modified or malicious Java
-- code.
-- KPIs: Java security compliance.
-- Feature Reference: F192
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.jar_signatures (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    required_digest_algorithm VARCHAR(10) DEFAULT 'SHA-256',
    require_manifest_signature BOOLEAN DEFAULT true,
    block_unsigned_jars BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.jar_signatures IS 'Rules for validating signed JAR files';

------------------------------------------------------------------------------------------------
-- Table: T193 - apk_signatures
-- Description: Validation rules for Android APK signatures (v1, v2, v3).
-- Business Case: APK signing ensures app authenticity (F193). This table validates the signature
-- schemes used in the APK. It checks that signatures match the public key certificates
-- embedded in the APK and that the signing certificates are valid, preventing installation of
-- tampered apps.
-- KPIs: Mobile app security.
-- Feature Reference: F193
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.apk_signatures (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    allowed_signature_versions TEXT[] DEFAULT ARRAY{'v1', 'v2', 'v3'},
    require_v3_signature BOOLEAN DEFAULT true, -- Most secure
    allow_stripping BOOLEAN DEFAULT false -- Allow downgrade of signing blocks
);

COMMENT ON TABLE core.apk_signatures IS 'Rules for validating APK signatures';

------------------------------------------------------------------------------------------------
-- Table: T194 - provisioning_profiles
-- Description: Validation rules for iOS Provisioning Profiles.
-- Business Case: Profiles are required for iOS app deployment (F194). This table validates the
-- App ID, Team ID, and expiration date of the .mobileprovision file. Ensuring the
-- profile is valid and not expired prevents the installation of unauthorized iOS binaries or
-- debugging builds in production.
-- KPIs: iOS deployment compliance.
-- Feature Reference: F194
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.provisioning_profiles (
    -- Primary Key
    uuid UUID PRIMARY KEY,

    -- Attributes
    app_id_prefix VARCHAR(10) NOT NULL,
    app_identifier VARCHAR(255) NOT NULL,

    -- State
    expiration_date DATE NOT NULL,
    is_development BOOLEAN DEFAULT false,

    -- Constraints
    CONSTRAINT profile_expiration CHECK (expiration_date >= CURRENT_DATE)
);

COMMENT ON TABLE core.provisioning_profiles IS 'Validation of iOS Provisioning Profiles';

------------------------------------------------------------------------------------------------
-- Table: T195 - authenticode_certificates
-- Description: Validation rules for Authenticode signatures on Windows binaries.
-- Business Case: Authenticode signs EXE, MSI, and CAB files for Windows (F195). This table
-- validates the signature chain and ensures the certificate is issued by a trusted CA (e.g.,
-- Verisign). It prevents the execution of unsigned or malware-injected binaries in the
-- infrastructure.
-- KPIs: Windows security baseline.
-- Feature Reference: F195
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.authenticode_certificates (
    -- Primary Key
    thumbprint VARCHAR(40) PRIMARY KEY, -- SHA-1 thumbprint of cert (legacy)

    -- Attributes
    subject VARCHAR(255),
    issuer VARCHAR(255),
    valid_until DATE NOT NULL
);

COMMENT ON TABLE core.authenticode_certificates IS 'Trusted Authenticode certificates';

------------------------------------------------------------------------------------------------
-- Table: T196 - docker_image_whitelist
-- Description: Allowed Docker registries and images (Duplicate of T056).
-- Business Case: Ensures supply chain security. This table (F196) whitelists allowed registries
-- (e.g., Docker Hub, ECR) and specific image digests. Validation prevents the pull of
-- compromised or unauthorized images, securing the CI/CD pipeline.
-- KPIs: Container security compliance.
-- Feature Reference: F196
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.docker_image_whitelist (
    registry_url VARCHAR(255) NOT NULL,
    image_name VARCHAR(255) NOT NULL,
    digest VARCHAR(100) NOT NULL,
    PRIMARY KEY (registry_url, image_name, digest),
    signature_verified BOOLEAN DEFAULT true,
    is_active BOOLEAN DEFAULT true
);
COMMENT ON TABLE core.docker_image_whitelist IS 'Allowed Docker images (Configuration)';

------------------------------------------------------------------------------------------------
-- Table: T197 - oci_manifest_rules
-- Description: Validation rules for OCI Image Manifests.
-- Business Case: OCI (Open Container Initiative) standardizes image manifests (F197). This table
-- validates the JSON Schema of the manifest (mediaType, config, layers). It ensures that the
-- manifest structure is compliant, preventing deployment failures due to malformed image configs.
-- KPIs: Container deployment success rate.
-- Feature Reference: F197
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.oci_manifest_rules (
    -- Primary Key
    media_type VARCHAR(100) PRIMARY KEY, -- e.g., application/vnd.oci.image.manifest.v1+json

    -- Validation
    json_schema JSONB NOT NULL,
    required_layers_artifact_type VARCHAR(100)
);

COMMENT ON TABLE core.oci_manifest_rules IS 'Rules for validating OCI Image Manifests';

------------------------------------------------------------------------------------------------
-- Table: T198 - helm_chart_schemas
-- Description: Validation rules for Helm Chart values.yaml.
-- Business Case: Helm manages Kubernetes deployments (F198). This table defines the JSON
-- Schema for the `values.yaml` file of specific charts. Validating input values against this
-- schema prevents deployment of misconfigured or invalid infrastructure stacks.
-- KPIs: Infrastructure deployment success rate.
-- Feature Reference: F198
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.helm_chart_schemas (
    -- Primary Key
    chart_name VARCHAR(255) NOT NULL,
    chart_version VARCHAR(50) NOT NULL,
    PRIMARY KEY (chart_name, chart_version),

    -- Schema
    values_schema JSONB NOT NULL
);

COMMENT ON TABLE core.helm_chart_schemas IS 'JSON Schemas for Helm Chart values';

------------------------------------------------------------------------------------------------
-- Table: T199 - kubernetes_label_rules
-- Description: Rules for validating Kubernetes label keys and values.
-- Business Case: K8s labels must be valid DNS subdomains (F199). This table defines the regex
-- rules for label keys (prefix/name) and values. Validating labels applied to resources
-- prevents API rejection errors during resource creation or update.
-- KPIs: K8s API success rate.
-- Feature Reference: F199
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.kubernetes_label_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    key_prefix_length_max INTEGER DEFAULT 253,
    key_name_length_max INTEGER DEFAULT 63,
    value_length_max INTEGER DEFAULT 63,

    -- Regex
    key_regex VARCHAR(255) DEFAULT '^[a-z0-9]([-a-z0-9]*[a-z0-9])?(\\.[a-z0-9]([-a-z0-9]*[a-z0-9])?)*$'
);

COMMENT ON TABLE core.kubernetes_label_rules IS 'Rules for K8s label syntax';

------------------------------------------------------------------------------------------------
-- Table: T200 - terraform_state_whitelist
-- Description: Allowed S3 buckets for Terraform state (Duplicate of T058).
-- Business Case: Terraform state contains secrets (F200). This table restricts where state
-- can be stored to compliant, encrypted S3 buckets. Validation ensures that Terraform runs
-- do not accidentally write state to an insecure location.
-- KPIs: Infrastructure security compliance.
-- Feature Reference: F200
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.terraform_state_whitelist (
    bucket_name VARCHAR(255) PRIMARY KEY,
    region VARCHAR(50) NOT NULL,
    is_encrypted BOOLEAN DEFAULT true,
    versioning_enabled BOOLEAN DEFAULT true
);
COMMENT ON TABLE core.terraform_state_whitelist IS 'Allowed S3 buckets for Terraform state (Configuration)';

-- ================================================================================================
-- 5. ENTITY RELATIONSHIPS AND CONSTRAINTS (Foreign Keys - Part 4)
-- ================================================================================================

-- T174 (avro_schema_ids) references T095 (message_queue_topics)
ALTER TABLE core.avro_schema_ids
    ADD CONSTRAINT fk_avro_topic
    FOREIGN KEY (topic_name) REFERENCES core.message_queue_topics(topic_name) ON DELETE CASCADE;

-- T159 (download_tokens) logic implies a user table, but we use UUID generic.

-- ================================================================================================
-- 6. TRIGGERS FOR AUDIT COLUMNS (Part 4)
-- ================================================================================================

-- Apply the update_updated_at trigger to Part 4 tables
DO $$ DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT table_name
             FROM information_schema.tables
             WHERE table_schema = 'core'
             AND table_name IN (
                 'x_forwarded_for_rules', 'download_tokens', 'resumable_upload_rules',
                 'push_subscriptions', 'graphql_complexity_rules', 'graphql_argument_types',
                 'gpg_signatures', 'authenticode_certificates'
             )
    LOOP
        EXECUTE format('CREATE TRIGGER trigger_update_%s BEFORE UPDATE ON core.%I FOR EACH ROW EXECUTE FUNCTION core.trigger_update_updated_at()', r.table_name, r.table_name);
    END LOOP;
END$$;

