------------------------------------------------------------------------------------------------
-- Table: T201 - cloudformation_templates
-- Description: Storage and validation rules for AWS CloudFormation templates.
-- Business Case: CloudFormation is the Infrastructure as Code (IaC) standard for AWS. This
-- table stores the template definitions (JSON/YAML) and validation rules. It ensures that
-- infrastructure deployments are based on validated, versioned templates, preventing
-- drift, security misconfigurations (like open security groups), and deployment failures
-- due to syntax errors. It supports the CMMI Level 5 goal by maintaining a standard
-- repository for all cloud artifacts.
-- KPIs: IaC deployment success rate, Template validation latency.
-- Feature Reference: F201
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cloudformation_templates (
    -- Primary Key
    template_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    stack_name VARCHAR(255) NOT NULL,
    region VARCHAR(50) NOT NULL,
    template_version VARCHAR(50) NOT NULL,

    -- Content
    template_body JSONB NOT NULL, -- The CloudFormation template JSON/YAML
    parameters_schema JSONB, -- Expected parameters

    -- Validation Rules
    max_resources INTEGER, -- Guardrail for resource count
    required_resources TEXT[], -- e.g., {'VPC', 'Subnet'}

    -- Lifecycle
    is_active BOOLEAN DEFAULT true,
    is_deprecated BOOLEAN DEFAULT false,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL,

    -- Constraints
    CONSTRAINT cf_template_unique UNIQUE (stack_name, region, template_version)
);

COMMENT ON TABLE core.cloudformation_templates IS 'Storage and validation rules for AWS CloudFormation templates';

------------------------------------------------------------------------------------------------
-- Table: T202 - arm_templates
-- Description: Storage and validation rules for Azure Resource Manager (ARM) templates.
-- Business Case: Azure ARM templates define the infrastructure for Azure environments. This
-- table stores the JSON schema and logic required to validate ARM templates before deployment.
-- It ensures that Azure resources (VMs, SQL Databases) are defined correctly, adhering
-- to corporate governance policies, and preventing costly deployment errors.
-- KPIs: Azure deployment accuracy.
-- Feature Reference: F202
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.arm_templates (
    -- Primary Key
    template_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    resource_group VARCHAR(255) NOT NULL,
    subscription_id VARCHAR(100) NOT NULL,
    template_version VARCHAR(50) NOT NULL,

    -- Content
    template_json JSONB NOT NULL, -- ARM Template JSON
    parameters_schema JSONB,

    -- Validation
    allowed_providers TEXT[], -- e.g., {'Microsoft.Compute', 'Microsoft.Network'}
    forbidden_locations TEXT[], -- e.g., block 'eastus' for compliance

    -- Lifecycle
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.arm_templates IS 'Storage and validation rules for Azure ARM templates';

------------------------------------------------------------------------------------------------
-- Table: T203 - sam_policies
-- Description: Validation rules for AWS Serverless Application Model (SAM) policies.
-- Business Case: SAM is an extension of CloudFormation for serverless apps. This table
-- specifically validates the IAM policies and resource permissions generated by SAM. It is
-- critical for ensuring that serverless functions (Lambda) do not have overly permissive
-- roles (Privilege Escalation), which is a major security risk in cloud environments.
-- KPIs: Security policy violation rate.
-- Feature Reference: F203
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.sam_policies (
    -- Primary Key
    policy_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    function_name VARCHAR(255) NOT NULL,
    policy_type VARCHAR(50) NOT NULL, -- e.g., 'LambdaExecutionRole', 'LogsRetention'

    -- Policy Definition
    policy_document JSONB NOT NULL,

    -- Security Constraints
    max_policy_size_kb INTEGER DEFAULT 10, -- AWS IAM limit
    forbidden_actions TEXT[], -- e.g., {'s3:DeleteBucket', 'iam:*'}
    required_boundary_arn VARCHAR(255), -- Permissions Boundary

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.sam_policies IS 'Validation rules for SAM IAM policies';

------------------------------------------------------------------------------------------------
-- Table: T204 - serverless_frameworks
-- Description: Validation rules for serverless.com framework configurations.
-- Business Case: The Serverless Framework is a popular tool for deploying multi-cloud functions.
-- This table validates the `serverless.yml` configuration. It ensures that handler
-- paths, environment variables, and plugin configurations are correct, preventing runtime
-- errors in continuous integration pipelines.
-- KPIs: CI/CD pipeline success rate.
-- Feature Reference: F204
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.serverless_frameworks (
    -- Primary Key
    service_name VARCHAR(100) NOT NULL,
    stage VARCHAR(50) NOT NULL DEFAULT 'dev',
    PRIMARY KEY (service_name, stage),

    -- Configuration
    provider VARCHAR(20) CHECK (provider IN ('AWS', 'AZURE', 'GOOGLE', 'ALIBABA')),
    runtime VARCHAR(50) NOT NULL, -- e.g., 'nodejs14.x', 'python3.9'

    -- Validation Rules
    required_plugins TEXT[], -- e.g., {'serverless-offline', 'serverless-iam-roles-per-function'}
    max_memory_mb INTEGER CHECK (max_memory_mb BETWEEN 128 AND 10240),
    max_timeout_sec INTEGER CHECK (max_timeout_sec BETWEEN 1 AND 900),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.serverless_frameworks IS 'Validation rules for serverless.com configurations';

------------------------------------------------------------------------------------------------
-- Table: T205 - openapi_specs
-- Description: Storage of OpenAPI/Swagger specification documents.
-- Business Case: OpenAPI defines the contract for REST APIs. This table stores the raw
-- OpenAPI spec (JSON/YAML). The validation engine (F205) uses this to validate that
-- incoming API requests (payloads, headers, paths) match the defined contract,
-- enforcing strict typing and schema compliance at the gateway level.
-- KPIs: API contract compliance rate.
-- Feature Reference: F205
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.openapi_specs (
    -- Primary Key
    spec_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    api_name VARCHAR(100) NOT NULL,
    version VARCHAR(50) NOT NULL, -- v1.0.0
    spec_type VARCHAR(20) DEFAULT 'SWAGGER_2_0', -- or OPENAPI_3_0

    -- Content
    spec_json JSONB NOT NULL, -- The OpenAPI Object
    base_url VARCHAR(255),

    -- State
    is_published BOOLEAN DEFAULT false,

    -- Constraints
    CONSTRAINT openapi_name_ver UNIQUE (api_name, version)
);

COMMENT ON TABLE core.openapi_specs IS 'Storage of OpenAPI/Swagger specifications';

------------------------------------------------------------------------------------------------
-- Table: T206 - asyncapi_specs
-- Description: Storage of AsyncAPI specification documents for event-driven architectures.
-- Business Case: AsyncAPI defines the contract for asynchronous APIs (Kafka, MQTT, WebSockets).
-- This table stores the AsyncAPI YAML/JSON. It validates that events published to the
-- event stream adhere to the defined message schemas, ensuring data integrity in
-- decoupled microservices.
-- KPIs: Event schema compliance rate.
-- Feature Reference: F206
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.asyncapi_specs (
    -- Primary Key
    spec_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    event_name VARCHAR(100) NOT NULL,
    version VARCHAR(50) NOT NULL,
    protocol VARCHAR(20), -- kafka, amqp, mqtt

    -- Content
    spec_json JSONB NOT NULL,
    channel_name VARCHAR(255) NOT NULL, -- e.g., 'user/signedup'

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Constraints
    CONSTRAINT asyncapi_name_ver UNIQUE (event_name, version)
);

COMMENT ON TABLE core.asyncapi_specs IS 'Storage of AsyncAPI specifications';

------------------------------------------------------------------------------------------------
-- Table: T207 - graphql_schemas
-- Description: Storage of GraphQL Schema Definition Language (SDL) definitions.
-- Business Case: GraphQL schemas define Types, Queries, and Mutations. This table stores
-- the SDL. It is used to validate incoming queries (Syntax, Type checking) and to ensure
-- that new schema changes do not break existing client integrations (Breaking changes).
-- KPIs: GraphQL query success rate.
-- Feature Reference: F207
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.graphql_schemas (
    -- Primary Key
    schema_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    service_name VARCHAR(100) NOT NULL,
    environment VARCHAR(20) NOT NULL, -- dev, prod

    -- Content
    schema_sdl TEXT NOT NULL, -- The full Schema Definition Language text

    -- Metadata
    description TEXT,

    -- State
    is_active BOOLEAN DEFAULT true,

    -- Constraints
    CONSTRAINT graphql_name_env UNIQUE (service_name, environment)
);

COMMENT ON TABLE core.graphql_schemas IS 'Storage of GraphQL SDL definitions';

------------------------------------------------------------------------------------------------
-- Table: T208 - raml_specs
-- Description: Storage and validation rules for RESTful API Modeling Language (RAML).
-- Business Case: RAML is an alternative to OpenAPI for API specification. This table stores
-- RAML files. It allows organizations using RAML to enforce validation rules for their
-- legacy or specific API contracts without migrating them to OpenAPI immediately.
-- KPIs: RAML API compliance rate.
-- Feature Reference: F208
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.raml_specs (
    -- Primary Key
    spec_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    title VARCHAR(255) NOT NULL,
    version VARCHAR(50) NOT NULL,

    -- Content
    raml_content TEXT NOT NULL, -- YAML formatted RAML
    base_uri VARCHAR(255),

    -- Constraints
    CONSTRAINT raml_title_ver UNIQUE (title, version)
);

COMMENT ON TABLE core.raml_specs IS 'Storage of RAML specifications';

------------------------------------------------------------------------------------------------
-- Table: T209 - api_blueprints
-- Description: Storage of API Blueprint (Markdown) specifications.
-- Business Case: API Blueprint is a Markdown-based API specification. This table stores
-- the raw Markdown content. It validates that documentation-driven development results in
-- valid API endpoints, ensuring that developers can generate mock servers or
-- documentation without manual errors.
-- KPIs: Blueprint validity score.
-- Feature Reference: F209
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.api_blueprints (
    -- Primary Key
    blueprint_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    api_name VARCHAR(100) NOT NULL,
    resource_group VARCHAR(100) NOT NULL

    -- Content
    blueprint_markdown TEXT NOT NULL,

    -- Constraints
    CONSTRAINT api_bp_name_group UNIQUE (api_name, resource_group)
);

COMMENT ON TABLE core.api_blueprints IS 'Storage of API Blueprint Markdown specs';

------------------------------------------------------------------------------------------------
-- Table: T210 - json_schema_draft7
-- Description: Registry of JSON Schema Draft 7 definitions.
-- Business Case: JSON Schema Draft 7 is a widely used standard for validating JSON data.
-- This table stores the specific schemas (F210). The validation engine retrieves these
-- schemas to validate incoming JSON payloads against complex structures (nested objects,
-- arrays), ensuring strict data typing.
-- KPIs: JSON validation accuracy.
-- Feature Reference: F210
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.json_schema_draft7 (
    -- Primary Key
    schema_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    name VARCHAR(100) NOT NULL,
    version VARCHAR(20) NOT NULL,

    -- Content
    schema_definition JSONB NOT NULL, -- Draft 7 format

    -- Constraints
    CONSTRAINT jsons_d7_name_ver UNIQUE (name, version)
);

COMMENT ON TABLE core.json_schema_draft7 IS 'JSON Schema Draft 7 definitions';

------------------------------------------------------------------------------------------------
-- Table: T211 - json_schema_draft2020
-- Description: Registry of JSON Schema Draft 2020-12 definitions.
-- Business Case: JSON Schema Draft 2020 is the latest standard with features like unevaluated
-- properties and content encoding. This table stores these modern schemas. Validating
-- against F211 ensures that the platform supports the latest JSON validation capabilities
-- and maintains forward compatibility.
-- KPIs: Modern JSON validation coverage.
-- Feature Reference: F211
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.json_schema_draft2020 (
    -- Primary Key
    schema_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    name VARCHAR(100) NOT NULL,
    version VARCHAR(20) NOT NULL,

    -- Content
    schema_definition JSONB NOT NULL, -- Draft 2020-12 format

    -- Constraints
    CONSTRAINT jsons_d20_name_ver UNIQUE (name, version)
);

COMMENT ON TABLE core.json_schema_draft2020 IS 'JSON Schema Draft 2020 definitions';

------------------------------------------------------------------------------------------------
-- Table: T212 - xml_schemas
-- Description: Storage of XML Schema Definitions (XSD).
-- Business Case: XSDs define the structure and data types of XML documents (e.g., SWIFT,
-- EDI). This table stores the XSD content. The validation engine uses it to ensure
-- incoming XML is well-formed and valid against the contract, preventing parsing errors
-- and data corruption.
-- KPIs: XML validation success rate.
-- Feature Reference: F212
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.xml_schemas (
    -- Primary Key
    xsd_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    target_namespace VARCHAR(255), -- e.g., 'urn:swift:xsd:$camt.053.001.08'
    version VARCHAR(50),

    -- Content
    xsd_content XML NOT NULL, -- The actual XSD

    -- Constraints
    CONSTRAINT xsd_ns_ver UNIQUE (target_namespace, version)
);

COMMENT ON TABLE core.xml_schemas IS 'XML Schema Definitions (XSD)';

------------------------------------------------------------------------------------------------
-- Table: T213 - dtd_validators
-- Description: Document Type Definitions (DTD) for legacy XML validation.
-- Business Case: DTD is an older standard for XML validation still used in some legacy systems
-- (e.g., older banking protocols). This table stores DTD content. It ensures compatibility
-- with legacy integrations by validating XML against DTD constraints where XSD is not
-- available.
-- KPIs: Legacy XML compatibility.
-- Feature Reference: F213
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.dtd_validators (
    -- Primary Key
    dtd_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    root_element VARCHAR(100) NOT NULL,
    system_id VARCHAR(255),

    -- Content
    dtd_content TEXT NOT NULL
);

COMMENT ON TABLE core.dtd_validators IS 'Document Type Definitions (DTD) for XML';

------------------------------------------------------------------------------------------------
-- Table: T214 - relaxng_validators
-- Description: RELAX NG schemas for XML validation.
-- Business Case: RELAX NG is a simpler, more powerful schema language for XML than XSD.
-- This table stores RELAX NG schemas. It provides validation capabilities for systems
-- or file formats that prefer RELAX NG over XSD, ensuring robust XML structure checking.
-- KPIs: XML validation flexibility.
-- Feature Reference: F214
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.relaxng_validators (
    -- Primary Key
    schema_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    name VARCHAR(100) NOT NULL,
    pattern_namespace VARCHAR(255),

    -- Content
    schema_content TEXT NOT NULL -- RELAX NG syntax
);

COMMENT ON TABLE core.relaxng_validators IS 'RELAX NG schemas for XML';

------------------------------------------------------------------------------------------------
-- Table: T215 - schematron_validators
-- Description: Schematron rules for XML business rule validation.
-- Business Case: Schematron allows expressing complex business rules that are difficult in XSD
-- (e.g., "If field A is 'X', field B must be greater than 100"). This table stores
-- these rule sets. It enables deep semantic validation of XML documents, ensuring data
-- integrity beyond simple syntax.
-- KPIs: Business rule violation detection.
-- Feature Reference: F215
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.schematron_validators (
    -- Primary Key
    rule_set_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    rule_set_name VARCHAR(100) NOT NULL,
    target_namespace VARCHAR(255),

    -- Content
    schematron_content XML NOT NULL -- Schematron XML

    -- Constraints
    CONSTRAINT schematron_name_ns UNIQUE (rule_set_name, target_namespace)
);

COMMENT ON TABLE core.schematron_validators IS 'Schematron rules for XML';

------------------------------------------------------------------------------------------------
-- Table: T216 - csv_schemas
-- Description: Schema definitions for CSV file validation.
-- Business Case: CSVs are a common format for bulk imports (e.g., merchant lists). This table
-- stores schemas defining column names, data types, and mandatory fields. Validating
-- CSVs against this schema (F216) prevents data type mismatches and missing columns during
-- bulk ingestion.
-- KPIs: CSV import success rate.
-- Feature Reference: F216
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.csv_schemas (
    -- Primary Key
    schema_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    schema_name VARCHAR(100) NOT NULL,
    version VARCHAR(50),

    -- Definition
    column_definitions JSONB NOT NULL, -- [{"name": "id", "type": "INT", "required": true}]
    has_header BOOLEAN DEFAULT true,
    delimiter CHAR(1) DEFAULT ','
);

COMMENT ON TABLE core.csv_schemas IS 'Schema definitions for CSV validation';

------------------------------------------------------------------------------------------------
-- Table: T217 - fixed_width_validators
-- Description: Definitions for fixed-width file formats.
-- Business Case: Mainframe and banking systems often use fixed-width files (no delimiters).
-- This table defines the start/end positions and data types for each field. It ensures
-- that parsing logic slices the file correctly, preventing data misalignment in
-- legacy data integration.
-- KPIs: Fixed-width parsing accuracy.
-- Feature Reference: F217
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.fixed_width_validators (
    -- Primary Key
    schema_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    file_type VARCHAR(50) NOT NULL, -- e.g., 'BANK_STATEMENT_V1'
    record_type VARCHAR(10), -- If multiple record types in one file

    -- Field Definitions (JSONB array of objects)
    field_definitions JSONB NOT NULL -- [{"field": "Date", "start": 1, "end": 8, "type": "DATE"}]
);

COMMENT ON TABLE core.fixed_width_validators IS 'Definitions for fixed-width file parsing';

------------------------------------------------------------------------------------------------
-- Table: T218 - edi_x12_validators
-- Description: Validation rules for EDI X12 segments (ISA, GS, ST, etc.).
-- Business Case: EDI X12 is the standard for B2B data exchange in North America (Healthcare,
-- Logistics). This table stores the structure of X12 segments and their allowed elements.
-- It validates that EDI messages adhere to the version and implementation guides.
-- KPIs: EDI processing success rate.
-- Feature Reference: F218
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.edi_x12_validators (
    -- Primary Key
    segment_id VARCHAR(10) NOT NULL,
    element_position INTEGER NOT NULL,
    PRIMARY KEY (segment_id, element_position),

    -- Attributes
    element_name VARCHAR(100),
    data_type VARCHAR(20) CHECK (data_type IN ('N0', 'N2', 'R', 'ID', 'AN')),
    min_length INTEGER,
    max_length INTEGER,

    -- Context
    version VARCHAR(10), -- e.g., '005010'
    required BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.edi_x12_validators IS 'Validation rules for EDI X12 segments';

------------------------------------------------------------------------------------------------
-- Table: T219 - edifact_validators
-- Description: Validation rules for UN/EDIFACT messages.
-- Business Case: UN/EDIFACT is the international EDI standard (Shipping, Customs). This table
-- stores segment tags, composite data elements, and their definitions. It ensures that
-- international trade messages are valid according to UN/ECE directories.
-- KPIs: International trade message validity.
-- Feature Reference: F219
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.edifact_validators (
    -- Primary Key
    segment_tag VARCHAR(6) NOT NULL, -- e.g., 'BGM', 'DTM'
    element_code VARCHAR(10) NOT NULL,
    PRIMARY KEY (segment_tag, element_code),

    -- Attributes
    element_name VARCHAR(100),
    data_type VARCHAR(20), -- a, an, n
    status VARCHAR(20), -- Mandatory, Conditional
    message_type VARCHAR(10) -- e.g., 'INVOIC'
);

COMMENT ON TABLE core.edifact_validators IS 'Validation rules for UN/EDIFACT messages';

------------------------------------------------------------------------------------------------
-- Table: T220 - hl7_fhir_validators
-- Description: Validation rules for HL7 FHIR resources.
-- Business Case: FHIR is the modern standard for exchanging healthcare data (Patients,
-- Observations). This table stores StructureDefinitions for FHIR resources. It ensures
-- that medical records exchanged between systems conform to FHIR specifications,
-- critical for patient safety and EHR integration.
-- KPIs: Healthcare data interoperability.
-- Feature Reference: F220
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.hl7_fhir_validators (
    -- Primary Key
    resource_type VARCHAR(100) NOT NULL, -- e.g., 'Patient', 'Encounter'
    resource_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    structure_definition JSONB NOT NULL, -- FHIR StructureDefinition JSON
    profile_url VARCHAR(255), -- Specific profile (e.g., US Core)

    -- Constraints
    CONSTRAINT fhir_resource_type UNIQUE (resource_type, profile_url)
);

COMMENT ON TABLE core.hl7_fhir_validators IS 'Validation rules for HL7 FHIR resources';

------------------------------------------------------------------------------------------------
-- Table: T221 - dicom_validators
-- Description: Validation rules for DICOM medical image headers.
-- Business Case: DICOM is the standard for medical imaging (MRI, CT). This table defines
-- mandatory tags (SOP Class UID, Transfer Syntax) and value representations. It validates
-- that medical image files have the correct metadata headers for processing by PACS
-- systems.
-- KPIs: Medical imaging processing success.
-- Feature Reference: F221
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.dicom_validators (
    -- Primary Key
    sop_class_uid VARCHAR(64) PRIMARY KEY, -- SOP Instance UID

    -- Attributes
    modality VARCHAR(10), -- CT, MR, US
    required_tags JSONB NOT NULL -- [{"tag": "00080016", "vr": "UI", "name": "SOP Class UID"}]
);

COMMENT ON TABLE core.dicom_validators IS 'Validation rules for DICOM headers';

------------------------------------------------------------------------------------------------
-- Table: T222 - fix_protocols
-- Description: Validation rules for Financial Information eXchange (FIX) protocols.
-- Business Case: FIX is the standard for electronic trading (Equities, FX, Derivatives). This
-- table stores the protocol version (FIX.4.2, FIX.5.0) and valid MsgTypes. It ensures
-- that financial trading messages conform to the FIX protocol, preventing rejection by
-- trading counterparties.
-- KPIs: FIX message acceptance rate.
-- Feature Reference: F222
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.fix_protocols (
    -- Primary Key
    begin_string VARCHAR(10) NOT NULL, -- e.g., FIX.4.4
    msg_type VARCHAR(10) NOT NULL, -- e.g., 'D' (NewOrderSingle)
    PRIMARY KEY (begin_string, msg_type),

    -- Attributes
    msg_name VARCHAR(100),
    required_fields JSONB, -- Array of tag numbers
    repeating_groups JSONB -- Definition of repeating groups
);

COMMENT ON TABLE core.fix_protocols IS 'Validation rules for FIX protocols';

------------------------------------------------------------------------------------------------
-- Table: T223 - iso8583_validators
-- Description: Validation rules for ISO 8583 card transaction messages.
-- Business Case: ISO 8583 defines the format for card-based financial transactions (ATM, POS).
-- This table defines the Bitmap and Data Elements layout. It validates MTI and Bitmaps
-- to ensure transaction messages are structurally correct before processing by the switch.
-- KPIs: Card processing success rate.
-- Feature Reference: F223
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.iso8583_validators (
    -- Primary Key
    mti VARCHAR(4) NOT NULL, -- Message Type Indicator
    bit_offset INTEGER NOT NULL, -- Position in bitmap (1-128)
    PRIMARY KEY (mti, bit_offset),

    -- Attributes
    element_name VARCHAR(100),
    data_type VARCHAR(20) CHECK (data_type IN ('n', 'an', 'ans', 'b')),
    length VARCHAR(10), -- 'LLVAR', 'FIXED', 'LLLVAR'

    -- Constraints
    CONSTRAINT iso8583_bit_check CHECK (bit_offset > 0 AND bit_offset <= 128)
);

COMMENT ON TABLE core.iso8583_validators IS 'Validation rules for ISO 8583 messages';

------------------------------------------------------------------------------------------------
-- Table: T224 - nacha_validators
-- Description: Validation rules for NACHA ACH file formats.
-- Business Case: NACHA rules govern the US ACH Network (Direct Deposit, Bill Pay). This table
-- defines the record layouts (File Header, Batch Header, Entry Detail). It validates
-- that ACH files meet formatting requirements to avoid rejection by the Federal Reserve.
-- KPIs: ACH file acceptance rate.
-- Feature Reference: F224
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.nacha_validators (
    -- Primary Key
    record_type_code CHAR(1) NOT NULL, -- e.g., '1' (File Header), '5' (Batch Header)
    field_position INTEGER NOT NULL,
    PRIMARY KEY (record_type_code, field_position),

    -- Attributes
    field_name VARCHAR(100),
    data_type VARCHAR(20), -- Alphabetic, Numeric, Alphanumeric
    field_length INTEGER NOT NULL,
    validation_rule TEXT -- Regex or logic
);

COMMENT ON TABLE core.nacha_validators IS 'Validation rules for NACHA ACH formats';

------------------------------------------------------------------------------------------------
-- Table: T225 - iso20022_validators
-- Description: Validation rules for ISO 20022 messages (XML).
-- Business Case: ISO 20022 is the global standard for financial messaging (SWIFT MX, SEPA).
-- This table stores the message definitions (BusinessApplicationHeader, Document). It
-- validates that payment messages conform to the specific MX variations required by
-- clearinghouses.
-- KPIs: High-value payment success rate.
-- Feature Reference: F225
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.iso20022_validators (
    -- Primary Key
    message_type VARCHAR(50) NOT NULL, -- e.g., 'pacs.008.001.02'
    element_xpath TEXT NOT NULL, -- XPath to element in XML
    PRIMARY KEY (message_type, element_xpath),

    -- Attributes
    element_name VARCHAR(100),
    data_type VARCHAR(50),
    is_mandatory BOOLEAN DEFAULT true,
    format_pattern TEXT
);

COMMENT ON TABLE core.iso20022_validators IS 'Validation rules for ISO 20022 messages';

------------------------------------------------------------------------------------------------
-- Table: T226 - swift_mt_validators
-- Description: Validation rules for SWIFT MT text fields.
-- Business Case: SWIFT MT is the traditional fixed-text format for interbank messaging. This
-- table defines the format for specific tags (fields) within MT messages (e.g., MT103,
-- MT202). It validates field content (Date, Amount, Format) to prevent manual data
-- entry errors.
-- KPIs: SWIFT message validity.
-- Feature Reference: F226
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.swift_mt_validators (
    -- Primary Key
    mt_number VARCHAR(3) NOT NULL, -- e.g., 103, 202
    field_tag VARCHAR(10) NOT NULL, -- e.g., 32A, 50K
    PRIMARY KEY (mt_number, field_tag),

    -- Attributes
    field_name VARCHAR(100),
    option_letter VARCHAR(1), -- A, B, C
    line_format TEXT, -- e.g., '6!n'
    validation_regex TEXT
);

COMMENT ON TABLE core.swift_mt_validators IS 'Validation rules for SWIFT MT fields';

------------------------------------------------------------------------------------------------
-- Table: T227 - realt_validators
-- Description: Validation rules for French REALT (Règlement de l'Instantané).
-- Business Case: REALT is the French instant payment scheme. This table stores the specific
-- XML schema or field constraints for REALT messages. It ensures that instant payments
-- initiated in France adhere to national standards and reach beneficiaries immediately.
-- KPIs: French instant payment success rate.
-- Feature Reference: F227
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.realt_validators (
    -- Primary Key
    message_type VARCHAR(50) PRIMARY KEY,

    -- Definition
    xsd_content XML,

    -- Specific Rules
    allowed_institutions TEXT[], -- French Bank IDs
    max_amount_eur NUMERIC(15,2)
);

COMMENT ON TABLE core.realt_validators IS 'Validation rules for French REALT instant transfers';

------------------------------------------------------------------------------------------------
-- Table: T228 - cor1_validators
-- Description: Validation rules for German COR1 instant payments.
-- Business Case: COR1 is the German instant payment scheme (Eiliges Zahlsystem). This
-- table validates the specifics of SEPA Credit Transfer with COR1 clearing. It ensures
-- that instant payments in Germany use the correct clearing codes and mandatory fields.
-- KPIs: German instant payment success rate.
-- Feature Reference: F228
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cor1_validators (
    -- Primary Key
    service_level VARCHAR(10) PRIMARY KEY, -- 'URGP' for COR1

    -- Rules
    mandatory_elements TEXT[], -- e.g., 'CdtrAgtAcct', 'ChrgBr'
    allowed_end2end_ids TEXT[] -- German bank codes
);

COMMENT ON TABLE core.cor1_validators IS 'Validation rules for German COR1 instant payments';

------------------------------------------------------------------------------------------------
-- Table: T229 - sct_inst_validators
-- Description: Validation rules for SEPA Instant Credit Transfer (SCT Inst).
-- Business Case: SCT Inst is the pan-European instant payment scheme. This table validates the
-- ISO 20022 specific rules for SCT Inst (e.g., 'SEPA' Creditor Scheme Identification
-- must be 'SEPA INST'). It ensures compliance with the EPC (European Payments Council)
-- rulebook.
-- KPIs: European instant payment compliance.
-- Feature Reference: F229
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.sct_inst_validators (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Constraints
    required_service_level VARCHAR(10) DEFAULT 'URGP',
    creditor_scheme_id_pattern VARCHAR(50) DEFAULT 'SEPA INST',

    -- Formatting
    payment_type_identification VARCHAR(35) DEFAULT 'SDVA'
);

COMMENT ON TABLE core.sct_inst_validators IS 'Validation rules for SEPA Instant Credit Transfer';

------------------------------------------------------------------------------------------------
-- Table: T230 - request_for_pay
-- Description: Validation rules for ISO 20022 Request for Pay (RfP) messages.
-- Business Case: RfP allows merchants to request payment from consumers (Open Banking).
-- This table validates the RfP message structure (Debtor Agent, Creditor Agent, Amount).
-- It ensures that the request is valid before being presented to the debtor's bank,
-- facilitating secure push-payments.
-- KPIs: RfP success rate.
-- Feature Reference: F230
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.request_for_pay (
    -- Primary Key
    rule_set_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identification
    initiating_party_role VARCHAR(50), -- e.g., 'MERCHANT'

    -- Validation Rules
    required_debtor_fields TEXT[], -- 'Nm', 'PstlAdr'
    required_creditor_fields TEXT[], -- 'Nm', 'Acct'

    -- Constraints
    max_expiry_hours INTEGER DEFAULT 24
);

COMMENT ON TABLE core.request_for_pay IS 'Validation rules for Request for Pay messages';

------------------------------------------------------------------------------------------------
-- Table: T231 - payment_initiation
-- Description: Validation rules for Open Banking Payment Initiation Service (PIS).
-- Business Case: PIS allows third parties to initiate payments on behalf of a user. This table
-- validates the Consent ID, Amount, and Beneficiary details against Open Banking
-- specifications (OBIE, Berlin Group). It prevents unauthorized or malformed payment
-- instructions.
-- KPIs: Open Banking payment success rate.
-- Feature Reference: F231
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.payment_initiation (
    -- Primary Key
    rule_set_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    consent_id_format VARCHAR(50) DEFAULT 'UUID',
    required_headers TEXT[] DEFAULT ARRAY['x-idempotency-key', 'x-fapi-interaction-id'],

    -- Constraints
    max_amount_eur NUMERIC(15,2),
    allowed_execution_modes TEXT[] DEFAULT ARRAY['IMMEDIATE', 'SCHEDULED']
);

COMMENT ON TABLE core.payment_initiation IS 'Validation rules for Payment Initiation Service';

------------------------------------------------------------------------------------------------
-- Table: T232 - account_information
-- Description: Validation rules for Open Banking Account Information Service (AIS).
-- Business Case: AIS allows third parties to access account data (Balances, Transactions).
-- This table validates the Consent ID, Permissions (Read Balances, Read Transactions),
-- and Date ranges. It ensures that data requests stay within the scope of user consent.
-- KPIs: Consent violation rate (should be 0).
-- Feature Reference: F232
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.account_information (
    -- Primary Key
    rule_set_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    permission_scope TEXT[] NOT NULL, -- 'ReadAccountsDetail', 'ReadBalances'
    max_date_range_days INTEGER DEFAULT 90, -- Max history access

    -- Constraints
    consent_required BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.account_information IS 'Validation rules for Account Information Service';

------------------------------------------------------------------------------------------------
-- Table: T233 - bulk_payment_rules
-- Description: Validation rules for bulk payment file structures.
-- Business Case: Enterprises use bulk payments (Payroll, Suppliers). This table validates
-- the aggregate control sums (hash total) and individual transaction counts within the
-- batch file. It prevents discrepancies where the header total does not match the sum of
-- lines, which causes rejection by clearing banks.
-- KPIs: Bulk payment rejection rate.
-- Feature Reference: F233
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.bulk_payment_rules (
    -- Primary Key
    batch_type VARCHAR(50) NOT NULL, -- 'PAYROLL', 'SUPPLIER'
    PRIMARY KEY (batch_type),

    -- Validation Rules
    require_control_sum BOOLEAN DEFAULT true,
    control_sum_algorithm VARCHAR(20), -- 'MOD97', 'SUM'
    max_transactions_per_batch INTEGER DEFAULT 50000,

    -- Headers
    required_header_fields TEXT[]
);

COMMENT ON TABLE core.bulk_payment_rules IS 'Validation rules for bulk payment files';

------------------------------------------------------------------------------------------------
-- Table: T234 - payroll_rules
-- Description: Validation rules for specific payroll file formats.
-- Business Case: Payroll files (e.g., NACHA PPD, UK BACS PAYMNL) have specific employee
-- fields (Tax ID, Net Pay). This table validates these formats. It ensures that
-- employees are paid correctly and that tax deductions are accurately reported to
-- government bodies.
-- KPIs: Payroll processing error rate.
-- Feature Reference: F234
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.payroll_rules (
    -- Primary Key
    jurisdiction_code CHAR(2) NOT NULL, -- ISO Country Code
    file_format VARCHAR(20) NOT NULL, -- 'ACH_PPD', 'BACS'
    PRIMARY KEY (jurisdiction_code, file_format),

    -- Field Definitions
    employee_id_field VARCHAR(50),
    net_pay_field VARCHAR(50),
    tax_field VARCHAR(50),

    -- Constraints
    enforce_tax_id_format BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.payroll_rules IS 'Validation rules for payroll files';

------------------------------------------------------------------------------------------------
-- Table: T235 - pension_rules
-- Description: Validation rules for pension contribution data.
-- Business Case: Pension contributions require specific data (Employee ID, Contribution %,
-- Scheme ID). This table validates that contributions fall within legal limits and that
-- scheme IDs are active. It ensures compliance with pension regulations (ERISA in US,
-- Auto-Enrolment in UK).
-- KPIs: Pension compliance rate.
-- Feature Reference: F235
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.pension_rules (
    -- Primary Key
    scheme_id VARCHAR(50) PRIMARY KEY,

    -- Rules
    jurisdiction VARCHAR(50),
    min_contribution_percent NUMERIC(5,2),
    max_contribution_percent NUMERIC(5,2),

    -- Validation
    require_employee_consent BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.pension_rules IS 'Validation rules for pension contributions';

------------------------------------------------------------------------------------------------
-- Table: T236 - tax_submission_rules
-- Description: Validation rules for submitting data to tax authorities (SII, etc.).
-- Business Case: Direct reporting of transaction data to tax authorities (SII in Chile,
-- VAT in Italy) requires strict format adherence. This table validates the XML/JSON
-- payloads sent to tax APIs, ensuring they are not rejected for format errors, which
-- would cause delays in tax deductions.
-- KPIs: Tax submission success rate.
-- Feature Reference: F236
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.tax_submission_rules (
    -- Primary Key
    country_code CHAR(2) NOT NULL,
    tax_authority VARCHAR(100) NOT NULL, -- e.g., 'AEAT', 'IRS'
    PRIMARY KEY (country_code, tax_authority),

    -- Validation
    required_signature BOOLEAN DEFAULT true,
    xml_namespace VARCHAR(255),
    required_fields TEXT[]
);

COMMENT ON TABLE core.tax_submission_rules IS 'Validation rules for tax authority submissions';

------------------------------------------------------------------------------------------------
-- Table: T237 - customs_rules
-- Description: Validation rules for customs export/import data (WCO).
-- Business Case: Customs declarations require Harmonized System (HS) codes and valuation.
-- This table validates HS codes and ensures that declared weights/values are within logical
-- ranges. It prevents goods from being held at borders due to administrative errors.
-- KPIs: Customs clearance success rate.
-- Feature Reference: F237
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.customs_rules (
    -- Primary Key
    country_code CHAR(2) NOT NULL,
    PRIMARY KEY (country_code),

    -- Rules
    required_hs_codes BOOLEAN DEFAULT true,
    max_weight_tolerance_percent NUMERIC(5,2) DEFAULT 10.0,
    require_tariff_code BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.customs_rules IS 'Validation rules for customs declarations';

------------------------------------------------------------------------------------------------
-- Table: T238 - insurance_claim_rules
-- Description: Validation rules for ACORD XML insurance claims.
-- Business Case: ACORD is the standard for insurance data exchange. This table validates the
-- claim structure (Policy ID, Incident Date, Coverage Code). It ensures that claims
-- are processed correctly and are valid against the insurance contract.
-- KPIs: Claim processing accuracy.
-- Feature Reference: F238
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.insurance_claim_rules (
    -- Primary Key
    claim_type VARCHAR(50) NOT NULL, -- 'Property', 'Auto'
    PRIMARY KEY (claim_type),

    -- Validation
    required_coverage_codes TEXT[],
    max_claim_amount NUMERIC(15,2),
    required_incident_details TEXT[] -- 'Date', 'Location', 'Description'
);

COMMENT ON TABLE core.insurance_claim_rules IS 'Validation rules for insurance claims (ACORD)';

------------------------------------------------------------------------------------------------
-- Table: T239 - healthcare_claim_rules
-- Description: Validation rules for Healthcare claims (FHIR/CDA).
-- Business Case: Healthcare claims involve Diagnosis Codes (ICD-10) and Procedure Codes (CPT).
-- This table validates that these codes are active and compatible. It prevents rejected
-- claims by insurers due to invalid or deprecated medical codes.
-- KPIs: Healthcare claim acceptance rate.
-- Feature Reference: F239
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.healthcare_claim_rules (
    -- Primary Key
    code_set VARCHAR(20) NOT NULL, -- 'ICD10', 'CPT'
    PRIMARY KEY (code_set),

    -- Validation
    check_code_expiration BOOLEAN DEFAULT true,
    allowed_code_ranges TEXT[], -- e.g., 'A00-B99' for ICD-10
    require_provider_npi BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.healthcare_claim_rules IS 'Validation rules for healthcare claims';

------------------------------------------------------------------------------------------------
-- Table: T240 - geospatial_geometry
-- Description: Validation rules for Geospatial geometry (GeoJSON/WKT).
-- Business Case: Validates location data (Points, Polygons) used in logistics or fraud detection.
-- This table defines acceptable geometry types and coordinate precision. It ensures that
-- geometry data is valid (e.g., closed polygons) so that it can be indexed and queried
-- for distance or area calculations.
-- KPIs: Location data validity.
-- Feature Reference: F240
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.geospatial_geometry (
    -- Primary Key
    geometry_type VARCHAR(20) NOT NULL, -- Point, LineString, Polygon
    PRIMARY KEY (geometry_type),

    -- Constraints
    allowed_crs VARCHAR(20) DEFAULT 'EPSG:4326', -- WGS84
    max_coordinate_precision INTEGER DEFAULT 7,
    require_valid_structure BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.geospatial_geometry IS 'Validation rules for Geospatial geometry';

------------------------------------------------------------------------------------------------
-- Table: T241 - elevation_data
-- Description: Validation rules for Elevation/Altitude data.
-- Business Case: Elevation is critical for drone delivery or logistics. This table validates
-- the range (e.g., Death Valley to Mt. Everest) and units (Meters/Feet). It prevents
-- invalid altitude inputs that could cause errors in navigation or 3D modeling.
-- KPIs: Altitude data accuracy.
-- Feature Reference: F241
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.elevation_data (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    allowed_units TEXT[] DEFAULT ARRAY{'METERS', 'FEET'},
    min_value NUMERIC(10,2) DEFAULT -500.0, -- Dead Sea
    max_value NUMERIC(10,2) DEFAULT 8848.0 -- Everest
);

COMMENT ON TABLE core.elevation_data IS 'Validation rules for elevation data';

------------------------------------------------------------------------------------------------
-- Table: T242 - polygon_rules
-- Description: Rules for validating Polygon geometry (Closure).
-- Business Case: Polygons (e.g., geofences, delivery zones) must be closed (First point == Last
-- point) and non-self-intersecting. This table defines these constraints to ensure
-- that geometric calculations (area, containment) work correctly.
-- KPIs: Geofence validity.
-- Feature Reference: F242
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.polygon_rules (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    force_closure BOOLEAN DEFAULT true, -- Check if last point matches first
    allow_self_intersection BOOLEAN DEFAULT false,
    max_coordinate_pairs INTEGER DEFAULT 1000
);

COMMENT ON TABLE core.polygon_rules IS 'Rules for validating Polygon geometry';

------------------------------------------------------------------------------------------------
-- Table: T243 - tile_coords
-- Description: Validation rules for Map tile coordinates (X, Y, Zoom).
-- Business Case: Map tile servers use XYZ coordinates. This table validates that X and Y are
-- within the valid range for the given Zoom level (0-22). It prevents requests for
-- non-existent tiles, reducing server load.
-- KPIs: Map tile hit rate.
-- Feature Reference: F243
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.tile_coords (
    -- Primary Key
    zoom_level INTEGER NOT NULL,
    PRIMARY KEY (zoom_level),

    -- Constraints
    max_x_axis INTEGER NOT NULL, -- 2^zoom - 1
    max_y_axis INTEGER NOT NULL
);

COMMENT ON TABLE core.tile_coords IS 'Validation rules for Map tile coordinates';

------------------------------------------------------------------------------------------------
-- Table: T244 - geohash_rules
-- Description: Validation rules for Geohash strings.
-- Business Case: Geohash encodes geographic coordinates into a short string. This table
-- validates the character set (Base32) and length (precision). It ensures that Geohash
-- lookups (e.g., for nearby users) function correctly.
-- KPIs: Geohash lookup success rate.
-- Feature Reference: F244
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.geohash_rules (
    -- Primary Key
    geohash_length INTEGER NOT NULL,
    PRIMARY KEY (geohash_length),

    -- Attributes
    allowed_chars VARCHAR(32) DEFAULT '0123456789bcdefghjkmnpqrstuvwxyz',
    precision_meters NUMERIC(10,2), -- Approximate resolution
    latitude_range CHAR(1) CHECK (latitude_range IN ('N', 'S'))
);

COMMENT ON TABLE core.geohash_rules IS 'Validation rules for Geohash strings';

------------------------------------------------------------------------------------------------
-- Table: T245 - plus_codes
-- Description: Validation rules for Open Location Code (Plus Code).
-- Business Case: Plus Codes (What3Words alternative) provide a standardized addressing system.
-- This table validates the Plus Code format (8+XXXXXX). It ensures that addresses are
-- correctly encoded for delivery or emergency services.
-- KPIs: Plus Code delivery success rate.
-- Feature Reference: F245
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.plus_codes (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Rules
    full_length INTEGER DEFAULT 11, -- 8 + 3
    short_length INTEGER DEFAULT 8,
    character_set VARCHAR(20) DEFAULT '23456789CFGHJMPQRVWX'
);

COMMENT ON TABLE core.plus_codes IS 'Validation rules for Open Location Codes';

------------------------------------------------------------------------------------------------
-- Table: T246 - w3w_rules
-- Description: Validation rules for What3Words addresses.
-- Business Case: What3Words uses 3 words to define a 3m x 3m square. This table validates
-- that the 3 words are valid words in the W3W dictionary and correctly formatted.
-- It ensures accurate routing for emergency services or logistics in unmapped areas.
-- KPIs: W3W routing success rate.
-- Feature Reference: F246
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.w3w_rules (
    -- Primary Key
    language_code CHAR(2) NOT NULL, -- e.g., 'en', 'es'
    PRIMARY KEY (language_code),

    -- Rules
    separator VARCHAR(1) DEFAULT '.', -- Standard dot separator
    max_word_length INTEGER DEFAULT 15,
    min_word_length INTEGER DEFAULT 3
);

COMMENT ON TABLE core.w3w_rules IS 'Validation rules for What3Words addresses';

------------------------------------------------------------------------------------------------
-- Table: T247 - container_ids
-- Description: Validation rules for ISO 6346 Container IDs.
-- Business Case: Shipping containers have a unique 11-character ID (Owner Code, Serial
-- Number, Check Digit). This table validates the check digit to prevent data entry errors
-- in logistics tracking.
-- KPIs: Container tracking accuracy.
-- Feature Reference: F247
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.container_ids (
    -- Primary Key
    owner_code CHAR(4) NOT NULL, -- e.g., 'ABCD'
    PRIMARY KEY (owner_code),

    -- Attributes
    equipment_category_id INTEGER, -- U, J, Z, etc.
    checksum_algorithm VARCHAR(20) DEFAULT 'ISO6346',

    -- Constraints
    CONSTRAINT owner_code_upper CHECK (owner_code ~ '^[A-Z]{4}$')
);

COMMENT ON TABLE core.container_ids IS 'Validation rules for ISO 6346 Container IDs';

------------------------------------------------------------------------------------------------
-- Table: T248 - vin_rules
-- Description: Validation rules for Vehicle Identification Numbers (VIN).
-- Business Case: VINs uniquely identify motor vehicles. This table validates the structure
-- (WMI, VDS, VIS) and the check digit (Transliteration + Mod 11). It prevents
-- registration of non-existent or fraudulent vehicle identifiers.
-- KPIs: Vehicle registration accuracy.
-- Feature Reference: F248
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.vin_rules (
    -- Primary Key
    wmi_code CHAR(3) PRIMARY KEY, -- World Manufacturer Identifier

    -- Attributes
    manufacturer_name VARCHAR(255),
    country_code CHAR(2),
    region VARCHAR(50)
);

COMMENT ON TABLE core.vin_rules IS 'Validation rules for VIN World Manufacturer Identifiers';

------------------------------------------------------------------------------------------------
-- Table: T249 - license_plates
-- Description: Validation rules for License Plates per jurisdiction.
-- Business Case: License plates follow varied patterns (Alphanumeric, special chars). This table
-- stores the regex and length rules for each country/state. It ensures that license
-- plate inputs are valid for their claimed jurisdiction (e.g., Parking, Tolling).
-- KPIs: License plate validation accuracy.
-- Feature Reference: F249
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.license_plates (
    -- Primary Key
    country_code CHAR(2) NOT NULL,
    plate_type VARCHAR(50) NOT NULL, -- e.g., 'STANDARD', 'VETERAN'
    PRIMARY KEY (country_code, plate_type),

    -- Validation
    regex_pattern TEXT NOT NULL,
    max_length INTEGER,
    allowed_special_chars TEXT -- e.g., '-. '
);

COMMENT ON TABLE core.license_plates IS 'Validation rules for License Plates';

------------------------------------------------------------------------------------------------
-- Table: T250 - isbn_rules
-- Description: Validation rules for ISBN (International Standard Book Number).
-- Business Case: ISBNs uniquely identify books. This table stores the rules for ISBN-10
-- (Mod 11) and ISBN-13 (Mod 10). It validates the check digit to ensure library
-- and retail databases reference the correct titles.
-- KPIs: Book lookup accuracy.
-- Feature Reference: F250
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.isbn_rules (
    -- Primary Key
    isbn_type VARCHAR(10) NOT NULL, -- 'ISBN10', 'ISBN13'
    PRIMARY KEY (isbn_type),

    -- Attributes
    length INTEGER NOT NULL, -- 10 or 13
    modulus_algorithm VARCHAR(10) NOT NULL, -- 'MOD11', 'MOD10'
    prefix_ranges TEXT[] -- 978-979 for ISBN13
);

COMMENT ON TABLE core.isbn_rules IS 'Validation rules for ISBN numbers';

-- ================================================================================================
-- 5. ENTITY RELATIONSHIPS AND CONSTRAINTS (Foreign Keys - Part 5)
-- ================================================================================================

-- T225 (iso20022_validators) - No direct FK in this table, but logic applies to T226 (SWIFT).
-- T240 (geospatial_geometry) - General purpose table.

-- ================================================================================================
-- 6. TRIGGERS FOR AUDIT COLUMNS (Part 5)
-- ================================================================================================

-- Apply the update_updated_at trigger to Part 5 tables
DO $$ DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT table_name
             FROM information_schema.tables
             WHERE table_schema = 'core'
             AND table_name IN (
                 'cloudformation_templates', 'arm_templates', 'sam_policies',
                 'openapi_specs', 'asyncapi_specs', 'graphql_schemas',
                 'edi_x12_validators', 'edifact_validators', 'hl7_fhir_validators',
                 'fix_protocols', 'iso8583_validators', 'nacha_validators',
                 'iso20022_validators', 'swift_mt_validators', 'geospatial_geometry'
             )
    LOOP
        EXECUTE format('CREATE TRIGGER trigger_update_%s BEFORE UPDATE ON core.%I FOR EACH ROW EXECUTE FUNCTION core.trigger_update_updated_at()', r.table_name, r.table_name);
    END LOOP;
END$$;

-- ================================================================================================
-- END OF SCRIPT - PART 5 (T201-T250)
