------------------------------------------------------------------------------------------------
-- Table: T251 - ean_upc_validation
-- Description: Validation rules for EAN and UPC barcodes.
-- Business Case: EAN (13 digits) and UPC (12 digits) barcodes are the global standard for
-- product identification in retail. This table stores the check digit algorithm (Mod 10)
-- and validates the structure. Ensuring barcodes are valid at ingestion prevents
-- incorrect product lookups, pricing errors, and inventory discrepancies in the PARI
-- retail/POS modules.
-- KPIs: Barcode lookup success rate.
-- Feature Reference: F251
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.ean_upc_validation (
    -- Primary Key
    barcode_type VARCHAR(10) PRIMARY KEY, -- 'EAN13', 'UPC12', 'EAN8'

    -- Attributes
    length INTEGER NOT NULL,
    check_digit_algorithm VARCHAR(20) DEFAULT 'MOD10',

    -- Constraints
    CONSTRAINT barcode_length_positive CHECK (length > 0)
);

COMMENT ON TABLE core.ean_upc_validation IS 'Validation rules for EAN/UPC barcodes';

------------------------------------------------------------------------------------------------
-- Table: T252 - sku_format_validation
-- Description: Validation rules for Stock Keeping Unit (SKU) formats.
-- Business Case: SKUs are internal codes for inventory. Different merchants use different
-- formats (alphanumeric, specific prefixes). This table stores regex patterns per
-- merchant to validate that SKUs match their expected format, reducing bad data
-- in inventory management systems.
-- KPIs: Inventory record accuracy.
-- Feature Reference: F252
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.sku_format_validation (
    -- Primary Key
    merchant_id UUID NOT NULL,
    sku_type VARCHAR(50) NOT NULL, -- e.g., 'APPAREL', 'ELECTRONICS'
    PRIMARY KEY (merchant_id, sku_type),

    -- Attributes
    format_regex TEXT NOT NULL,
    prefix_pattern VARCHAR(50),
    example_sku VARCHAR(100),

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID NOT NULL,
    updated_by UUID NOT NULL
);

COMMENT ON TABLE core.sku_format_validation IS 'Regex patterns for SKU validation per merchant';

------------------------------------------------------------------------------------------------
-- Table: T253 - hs_code_validation
-- Description: Validation rules for Harmonized System (HS) codes.
-- Business Case: HS codes classify goods for customs duty calculation. They are typically
-- 4 to 10 digits. This table validates that codes follow the correct digit length
-- and hierarchical structure. It prevents customs declaration errors that could lead
-- to fines or delays.
-- KPIs: Customs declaration accuracy.
-- Feature Reference: F253
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.hs_code_validation (
    -- Primary Key
    hs_code VARCHAR(10) PRIMARY KEY, -- Can be 4, 6, 8, or 10 digits

    -- Attributes
    description TEXT,
    valid_from DATE,
    valid_until DATE,

    -- Constraints
    CONSTRAINT hs_code_format CHECK (hs_code ~ '^[0-9]{4,10}$')
);

COMMENT ON TABLE core.hs_code_validation IS 'Harmonized System codes for customs validation';

------------------------------------------------------------------------------------------------
-- Table: T254 - tariff_code_validation
-- Description: Validation rules for import/export tariff codes.
-- Business Case: Tariff codes determine the specific duty rate for a product in a specific
-- country. This table maps HS codes (or specific national codes) to tariff codes.
-- Validating that the combination is valid ensures that financial liability (tax)
-- is calculated correctly.
-- KPIs: Duty calculation accuracy.
-- Feature Reference: F254
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.tariff_code_validation (
    -- Primary Key
    country_code CHAR(2) NOT NULL,
    tariff_code VARCHAR(20) NOT NULL,
    PRIMARY KEY (country_code, tariff_code),

    -- Attributes
    hs_code_root VARCHAR(10) NOT NULL,
    description TEXT,
    duty_rate NUMERIC(10,4),

    -- Constraints
    CONSTRAINT tariff_country_fk FOREIGN KEY (country_code) REFERENCES core.iso_3166_countries(alpha_2_code)
);

COMMENT ON TABLE core.tariff_code_validation IS 'Import/Export tariff codes';

