------------------------------------------------------------------------------------------------
-- Table: J001 - junction_rule_error_codes
-- Description: Maps rules to specific error codes.
-- Business Case: A single validation rule might fail in multiple ways or have different
-- severity levels depending on context. This junction table allows a many-to-many
-- relationship between rules (T001) and error codes (T006), enabling granular
-- error reporting (e.g., "Syntax Error" vs "Range Error") from the same rule engine.
-- KPIs: Error reporting granularity.
-- Feature Reference: T001, T006
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.junction_rule_error_codes (
    -- Primary Key
    rule_id UUID NOT NULL,
    error_code VARCHAR(50) NOT NULL,
    PRIMARY KEY (rule_id, error_code),

    -- Foreign Keys
    CONSTRAINT fk_rule_error_rule FOREIGN KEY (rule_id) REFERENCES core.validation_rules(id) ON DELETE CASCADE,
    CONSTRAINT fk_rule_error_code FOREIGN KEY (error_code) REFERENCES core.error_codes_registry(code) ON DELETE CASCADE
);

COMMENT ON TABLE core.junction_rule_error_codes IS 'Many-to-many mapping of rules to error codes';

------------------------------------------------------------------------------------------------
-- Table: J002 - junction_table_columns
-- Description: Maps rules to specific table columns.
-- Business Case: Validation rules (T001) often apply to specific columns across different
-- tables. This junction table maps a generic rule definition to the concrete
-- `schema.table.column` path. It allows the rule engine to apply constraints
-- like "IBAN Mod 97" to `payment.iban` and `refund.iban` separately.
-- KPIs: Rule reuse efficiency.
-- Feature Reference: T001, T010
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.junction_table_columns (
    -- Primary Key
    rule_id UUID NOT NULL,
    table_name VARCHAR(255) NOT NULL,
    column_name VARCHAR(255) NOT NULL,
    PRIMARY KEY (rule_id, table_name, column_name),

    -- Attributes
    is_active BOOLEAN DEFAULT true,

    -- Foreign Keys
    CONSTRAINT fk_table_col_rule FOREIGN KEY (rule_id) REFERENCES core.validation_rules(id) ON DELETE CASCADE
);

COMMENT ON TABLE core.junction_table_columns IS 'Maps rules to specific table columns';

------------------------------------------------------------------------------------------------
-- Table: J003 - junction_regex_countries
-- Description: Maps regex patterns to countries.
-- Business Case: A generic regex (e.g., "Phone Number") might have specific variations
-- per country (e.g., USA length 10, UK length 11). This table links regex
-- patterns (T008) to country codes (T004), allowing the validation engine
-- to select the correct pattern based on the user's locale.
-- KPIs: Validation localization accuracy.
-- Feature Reference: T008, T004
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.junction_regex_countries (
    -- Primary Key
    pattern_id UUID NOT NULL,
    country_code CHAR(2) NOT NULL,
    PRIMARY KEY (pattern_id, country_code),

    -- Foreign Keys
    CONSTRAINT fk_regex_country_pattern FOREIGN KEY (pattern_id) REFERENCES core.regex_patterns(id) ON DELETE CASCADE,
    CONSTRAINT fk_regex_country_code FOREIGN KEY (country_code) REFERENCES core.iso_3166_countries(alpha_2_code) ON DELETE CASCADE
);

COMMENT ON TABLE core.junction_regex_countries IS 'Maps regex patterns to country codes';

------------------------------------------------------------------------------------------------
-- Table: J004 - junction_mcc_groups
-- Description: Maps MCCs to business groups.
-- Business Case: For high-level reporting, individual 4-digit MCCs need to be grouped
-- (e.g., all MCCs 5811-5813 are 'RESTAURANTS'). This table maps the
-- specific MCCs (T015) to their business groups (E007), enabling aggregated
-- analytics.
-- KPIs: Aggregation accuracy.
-- Feature Reference: T015
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.junction_mcc_groups (
    -- Primary Key
    mcc CHAR(4) NOT NULL,
    group_id VARCHAR(20) NOT NULL,
    PRIMARY KEY (mcc, group_id),

    -- Foreign Keys
    CONSTRAINT fk_mcc_group_code FOREIGN KEY (mcc) REFERENCES core.merchant_category_codes(mcc) ON DELETE CASCADE,
    CONSTRAINT fk_mcc_group_id FOREIGN KEY (group_id) REFERENCES core.enum_mcc_group
);

COMMENT ON TABLE core.junction_mcc_groups IS 'Maps MCCs to business groups';

------------------------------------------------------------------------------------------------
-- Table: J005 - junction_api_keys_tenants
-- Description: Assigns API keys to tenants.
-- Business Case: API keys (T047) can be scoped to a specific tenant (T048) in a
-- multi-tenant platform. This junction enforces that an API key used in a
-- request belongs to the correct tenant context, preventing cross-tenant data access.
-- KPIs: Multi-tenant isolation integrity.
-- Feature Reference: T047, T048
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.junction_api_keys_tenants (
    -- Primary Key
    key_hash VARCHAR(64) NOT NULL,
    tenant_id UUID NOT NULL,
    PRIMARY KEY (key_hash, tenant_id),

    -- Attributes
    scope_override TEXT[], -- Tenant-specific scope additions

    -- Foreign Keys
    CONSTRAINT fk_apikey_tenant_key FOREIGN KEY (key_hash) REFERENCES core.api_keys(key_hash) ON DELETE CASCADE,
    CONSTRAINT fk_apikey_tenant_id FOREIGN KEY (tenant_id) REFERENCES core.tenants(tenant_id) ON DELETE CASCADE
);

COMMENT ON TABLE core.junction_api_keys_tenants IS 'Assigns API keys to tenants';

------------------------------------------------------------------------------------------------
-- Table: J006 - junction_user_roles
