    role VARCHAR(50) NOT NULL,
    PRIMARY KEY (user_id, role)
);

COMMENT ON TABLE core.junction_user_roles IS 'Assigns roles to users';

------------------------------------------------------------------------------------------------
-- Table: J007 - junction_feature_flags_tenants
-- Description: Enables features per tenant.
-- Business Case: Features (T049) are rolled out gradually. This table specifies which
