    PRIMARY KEY (flag_key, tenant_id),

    -- Attributes
    enabled_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Foreign Keys
    CONSTRAINT fk_featflag_key FOREIGN KEY (flag_key) REFERENCES core.feature_flags(flag_key) ON DELETE CASCADE,
    CONSTRAINT fk_featflag_tenant FOREIGN KEY (tenant_id) REFERENCES core.tenants(tenant_id) ON DELETE CASCADE
);

COMMENT ON TABLE core.junction_feature_flags_tenants IS 'Enables features per tenant';

------------------------------------------------------------------------------------------------
-- Table: J008 - junction_pii_data
-- Description: Links PII fields to data objects.
-- Business Case: PII Classification (T081) defines that a field is PII. This table
