    table_name VARCHAR(255) NOT NULL,
    PRIMARY KEY (field_path, table_name),

    -- Foreign Keys
    CONSTRAINT fk_pii_field FOREIGN KEY (field_path) REFERENCES core.pii_classification(field_path) ON DELETE CASCADE
);

COMMENT ON TABLE core.junction_pii_data IS 'Links PII fields to table columns';

------------------------------------------------------------------------------------------------
-- Table: J009 - junction_kyc_documents
-- Description: Links KYC checks to document types.
-- Business Case: Different KYC levels (E009) require different documents (T067). This table
