COMMENT ON TABLE core.junction_kyc_documents IS 'Links KYC levels to required documents';

------------------------------------------------------------------------------------------------
-- Table: J010 - junction_sanctions_lists
-- Description: Aggregates multiple sanctions lists.
-- Business Case: Sanctions screening involves multiple lists (OFAC, EU, UN). This table
