    list_name VARCHAR(50) NOT NULL,
    entry_id VARCHAR(100) NOT NULL,
    PRIMARY KEY (list_name, entry_id),

    -- Foreign Keys
    CONSTRAINT fk_sanc_list FOREIGN KEY (list_name, entry_id) REFERENCES core.sanctions_lists(list_name, entry_id) ON DELETE CASCADE
);

COMMENT ON TABLE core.junction_sanctions_lists IS 'Aggregates sanctions list entries';

------------------------------------------------------------------------------------------------
-- Table: J011 - junction_exchange_currencies
-- Description: Defines supported currencies per exchange.
-- Business Case: A crypto or forex exchange (T034) might only support specific trading
