    is_withdraw_enabled BOOLEAN DEFAULT true,

    -- Foreign Keys
    CONSTRAINT fk_exch_curr_code FOREIGN KEY (currency_code) REFERENCES core.currencies_active(currency_code) ON DELETE CASCADE
