-- KPIs: Merchant payment success.
-- Feature Reference: T033, T069
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.junction_merchant_currencies (
    -- Primary Key
    merchant_id UUID NOT NULL,
    currency_code CHAR(3) NOT NULL,
    PRIMARY KEY (merchant_id, currency_code),

    -- Attributes
    is_default BOOLEAN DEFAULT false,

    -- Foreign Keys
    CONSTRAINT fk_merc_curr_code FOREIGN KEY (currency_code) REFERENCES core.currencies_active(currency_code) ON DELETE CASCADE
