COMMENT ON TABLE core.junction_merchant_currencies IS 'Accepted currencies per merchant';

------------------------------------------------------------------------------------------------
-- Table: J013 - junction_card_brands_mcc
-- Description: Associates card brands with MCC categories.
-- Business Case: Interchange rates and risk profiles vary by card brand (Visa vs Amex) and
-- Merchant Category (Restaurant vs Grocery). This junction table defines these
-- associations, allowing the validation engine to apply specific brand rules to
-- specific MCC groups.
-- KPIs: Interchange accuracy.
-- Feature Reference: F118, F011
------------------------------------------------------------------------------------------------
