------------------------------------------------------------------------------------------------
-- Table: J014 - junction_translation_errors
-- Description: Translations for error messages.
-- Business Case: Error messages must be localized for international users. This table (J014)
-- links a technical error code (T006) to a specific language code (E003) and
-- provides the human-readable message in that language.
-- KPIs: Localization coverage.
-- Feature Reference: T006, T070
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.junction_translation_errors (
