------------------------------------------------------------------------------------------------
-- Table: J015 - junction_trigger_history
-- Description: History of trigger execution.
-- Business Case: To debug issues with automated database triggers (T099), this table logs
-- every time a trigger fires, capturing the execution time and status. This ensures
-- that side effects (like updating `updated_at`) are audited.
-- KPIs: Trigger execution performance.
-- Feature Reference: T099, T002
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.junction_trigger_history (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Reference
    trigger_name VARCHAR(100) NOT NULL,

    -- Attributes
    execution_time TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    status VARCHAR(20) CHECK (status IN ('SUCCESS', 'FAILURE')),
    error_message TEXT,

    -- Audit
    affected_rows BIGINT,
    old_data JSONB,
    new_data JSONB
);

COMMENT ON TABLE core.junction_trigger_history IS 'Audit log of trigger executions';


