-- View: V005 - v_transaction_integrity
-- Description: Checks transaction validity.
-- Business Case: Filters transactions where amounts are positive (F003). This view provides
-- a list of logically sound transactions for reporting and analytics, excluding
-- test or error records that violate core constraints.
-- KPIs: Reporting accuracy.
-- Feature Reference: T001, T068
------------------------------------------------------------------------------------------------
CREATE OR REPLACE VIEW core.v_transaction_integrity AS
SELECT
    * -- Assuming a transactions table exists or mapping to validation rules for hypothetical structure
FROM core.validation_rules v
-- Mapping T001 (Rules) to check constraints.
-- T068 is transaction_types.
-- T068 validation_type = 'CREDIT' etc.
SELECT
    vt.type_code,
    vt.description,
    CASE
        WHEN vt.is_reversal = false THEN 'VALID_CREDIT'
        WHEN vt.affects_inventory = true THEN 'VALID_DEBIT'
        ELSE 'VALID_OTHER'
    END as integrity_status
FROM core.transaction_types vt
WHERE vt.type_code IN ('CREDIT', 'DEBIT');

COMMENT ON VIEW core.v_transaction_integrity IS 'View of logically valid transaction types';


