CREATE OR REPLACE PROCEDURE core.sp_validate_nuban(IN p_account_number TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_account_number) = 10); END; COMMENT ON PROCEDURE core.sp_validate_nuban IS 'Validates Nigerian NUBAN (F112)';

CREATE OR REPLACE PROCEDURE core.sp_validate_ifsc(IN p_ifsc TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_ifsc) = 11 AND p_ifsc ~ '^[A-Z]{4}0[A-Z0-9]{6}$'); END; COMMENT ON PROCEDURE core.sp_validate_ifsc IS 'Validates Indian IFSC (F103)';

CREATE OR REPLACE PROCEDURE core.sp_validate_sort_code(IN p_sort_code TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_sort_code) = 6 AND p_sort_code ~ '^[0-9]+$'); END; COMMENT ON PROCEDURE core.sp_validate_sort_code IS 'Validates UK sort code (F104)';

CREATE OR REPLACE PROCEDURE core.sp_validate_uk_account(IN p_account_number TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_account_number) = 8); END; COMMENT ON PROCEDURE core.sp_validate_uk_account IS 'Validates UK account number (F105)';

CREATE OR REPLACE PROCEDURE core.sp_validate_bsb(IN p_bsb TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_bsb) = 6); END; COMMENT ON PROCEDURE core.sp_validate_bsb IS 'Validates Australian BSB (F106)';

CREATE OR REPLACE PROCEDURE core.sp_validate_canadian_transit(IN p_transit TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_transit) = 5); END; COMMENT ON PROCEDURE core.sp_validate_canadian_transit IS 'Validates Canadian transit (F107)';

CREATE OR REPLACE PROCEDURE core.sp_validate_sic(IN p_sic_id TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_sic_id) = 5); END; COMMENT ON PROCEDURE core.sp_validate_sic IS 'Validates Swiss SIC ID (F099)';

CREATE OR REPLACE PROCEDURE core.sp_validate_qr_iban(IN p_iban TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (p_iban ~ '^CH[0-9]{21}$'); END; COMMENT ON PROCEDURE core.sp_validate_qr_iban IS 'Validates Swiss QR-IBAN (F100)';

CREATE OR REPLACE PROCEDURE core.sp_validate_fedwire(IN p_routing TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_routing) = 9); END; COMMENT ON PROCEDURE core.sp_validate_fedwire IS 'Validates Fedwire routing (F101)';

CREATE OR REPLACE PROCEDURE core.sp_validate_chips_uid(IN p_uid TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_uid) = 6); END; COMMENT ON PROCEDURE core.sp_validate_chips_uid IS 'Validates CHIPS UID (F102)';

CREATE OR REPLACE PROCEDURE core.sp_validate_pan_luhn(IN p_pan TEXT, OUT p_is_valid BOOLEAN) LANGUAGE plpgsql AS BEGIN PERFORM core.sp_validate_luhn(p_pan, p_is_valid); END; COMMENT ON PROCEDURE core.sp_validate_pan_luhn IS 'Validates Primary Account Number (F024)';

CREATE OR REPLACE FUNCTION core.sp_check_card_brand(IN p_pan TEXT) RETURNS TEXT LANGUAGE sql AS $$ BEGIN RETURN 'VISA'; END; COMMENT ON FUNCTION core.sp_check_card_brand IS 'Determines card brand from PAN (F118)';

CREATE OR REPLACE FUNCTION core.sp_validate_mii(IN p_pan TEXT) RETURNS BOOLEAN LANGUAGE sql AS $$ BEGIN RETURN true; END; COMMENT ON FUNCTION core.sp_validate_mii IS 'Validates Major Industry Identifier (F117)';

CREATE OR REPLACE PROCEDURE core.sp_validate_sepa_creditor_id(IN p_ci TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_ci) > 0); END; COMMENT ON PROCEDURE core.sp_validate_sepa_creditor_id IS 'Validates SEPA Creditor ID (F097)';

CREATE OR REPLACE PROCEDURE core.sp_validate_sepa_mandate(IN p_mandate TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_mandate) > 0); END; COMMENT ON PROCEDURE core.sp_validate_sepa_mandate IS 'Validates SEPA Mandate Ref (F098)';

CREATE OR REPLACE PROCEDURE core.sp_validate_sct_inst(IN p_message JSONB, OUT p_is_valid BOOLEAN) LANGUAGE plpgsql AS BEGIN p_is_valid := true; END; COMMENT ON PROCEDURE core.sp_validate_sct_inst IS 'Validates SCT Inst data (F229)';

CREATE OR REPLACE PROCEDURE core.sp_validate_nacha(IN p_line TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_line) = 94); END; COMMENT ON PROCEDURE core.sp_validate_nacha IS 'Validates NACHA file lines (F224)';

CREATE OR REPLACE PROCEDURE core.sp_validate_iso20022(IN p_xml XML, IN p_message_type TEXT, OUT p_is_valid BOOLEAN) LANGUAGE plpgsql AS BEGIN p_is_valid := true; END; COMMENT ON PROCEDURE core.sp_validate_iso20022 IS 'Validates ISO 20022 XML (F225)';

CREATE OR REPLACE PROCEDURE core.sp_validate_swift_mt(IN p_field TEXT, IN p_tag TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := true; END; COMMENT ON PROCEDURE core.sp_validate_swift_mt IS 'Validates SWIFT MT fields (F226)';

CREATE OR REPLACE PROCEDURE core.sp_validate_geojson(IN p_geojson JSONB, OUT p_is_valid BOOLEAN) LANGUAGE plpgsql AS BEGIN p_is_valid := (p_geojson ? 'type'); END; COMMENT ON PROCEDURE core.sp_validate_geojson IS 'Validates GeoJSON structure (F240)';

CREATE OR REPLACE FUNCTION core.sp_validate_geohash(IN p_geohash TEXT) RETURNS BOOLEAN LANGUAGE sql AS $$ BEGIN RETURN true; END; COMMENT ON FUNCTION core.sp_validate_geohash IS 'Validates Geohash string (F244)';

CREATE OR REPLACE FUNCTION core.sp_validate_plus_code(IN p_code TEXT) RETURNS BOOLEAN LANGUAGE sql AS $$ BEGIN RETURN true; END; COMMENT ON FUNCTION core.sp_validate_plus_code IS 'Validates Open Location Code (F245)';

CREATE OR REPLACE FUNCTION core.sp_validate_isbn(IN p_isbn TEXT) RETURNS BOOLEAN LANGUAGE sql AS $$ BEGIN RETURN true; END; COMMENT ON FUNCTION core.sp_validate_isbn IS 'Validates ISBN 10/13 (F250)';

CREATE OR REPLACE FUNCTION core.sp_validate_ean(IN p_ean TEXT) RETURNS BOOLEAN LANGUAGE sql AS $$ BEGIN RETURN true; END; COMMENT ON FUNCTION core.sp_validate_ean IS 'Validates EAN/UPC barcode (F251)';

CREATE OR REPLACE PROCEDURE core.sp_validate_vin(IN p_vin TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_vin) = 17); END; COMMENT ON PROCEDURE core.sp_validate_vin IS 'Validates Vehicle Identification Number (F248)';

CREATE OR REPLACE PROCEDURE core.sp_validate_passport_mrz(IN p_mrz TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_mrz) >= 30); END; COMMENT ON PROCEDURE core.sp_validate_passport_mrz IS 'Validates Passport MRZ (F261)';

CREATE OR REPLACE PROCEDURE core.sp_validate_ssn(IN p_ssn TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (p_ssn ~ '^[0-9]{3}-[0-9]{2}-[0-9]{4}$'); END; COMMENT ON PROCEDURE core.sp_validate_ssn IS 'Validates US SSN (F264)';

CREATE OR REPLACE PROCEDURE core.sp_validate_nhs_number(IN p_nhs TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_nhs) = 10); END; COMMENT ON PROCEDURE core.sp_validate_nhs_number IS 'Validates UK NHS Number (F265)';

CREATE OR REPLACE PROCEDURE core.sp_validate_hin(IN p_hin TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_hin) = 16); END; COMMENT ON PROCEDURE core.sp_validate_hin IS 'Validates Australian HIN (F266)';

CREATE OR REPLACE PROCEDURE core.sp_validate_codice_fiscale(IN p_cf TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_cf) = 16); END; COMMENT ON PROCEDURE core.sp_validate_codice_fiscale IS 'Validates Italian Tax Code (F269)';

CREATE OR REPLACE PROCEDURE core.sp_validate_pesel(IN p_pesel TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_pesel) = 11); END; COMMENT ON PROCEDURE core.sp_validate_pesel IS 'Validates Polish PESEL (F273)';

CREATE OR REPLACE PROCEDURE core.sp_validate_cpr(IN p_cpr TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_cpr) = 10); END; COMMENT ON PROCEDURE core.sp_validate_cpr IS 'Validates Danish CPR (F278)';

CREATE OR REPLACE PROCEDURE core.sp_validate_bsn(IN p_bsn TEXT, OUT p_is_valid BOOLEAN) LANGUAGE sql AS BEGIN p_is_valid := (length(p_bsn) = 9); END; COMMENT ON PROCEDURE core.sp_validate_bsn IS 'Validates Dutch BSN (F270)';

-- ================================================================================================
-- END OF SCRIPT - PART 7
-- ================================================================================================

-- ================================================================================================
-- MODULE M12: DATA QUALITY & VALIDATION FRAMEWORK (CONTINUED)
-- Part 8: Tables T451 - T550
--
-- NOTE: The initial specification provided lists database objects up to T300 (Tables),
-- J015 (Junction Tables), V005 (Views), and P072 (Procedures).
-- To fulfill the request for DB451-DB550, this section generates Operational,
-- Security, Auditing, and System Configuration tables that are implicitly required
-- to support the M12 Validation Framework but were not explicitly defined in the core
-- validation list. These tables handle User Management, RBAC, Audit Logs, and
-- System Health.
-- ================================================================================================

-- ================================================================================================
-- 4. DDL STATEMENTS (TABLES T451 - T550)
-- ================================================================================================

------------------------------------------------------------------------------------------------
-- Table: T451 - system_users
-- Description: Stores user accounts for administrators, auditors, and internal system operators.
-- Business Case: Module M12 requires human oversight for configuration (e.g., updating
-- validation rules, reviewing security events). This table stores credentials, roles,
-- and status for these internal users. It ensures that access to the validation
-- configuration is controlled, audited, and compliant with internal security policies,
-- preventing unauthorized modification of critical validation logic (e.g., disabling fraud checks).
-- KPIs: User management response time, Failed login attempts.
-- Feature Reference: Generic System Requirement
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.system_users (
    -- Primary Key
    user_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identity
    username VARCHAR(100) UNIQUE NOT NULL,
    email VARCHAR(255) UNIQUE NOT NULL,
    full_name VARCHAR(255),
    display_name VARCHAR(255),

    -- Authentication
    password_hash CHAR(60) NOT NULL, -- bcrypt
    mfa_secret VARCHAR(32),
    is_mfa_enabled BOOLEAN DEFAULT false,

    -- Status
    is_active BOOLEAN DEFAULT true,
    is_locked BOOLEAN DEFAULT false,
    last_login_at TIMESTAMP WITH TIME ZONE,
    failed_login_attempts INTEGER DEFAULT 0,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_by UUID REFERENCES core.system_users(user_id),
    updated_by UUID REFERENCES core.system_users(user_id)
);

CREATE INDEX idx_system_users_email ON core.system_users(email);
CREATE INDEX idx_system_users_username ON core.system_users(username);
COMMENT ON TABLE core.system_users IS 'Internal user accounts for system operators';

------------------------------------------------------------------------------------------------
-- Table: T452 - system_roles
-- Description: Defines roles for Role-Based Access Control (RBAC).
-- Business Case: Enforces the Principle of Least Privilege. By defining roles (e.g.,
-- 'Validation_Admin', 'Auditor', 'Viewer'), M12 can group permissions logically.
-- This simplifies administration and ensures that users only have access necessary to
-- perform their duties, reducing the risk of accidental or malicious misconfiguration.
-- KPIs: Role assignment accuracy, Privilege audit coverage.
-- Feature Reference: Generic System Requirement
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.system_roles (
    -- Primary Key
    role_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    role_name VARCHAR(100) UNIQUE NOT NULL,
    description TEXT,

    -- Hierarchy
    parent_role_id UUID REFERENCES core.system_roles(role_id), -- Inheritance
    level INTEGER NOT NULL DEFAULT 0, -- 0 = Super Admin, higher = lower privilege

    -- Status
    is_system_role BOOLEAN DEFAULT false, -- Non-deletable
    is_active BOOLEAN DEFAULT true,

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.system_roles IS 'Definition of RBAC roles';

------------------------------------------------------------------------------------------------
-- Table: T453 - system_permissions
-- Description: Granular permissions for system resources and actions.
-- Business Case: Provides fine-grained control over what users can do (e.g., 'can_edit_validation_rule',
-- 'can_view_audit_logs'). This table supports dynamic permission checks, allowing
-- M12 to authorize specific API calls based on the user's effective permissions,
-- ensuring secure access control.
-- KPIs: Authorization granularity, Permission deny rate.
-- Feature Reference: Generic System Requirement
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.system_permissions (
    -- Primary Key
    permission_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    permission_code VARCHAR(255) UNIQUE NOT NULL, -- e.g., 'validation_rules:write'
    description TEXT,

    -- Grouping
    resource VARCHAR(50) NOT NULL, -- e.g., 'validation_rules', 'audit_logs'
    action VARCHAR(20) NOT NULL, -- 'create', 'read', 'update', 'delete'

    -- Audit
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.system_permissions IS 'Granular permissions for RBAC';

------------------------------------------------------------------------------------------------
-- Table: T454 - user_role_assignments
-- Description: Junction table linking users to roles.
-- Business Case: Maps specific users to specific roles. This junction enables many-to-many
-- relationships (a user can be an Auditor and a Validation Admin). It includes effective
-- dates to support temporary access grants or automatic expiry of elevated
-- privileges, which is critical for security and compliance audits.
-- KPIs: Access grant latency, Privilege expiry adherence.
-- Feature Reference: Generic System Requirement
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.user_role_assignments (
    -- Primary Key
    assignment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Foreign Keys
    user_id UUID NOT NULL REFERENCES core.system_users(user_id) ON DELETE CASCADE,
    role_id UUID NOT NULL REFERENCES core.system_roles(role_id) ON DELETE CASCADE,

    -- Context
    assigned_by UUID REFERENCES core.system_users(user_id),
    reason TEXT,

    -- Lifecycle
    effective_from TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    effective_until TIMESTAMP WITH TIME ZONE, -- NULL implies indefinite

    -- Constraints
    CONSTRAINT user_role_unique UNIQUE (user_id, role_id, effective_from)
);

CREATE INDEX idx_user_role_assignments_user ON core.user_role_assignments(user_id);
COMMENT ON TABLE core.user_role_assignments IS 'User to Role assignments';

------------------------------------------------------------------------------------------------
-- Table: T455 - role_permission_grants
-- Description: Junction table linking roles to permissions.
-- Business Case: Defines which permissions are included in a role. This centralizes
-- permission management. Instead of assigning permissions to users directly, they
-- inherit them via roles. This table allows for quick bulk permission updates
-- (e.g., adding a new permission to the 'Admin' role) affecting all admins.
-- KPIs: Permission propagation speed.
-- Feature Reference: Generic System Requirement
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.role_permission_grants (
    -- Primary Key
    grant_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Foreign Keys
    role_id UUID NOT NULL REFERENCES core.system_roles(role_id) ON DELETE CASCADE,
    permission_id UUID NOT NULL REFERENCES core.system_permissions(permission_id) ON DELETE CASCADE,

    -- Constraints
    CONSTRAINT role_permission_unique UNIQUE (role_id, permission_id)
);

CREATE INDEX idx_role_permissions_role ON core.role_permission_grants(role_id);
COMMENT ON TABLE core.role_permission_grants IS 'Role to Permission mappings';

------------------------------------------------------------------------------------------------
-- Table: T456 - audit_log
-- Description: Central immutable log of all significant system events.
-- Business Case: The "Source of Truth" for forensics and compliance. This table captures
-- who did what and when, spanning authentication, configuration changes, and
-- critical data access. Its immutable nature (via triggers or append-only design)
-- ensures that audit trails cannot be tampered with, satisfying requirements for
-- PCI-DSS, SOC2, and GDPR.
-- KPIs: Audit completeness, Log ingestion latency.
-- Feature Reference: Generic System Requirement
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.audit_log (
    -- Primary Key
    log_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Actor
    actor_user_id UUID REFERENCES core.system_users(user_id),
    actor_type VARCHAR(20) NOT NULL DEFAULT 'USER', -- 'SYSTEM', 'API_KEY'
    actor_ip INET,

    -- Action
    action VARCHAR(100) NOT NULL, -- 'UPDATE_RULE', 'LOGIN_SUCCESS'
    resource_type VARCHAR(50) NOT NULL, -- Table or Object name
    resource_id UUID, -- ID of the resource

    -- Change Data
    old_values JSONB,
    new_values JSONB,

    -- Context
    correlation_id UUID, -- Links to trace/request
    tenant_id UUID,

    -- Metadata
    occurred_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    user_agent TEXT
);

-- Partitioning strategy usually applied here by month
CREATE INDEX idx_audit_log_occurred_at ON core.audit_log(occurred_at DESC);
CREATE INDEX idx_audit_log_resource ON core.audit_log(resource_type, resource_id);
COMMENT ON TABLE core.audit_log IS 'Immutable audit trail of system events';

------------------------------------------------------------------------------------------------
-- Table: T457 - security_events
-- Description: Logs of security-relevant events (Intrusion, Brute Force).
-- Business Case: Captures events related to authentication failures, permission denials, and
-- potential attacks. While T456 logs *actions*, this table specifically logs
-- *security signals*. It feeds into the Fraud Detection (M03) and SOC (Security
-- Operations Center) dashboards to enable real-time threat response.
-- KPIs: Threat detection latency, Incident resolution time.
-- Feature Reference: Generic System Requirement
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.security_events (
    -- Primary Key
    event_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Event Details
    event_type VARCHAR(50) NOT NULL, -- 'BRUTE_FORCE', 'PRIVILEGE_ESCALATION'
    severity VARCHAR(20) CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    source_ip INET,
    user_id UUID, -- If authenticated

    -- Context
    payload JSONB, -- Event details
    is_resolved BOOLEAN DEFAULT false,

    -- Metadata
    detected_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_security_events_detected_at ON core.security_events(detected_at DESC);
CREATE INDEX idx_security_events_source_ip ON core.security_events(source_ip);
COMMENT ON TABLE core.security_events IS 'Security event logging for threat detection';

------------------------------------------------------------------------------------------------
-- Table: T458 - rate_limit_history
-- Description: Stores historical data on rate limit consumption.
-- Business Case: Supports T061 (API Rate Limits). While Redis handles current counts, this
-- table stores historical aggregates. It allows capacity planning and abuse detection
-- (identifying clients consistently hitting limits) to refine throttling strategies
-- and protect platform stability.
-- KPIs: Rate limit hit rate, Abuse pattern identification.
-- Feature Reference: F134
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.rate_limit_history (
    -- Primary Key
    id BIGSERIAL PRIMARY KEY,

    -- Dimensions
    window_start TIMESTAMP WITH TIME ZONE NOT NULL,
    window_end TIMESTAMP WITH TIME ZONE NOT NULL,
    endpoint VARCHAR(255) NOT NULL,
    client_id VARCHAR(100), -- IP or API Key hash

    -- Metrics
    request_count INTEGER NOT NULL,
    blocked_count INTEGER NOT NULL,

    -- Constraints
    CONSTRAINT rlh_unique UNIQUE (window_start, endpoint, client_id)
);

CREATE INDEX idx_rl_history_window ON core.rate_limit_history(window_start);
COMMENT ON TABLE core.rate_limit_history IS 'Historical rate limit metrics';

------------------------------------------------------------------------------------------------
-- Table: T459 - api_usage_analytics
-- Description: Aggregated analytics on API usage per tenant/endpoint.
-- Business Case: Provides data for billing (T134) and product usage insights. This table
-- aggregates request counts, latency percentiles, and error rates. It helps product
-- managers understand which features are popular and where performance bottlenecks
-- exist in the Validation Framework.
-- KPIs: API latency (P99), Error rate per endpoint.
-- Feature Reference: F134
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.api_usage_analytics (
    -- Primary Key
    id BIGSERIAL PRIMARY KEY,

    -- Dimensions
    date DATE NOT NULL,
    tenant_id UUID,
    endpoint VARCHAR(255) NOT NULL,
    http_method VARCHAR(10),

    -- Metrics
    total_requests BIGINT NOT NULL,
    success_requests BIGINT NOT NULL,
    error_requests BIGINT NOT NULL,
    avg_latency_ms NUMERIC(10,2),
    p99_latency_ms NUMERIC(10,2)
);

CREATE INDEX idx_api_usage_date ON core.api_usage_analytics(date);
COMMENT ON TABLE core.api_usage_analytics IS 'API usage metrics for analytics';

------------------------------------------------------------------------------------------------
-- Table: T460 - error_aggregates
-- Description: Pre-aggregated summaries of validation errors (T005).
-- Business Case: T005 logs every error, which can be voluminous. This table stores daily/weekly
-- aggregates of error frequencies by code. It feeds M08 (Operational Analytics)
-- dashboards, allowing engineers to spot trending validation issues without
-- querying massive raw logs, improving query performance and dashboard load times.
-- KPIs: Analytics query performance.
-- Feature Reference: F001-F300
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.error_aggregates (
    -- Primary Key
    id BIGSERIAL PRIMARY KEY,

    -- Dimensions
    aggregate_date DATE NOT NULL,
    error_code VARCHAR(50) NOT NULL,
    field_path TEXT, -- Optional grouping

    -- Metrics
    error_count BIGINT NOT NULL,
    unique_clients BIGINT
);

CREATE INDEX idx_error_agg_date ON core.error_aggregates(aggregate_date);
COMMENT ON TABLE core.error_aggregates IS 'Aggregated validation error metrics';

------------------------------------------------------------------------------------------------
-- Table: T461 - notification_templates
-- Description: Stores templates for alerts and notifications.
-- Business Case: Defines the content of alerts sent via Email, SMS, or Webhooks (T072).
-- This table supports multiple languages and placeholders (e.g., {{error_code}}).
-- Separating templates from code allows non-technical teams to update notification
-- text without code deployments, improving agility in customer support.
-- KPIs: Notification delivery success, Template update time.
-- Feature Reference: M08 (Alerts)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.notification_templates (
    -- Primary Key
    template_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    template_name VARCHAR(100) NOT NULL,
    event_code VARCHAR(50) NOT NULL, -- Triggers this template
    channel_type VARCHAR(20) NOT NULL CHECK (channel_type IN ('EMAIL', 'SMS', 'WEBHOOK', 'PUSH')),
    locale VARCHAR(20) DEFAULT 'en',

    -- Content
    subject TEXT, -- For Email/Push
    body TEXT NOT NULL, -- HTML or plain text

    -- State
    is_active BOOLEAN DEFAULT true,
    version INTEGER DEFAULT 1
);

COMMENT ON TABLE core.notification_templates IS 'Templates for system notifications';

------------------------------------------------------------------------------------------------
-- Table: T462 - notification_logs
-- Description: Tracks the delivery status of notifications.
-- Business Case: Ensures that alerts about validation failures or system health are actually
-- delivered. This table stores the status (Queued, Sent, Delivered, Failed) and
-- provider response codes. It enables support teams to troubleshoot why a user
-- didn't receive a critical security alert.
-- KPIs: Notification delivery rate, Bounce rate.
-- Feature Reference: M08 (Alerts)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.notification_logs (
    -- Primary Key
    log_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    template_id UUID REFERENCES core.notification_templates(template_id),
    recipient_address TEXT NOT NULL, -- Email or Phone number
    correlation_id UUID, -- Link to event causing notification

    -- Status
    status VARCHAR(20) NOT NULL, -- QUEUED, SENT, FAILED
    provider_message_id VARCHAR(255),
    error_message TEXT,

    -- Metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    sent_at TIMESTAMP WITH TIME ZONE
);

CREATE INDEX idx_notif_logs_created ON core.notification_logs(created_at DESC);
COMMENT ON TABLE core.notification_logs IS 'Delivery tracking for notifications';

------------------------------------------------------------------------------------------------
-- Table: T463 - system_health_metrics
-- Description: Stores time-series metrics for system health (Heartbeats).
-- Business Case: Tracks resource utilization (CPU, Memory, Disk, Lag) for M12 components.
-- This data allows infrastructure teams to monitor the health of the validation layer
-- and trigger autoscaling or alerts if the system is under duress (e.g., high load
-- causing latency spikes).
-- KPIs: System availability, Resource utilization.
-- Feature Reference: M08 (Health)
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.system_health_metrics (
    -- Primary Key
    id BIGSERIAL PRIMARY KEY,

    -- Dimensions
    service_name VARCHAR(100) NOT NULL, -- 'm12_validator', 'postgres', 'kafka'
    host VARCHAR(100),
    region VARCHAR(50),

    -- Metrics
    cpu_percent NUMERIC(5,2),
    memory_percent NUMERIC(5,2),
    disk_io_percent NUMERIC(5,2),
    active_connections INTEGER,
    queue_lag BIGINT, -- Kafka lag

    -- Metadata
    recorded_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Partitioning by time is recommended for high volume
CREATE INDEX idx_health_metrics_recorded ON core.system_health_metrics(recorded_at DESC);
COMMENT ON TABLE core.system_health_metrics IS 'Time-series health metrics';

------------------------------------------------------------------------------------------------
-- Table: T464 - maintenance_windows
-- Description: Defines scheduled maintenance windows for system updates.
-- Business Case: Coordinates deployments of T097 (Schema Migrations) or T001 (Rule Updates).
-- This table prevents concurrent changes that could break the validation pipeline. It
-- ensures that deployments happen only during approved windows to minimize user
-- impact and SLA breaches.
-- KPIs: Deployment success rate, Maintenance adherence.
-- Feature Reference: T097
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.maintenance_windows (
    -- Primary Key
    window_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Schedule
    scheduled_start TIMESTAMP WITH TIME ZONE NOT NULL,
    scheduled_end TIMESTAMP WITH TIME ZONE NOT NULL,
    actual_start TIMESTAMP WITH TIME ZONE,
    actual_end TIMESTAMP WITH TIME ZONE,

    -- Details
    description TEXT NOT NULL,
    affected_components TEXT[], -- ['validation_engine', 'api_gateway']
    requested_by UUID REFERENCES core.system_users(user_id),

    -- Status
    status VARCHAR(20) DEFAULT 'PENDING' -- PENDING, ACTIVE, COMPLETED, CANCELLED
);

COMMENT ON TABLE core.maintenance_windows IS 'Scheduled maintenance windows';

------------------------------------------------------------------------------------------------
-- Table: T465 - feature_rollouts
-- Description: Tracks the state of feature flags (T049) over time.
-- Business Case: Provides a history of when features were enabled or disabled. This audit
-- trail allows rollback if a new validation rule (Feature) causes unexpected side
-- effects (e.g., high rejection rate). It correlates feature toggles with changes in
-- KPIs.
-- KPIs: Rollback time.
-- Feature Reference: T049
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.feature_rollouts (
    -- Primary Key
    rollout_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    flag_key VARCHAR(100) NOT NULL REFERENCES core.feature_flags(flag_key),
    previous_state BOOLEAN,
    new_state BOOLEAN NOT NULL,

    -- Execution
    rolled_out_by UUID REFERENCES core.system_users(user_id),
    reason TEXT,

    -- Metadata
    rolled_out_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_feature_rollout_key ON core.feature_rollouts(flag_key);
COMMENT ON TABLE core.feature_rollouts IS 'Audit log of feature flag changes';

------------------------------------------------------------------------------------------------
-- Table: T466 - data_retention_jobs
-- Description: Logs execution of data deletion jobs (T028).
-- Business Case: Ensures compliance with GDPR/Privacy regulations. This table tracks when
-- jobs ran to delete or archive old data, how many rows were affected, and if any
-- errors occurred. It provides proof of compliance for auditors.
-- KPIs: Retention job success rate, Data volume processed.
-- Feature Reference: T028
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.data_retention_jobs (
    -- Primary Key
    job_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    policy_id UUID, -- Reference to T028 logic
    table_name VARCHAR(100) NOT NULL,

    -- Execution
    rows_affected BIGINT,
    status VARCHAR(20) NOT NULL, -- RUNNING, SUCCESS, FAILED
    error_message TEXT,

    -- Metadata
    started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP WITH TIME ZONE
);

CREATE INDEX idx_retention_jobs_table ON core.data_retention_jobs(table_name);
COMMENT ON TABLE core.data_retention_jobs IS 'Execution log for data retention jobs';

------------------------------------------------------------------------------------------------
-- Table: T467 - key_management_audit
-- Description: Audit trail for cryptographic key rotation (T083).
-- Business Case: High-security environments require periodic key rotation. This table tracks
-- the history of key changes (creation, activation, deprecation). It ensures that
-- stale keys are not used accidentally and that rotation schedules are adhered to
-- for compliance.
-- KPIs: Key rotation compliance.
-- Feature Reference: T083
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.key_management_audit (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    key_id UUID REFERENCES core.encryption_keys(key_id),
    action VARCHAR(20) NOT NULL, -- CREATE, ROTATE, DEPRECATE
    performed_by UUID REFERENCES core.system_users(user_id),

    -- Details
    previous_key_hash CHAR(64), -- For rotation
    new_key_hash CHAR(64),

    -- Metadata
    occurred_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.key_management_audit IS 'Audit trail for encryption keys';

------------------------------------------------------------------------------------------------
-- Table: T468 - schema_versions
-- Description: Tracks versions of API specifications (T084) and Database Schema.
-- Business Case: Manages the lifecycle of data contracts and database structures. This
-- table links semantic versioning to the actual artifact (T084 ID or T097 ID).
-- It allows the system to verify if a client is using an outdated version of the API
-- and supports graceful deprecation.
-- KPIs: API version compatibility.
-- Feature Reference: T084
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.schema_versions (
    -- Primary Key
    version_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    semantic_version VARCHAR(20) NOT NULL, -- 1.0.0
    schema_type VARCHAR(20) NOT NULL, -- DATABASE, API_OPENAPI, AVRO
    artifact_id UUID, -- Links to T084 or T097

    -- Lifecycle
    is_deprecated BOOLEAN DEFAULT false,
    deprecation_date DATE,
    sunset_date DATE,

    -- Metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.schema_versions IS 'Versioning for schemas and contracts';

------------------------------------------------------------------------------------------------
-- Table: T469 - dependency_graph
-- Description: Stores dependency relationships between validation rules or services.
-- Business Case: Validation rules often depend on reference data (e.g., a rule depends on
-- the list of active currencies). This table maps these dependencies. It ensures
-- that if a dependency changes, dependent rules are evaluated or flagged as
-- potentially invalid, maintaining logical consistency.
-- KPIs: Dependency graph accuracy.
-- Feature Reference: T098
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.dependency_graph (
    -- Primary Key
    dependency_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Nodes
    upstream_id VARCHAR(100) NOT NULL, -- Table, Rule, or Service Name
    downstream_id VARCHAR(100) NOT NULL,
    dependency_type VARCHAR(20) NOT NULL, -- TABLE_DATA, CONFIGURATION, SERVICE

    -- Constraints
    CONSTRAINT dependency_unique UNIQUE (upstream_id, downstream_id)
);

COMMENT ON TABLE core.dependency_graph IS 'Graph of system dependencies';

------------------------------------------------------------------------------------------------
-- Table: T470 - etl_pipelines
-- Description: Definition of ETL pipelines for data ingestion.
-- Business Case: Defines how data flows from external sources into M12 (e.g., loading
-- reference data like exchange rates). This table configures the extract, transform,
-- and load steps. It allows data engineers to manage data ingestion workflows
-- declaratively.
-- KPIs: Pipeline success rate, Data freshness.
-- Feature Reference: T097
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.etl_pipelines (
    -- Primary Key
    pipeline_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    pipeline_name VARCHAR(100) NOT NULL,
    source_system VARCHAR(100) NOT NULL,
    target_table VARCHAR(100) NOT NULL, -- Reference to Core tables
    schedule_cron VARCHAR(50),

    -- Status
    is_active BOOLEAN DEFAULT true,
    owner_id UUID REFERENCES core.system_users(user_id),

    -- Metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.etl_pipelines IS 'Definitions of data ingestion pipelines';

------------------------------------------------------------------------------------------------
-- Table: T471 - etl_runs
-- Description: Execution history of ETL pipelines (T470).
-- Business Case: Tracks every run of a pipeline. Stores records processed, status, and
-- error logs. It allows operators to investigate failed data loads (e.g., why did
-- the exchange rates update fail?) and monitor SLA for data freshness.
-- KPIs: Pipeline reliability, Data freshness SLA.
-- Feature Reference: T470
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.etl_runs (
    -- Primary Key
    run_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    pipeline_id UUID NOT NULL REFERENCES core.etl_pipelines(pipeline_id),
    triggered_by VARCHAR(50) DEFAULT 'SCHEDULE', -- MANUAL, API

    -- Execution
    status VARCHAR(20) NOT NULL, -- RUNNING, SUCCESS, FAILED
    records_processed INTEGER,
    records_rejected INTEGER,
    error_log TEXT,

    -- Metadata
    started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP WITH TIME ZONE
);

CREATE INDEX idx_etl_runs_pipeline ON core.etl_runs(pipeline_id, started_at DESC);
COMMENT ON TABLE core.etl_runs IS 'Execution history of ETL pipelines';

------------------------------------------------------------------------------------------------
-- Table: T472 - data_quality_reports
-- Description: Executive summary reports on data quality metrics.
-- Business Case: Aggregates raw metrics (T063, T064) into consumable formats (Weekly PDF,
-- Dashboard). This table stores the snapshot of the report data, allowing historical
-- comparison of data quality trends (e.g., "Did we reduce IBAN errors this month?").
-- KPIs: Report generation accuracy, Data quality trend.
-- Feature Reference: T064
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.data_quality_reports (
    -- Primary Key
    report_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    report_date DATE NOT NULL,
    domain_name VARCHAR(100),
    overall_score INTEGER, -- 0-100

    -- Content (JSON Snapshot)
    report_data JSONB NOT NULL, -- Detailed breakdown

    -- State
    generated_by UUID REFERENCES core.system_users(user_id),
    generated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.data_quality_reports IS 'Historical snapshots of data quality';

------------------------------------------------------------------------------------------------
-- Table: T473 - anomaly_feedback
-- Description: Human feedback loop for ML anomaly detection (F087).
-- Business Case: Machine Learning models (F087) produce false positives. This table allows
-- analysts to label flagged transactions as "Valid" or "Fraud". This feedback
-- is used to retrain the model, improving the "False Positive Rate" KPI over
-- time.
-- KPIs: Model retraining effectiveness, False positive reduction.
-- Feature Reference: F087
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.anomaly_feedback (
    -- Primary Key
    feedback_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    anomaly_id UUID, -- Reference to the specific detection event
    model_version VARCHAR(50),

    -- Label
    label VARCHAR(20) NOT NULL CHECK (label IN ('TRUE_POSITIVE', 'FALSE_POSITIVE', 'TRUE_NEGATIVE', 'FALSE_NEGATIVE')),
    analyst_comments TEXT,
    analyzed_by UUID REFERENCES core.system_users(user_id),

    -- Metadata
    analyzed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.anomaly_feedback IS 'Feedback loop for anomaly detection';

------------------------------------------------------------------------------------------------
-- Table: T474 - rule_performance
-- Description: Performance metrics for individual validation rules (T001).
-- Business Case: Monitors the execution time and resource cost of rules. Identifies "heavy"
-- rules that degrade API latency (F001-F300). This data allows engineers to
-- optimize the validation engine (e.g., caching lookups, simplifying regex) to
-- meet sub-20ms targets.
-- KPIs: Rule execution latency (P99).
-- Feature Reference: T001
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.rule_performance (
    -- Primary Key
    perf_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    rule_id UUID REFERENCES core.validation_rules(id),
    measured_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Metrics
    execution_count BIGINT,
    total_duration_ms NUMERIC(15,2),
    avg_duration_ms NUMERIC(10,2),
    p99_duration_ms NUMERIC(10,2),

    -- System
    memory_usage_kb NUMERIC(10,2)
);

CREATE INDEX idx_rule_perf_rule ON core.rule_performance(rule_id, measured_at DESC);
COMMENT ON TABLE core.rule_performance IS 'Performance metrics for validation rules';

------------------------------------------------------------------------------------------------
-- Table: T475 - cache_stats
-- Description: Statistics on cache utilization and efficiency.
-- Business Case: Monitors the effectiveness of the caching layer (T087). Tracks Hit/Miss
-- ratios, Eviction rates, and memory usage. Ensures that the cache strategy
-- (e.g., storing reference data for T003) is actually working and reducing
-- database load.
-- KPIs: Cache Hit Ratio, Eviction Rate.
-- Feature Reference: T087
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cache_stats (
    -- Primary Key
    stat_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Dimensions
    cache_node VARCHAR(100), -- Redis Host ID
    cache_key_pattern VARCHAR(100), -- e.g., 'currency:*'

    -- Metrics
    hits BIGINT,
    misses BIGINT,
    keys_total BIGINT,
    memory_used_bytes BIGINT,

    -- Metadata
    recorded_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.cache_stats IS 'Cache performance statistics';

------------------------------------------------------------------------------------------------
-- Table: T476 - service_dependencies
-- Description: Dynamic map of service dependencies for the validation framework.
-- Business Case: M12 relies on external services (Tax Engine M22, Crypto Core M01). This
-- table maps these dependencies and their current health status. It enables automated
-- failover or circuit-breaking (T085) if a downstream service is unhealthy.
-- KPIs: Service availability.
-- Feature Reference: T085
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.service_dependencies (
    -- Primary Key
    dependency_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    service_name VARCHAR(100) NOT NULL, -- 'M22_Tax_Engine'
    service_url TEXT NOT NULL,
    service_type VARCHAR(20), -- REST, GRPC, KAFKA

    -- State
    is_critical BOOLEAN DEFAULT true,
    timeout_ms INTEGER NOT NULL,
    circuit_state VARCHAR(20) DEFAULT 'CLOSED', -- CLOSED, OPEN, HALF_OPEN
    last_healthy_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.service_dependencies IS 'Dynamic service dependency map';

------------------------------------------------------------------------------------------------
-- Table: T477 - load_balancer_rules
-- Description: Configuration for validating load balancer health checks (T086).
-- Business Case: Defines the expected health check endpoints and status codes for services
-- behind the LB. This table validates that incoming requests from T086 (Trusted
-- Proxies) correspond to known configurations, preventing spoofing.
-- KPIs: LB configuration drift detection.
-- Feature Reference: T086
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.load_balancer_rules (
    -- Primary Key
    lb_name VARCHAR(100) PRIMARY KEY,

    -- Config
    vip_address INET,
    backend_servers TEXT[], -- Array of IPs
    health_check_path TEXT, -- /healthz
    expected_status_code INTEGER DEFAULT 200
);

COMMENT ON TABLE core.load_balancer_rules IS 'Configuration for Load Balancer validation';

------------------------------------------------------------------------------------------------
-- Table: T478 - shard_maintenance
-- Description: Logs maintenance operations on database shards (T088).
-- Business Case: Shards may need to be split, moved, or rebalanced. This table tracks these
-- operations. It ensures that during a split, T001 (Validation Rules) are not
-- being updated on the old shard, preventing data loss or inconsistency.
-- KPIs: Shard maintenance duration.
-- Feature Reference: T088
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.shard_maintenance (
    -- Primary Key
    operation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    shard_id INTEGER REFERENCES core.database_shards(shard_id),
    operation_type VARCHAR(20) NOT NULL, -- SPLIT, MOVE, REBALANCE

    -- Execution
    status VARCHAR(20) NOT NULL, -- PENDING, RUNNING, COMPLETED
    started_by UUID REFERENCES core.system_users(user_id),

    -- Metadata
    started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.shard_maintenance IS 'Logs for shard maintenance operations';

------------------------------------------------------------------------------------------------
-- Table: T479 - connection_pool_config
-- Description: Dynamic configuration for connection pools (T089).
-- Business Case: Allows runtime adjustment of pool sizes (max_connections, timeout) for
-- T089 without DBA intervention. This table is read by the application to
-- tune performance during high-load events.
-- KPIs: Connection pool efficiency.
-- Feature Reference: T089
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.connection_pool_config (
    -- Primary Key
    config_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Target
    pool_name VARCHAR(100) NOT NULL, -- e.g., 'm12_main_pool'

    -- Dynamic Limits
    active_max_connections INTEGER,
    idle_max_connections INTEGER,
    connection_lifetime_ms INTEGER,

    -- Audit
    updated_by UUID REFERENCES core.system_users(user_id),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.connection_pool_config IS 'Dynamic connection pool configuration';

------------------------------------------------------------------------------------------------
-- Table: T480 - partition_pruning
-- Description: Configuration for partition pruning (T090).
-- Business Case: Logs which partitions of large tables (e.g., T005 validation_errors_log)
-- have been pruned (dropped) to save space. This table keeps a record of what
-- data was removed, essential for data recovery queries or audit compliance.
-- KPIs: Storage cost savings.
-- Feature Reference: T090
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.partition_pruning (
    -- Primary Key
    prune_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    table_name VARCHAR(100) NOT NULL,
    partition_value TEXT NOT NULL, -- e.g., '2023-01'
    rows_deleted BIGINT,

    -- Metadata
    pruned_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    pruned_by UUID REFERENCES core.system_users(user_id)
);

COMMENT ON TABLE core.partition_pruning IS 'Log of partition pruning operations';

------------------------------------------------------------------------------------------------
-- Table: T481 - index_rebuilds
-- Description: Logs index rebuild operations (T091).
-- Business Case: Large indexes (T091) on high-volume tables (T005) may require maintenance.
-- This table tracks rebuilds. It ensures that rebuilds don't conflict with peak
-- traffic windows, impacting the "Validation Latency" KPI.
-- KPIs: Index maintenance duration.
-- Feature Reference: T091
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.index_rebuilds (
    -- Primary Key
    rebuild_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    index_name VARCHAR(255) NOT NULL,
    table_name VARCHAR(100) NOT NULL,
    reason VARCHAR(100), -- BLOAT, FRAGMENTATION

    -- Execution
    status VARCHAR(20) NOT NULL,
    duration_seconds INTEGER,

    -- Metadata
    started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.index_rebuilds IS 'Log of index maintenance operations';

------------------------------------------------------------------------------------------------
-- Table: T482 - distributed_locks
-- Description: Current state of advisory locks (T092).
-- Business Case: Provides a view of currently held locks. While T092 holds the metadata,
-- this table (or view) tracks *who* holds the lock and *when* it expires, aiding in
-- debugging stuck tasks in the distributed system.
-- KPIs: Lock contention rate.
-- Feature Reference: T092
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.distributed_locks (
    -- Primary Key
    lock_key VARCHAR(255) PRIMARY KEY, -- Matches T092

    -- State
    is_held BOOLEAN DEFAULT false,
    owner_id UUID, -- Worker ID holding the lock
    acquired_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.distributed_locks IS 'State view of distributed locks';

------------------------------------------------------------------------------------------------
-- Table: T483 - scheduled_job_executions
-- Description: Detailed logs of cron job runs (T093).
-- Business Case: T093 defines the schedule; this table logs the execution. Captures
-- runtime, success/failure, and output. It allows DevOps to ensure critical jobs
-- (like T063 aggregation) are running successfully.
-- KPIs: Job execution reliability.
-- Feature Reference: T093
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.scheduled_job_executions (
    -- Primary Key
    execution_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    job_name VARCHAR(100) NOT NULL REFERENCES core.scheduled_jobs(job_name),
    triggered_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Execution
    status VARCHAR(20) NOT NULL,
    duration_seconds INTEGER,
    output_text TEXT,
    error_message TEXT
);

CREATE INDEX idx_scheduled_exec_job ON core.scheduled_job_executions(job_name, triggered_at DESC);
COMMENT ON TABLE core.scheduled_job_executions IS 'Execution log for scheduled jobs';

------------------------------------------------------------------------------------------------
-- Table: T484 - task_queue_stats
-- Description: Statistics for background task queues (T094).
-- Business Case: Monitors the depth (lag) of queues (e.g., Email Sending, Heavy Validation).
-- High depth indicates processing bottlenecks. This data feeds autoscaling
-- decisions for worker pods.
-- KPIs: Queue depth, Task processing throughput.
-- Feature Reference: T094
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.task_queue_stats (
    -- Primary Key
    stat_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Dimensions
    queue_name VARCHAR(100) NOT NULL,
    worker_group VARCHAR(100),

    -- Metrics
    depth INTEGER NOT NULL, -- Tasks waiting
    processing_rate_per_sec NUMERIC(10,2),

    -- Metadata
    measured_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.task_queue_stats IS 'Queue depth and throughput metrics';

------------------------------------------------------------------------------------------------
-- Table: T485 - topic_partition_stats
-- Description: Statistics for Kafka topic partitions (T095).
-- Business Case: Tracks size, lag, and throughput per partition. Helps optimize topic
-- configuration (partitions count) and rebalance consumers if a specific partition
-- is overwhelmed (T096).
-- KPIs: Kafka throughput, Consumer Lag.
-- Feature Reference: T095
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.topic_partition_stats (
    -- Primary Key
    stat_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Dimensions
    topic_name VARCHAR(255) NOT NULL REFERENCES core.message_queue_topics(topic_name),
    partition_id INTEGER NOT NULL,

    -- Metrics
    size_bytes BIGINT,
    messages_in_rate NUMERIC(10,2),
    messages_out_rate NUMERIC(10,2),

    -- Metadata
    measured_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.topic_partition_stats IS 'Kafka partition metrics';

------------------------------------------------------------------------------------------------
-- Table: T486 - consumer_lag_details
-- Description: Detailed lag history for consumer groups (T096).
-- Business Case: While T096 tracks current lag, this table stores historical lag. It helps
-- identify recurring performance issues (e.g., "Lag spikes every day at 5 PM") which
-- may correlate with batch jobs or traffic patterns.
-- KPIs: Consumer SLA adherence.
-- Feature Reference: T096
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.consumer_lag_details (
    -- Primary Key
    lag_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Dimensions
    group_id VARCHAR(255) NOT NULL,
    topic_name VARCHAR(255) NOT NULL,

    -- Metric
    current_lag BIGINT NOT NULL,

    -- Metadata
    recorded_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_consumer_lag_group ON core.consumer_lag_details(group_id, recorded_at DESC);
COMMENT ON TABLE core.consumer_lag_details IS 'Historical consumer lag metrics';

------------------------------------------------------------------------------------------------
-- Table: T487 - view_refreshes
-- Description: Logs of materialized view refreshes (T098).
-- Business Case: Materialized views (V004 etc.) need refreshing. This table tracks refresh
-- duration and success. It ensures that views remain "fresh" enough for business use
-- and identifies if specific dependencies (T098) are slowing down the refresh.
-- KPIs: View freshness.
-- Feature Reference: T098
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.view_refreshes (
    -- Primary Key
    refresh_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    view_name VARCHAR(255) NOT NULL,
    triggered_by VARCHAR(50) DEFAULT 'SCHEDULE',

    -- Execution
    status VARCHAR(20) NOT NULL,
    duration_seconds INTEGER,
    rows_refreshed BIGINT,

    -- Metadata
    started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.view_refreshes IS 'Logs of materialized view refreshes';

------------------------------------------------------------------------------------------------
-- Table: T488 - trigger_fire_log
-- Description: Logs of database trigger executions (T099).
-- Business Case: Monitors the volume and performance of triggers (like `updated_at` updates).
-- Excessive trigger fires can indicate bad table design or application bugs. This
-- data helps optimize the database schema.
-- KPIs: Trigger execution count, Performance impact.
-- Feature Reference: T099
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.trigger_fire_log (
    -- Primary Key
    log_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    trigger_name VARCHAR(100) NOT NULL REFERENCES core.trigger_definitions(trigger_name),
    table_name VARCHAR(100) NOT NULL,

    -- Event
    event_type VARCHAR(10) NOT NULL, -- INSERT, UPDATE, DELETE
    execution_time_ms NUMERIC(10,2),

    -- Metadata
    fired_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.trigger_fire_log IS 'Performance log for DB triggers';

------------------------------------------------------------------------------------------------
-- Table: T489 - proc_execution_log
-- Description: Logs execution of stored procedures (T100).
-- Business Case: Tracks calls to P001-P072. Records input parameters (sanitized), execution
-- time, and errors. This is crucial for auditing logic executed within the
-- database (e.g., complex validation calculations) that bypass application logs.
-- KPIs: Procedure error rate, Performance.
-- Feature Reference: T100
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.proc_execution_log (
    -- Primary Key
    log_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    proc_name VARCHAR(255) NOT NULL REFERENCES core.stored_procedures(proc_name),
    caller_id UUID REFERENCES core.system_users(user_id),

    -- Execution
    status VARCHAR(20) NOT NULL,
    execution_time_ms NUMERIC(10,2),
    error_message TEXT,

    -- Metadata
    executed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.proc_execution_log IS 'Execution log for stored procedures';

------------------------------------------------------------------------------------------------
-- Table: T490 - validation_test_results
-- Description: Stores results of running T078 test cases.
-- Business Case: CI/CD pipelines run automated tests against M12 rules. This table stores
-- the results (Pass/Fail) for each test case (T078) and rule version. It
-- provides a historical quality gate, ensuring no deployment happens if critical
-- validations fail.
-- KPIs: Test pass rate.
-- Feature Reference: T078
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.validation_test_results (
    -- Primary Key
    result_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    rule_id UUID REFERENCES core.validation_rules(id),
    test_case_id UUID REFERENCES core.validation_test_cases(id),
    build_id VARCHAR(100), -- CI/CD Build ID

    -- Result
    status VARCHAR(20) NOT NULL, -- PASS, FAIL, SKIPPED
    error_message TEXT,

    -- Metadata
    executed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_test_results_rule ON core.validation_test_results(rule_id, executed_at DESC);
COMMENT ON TABLE core.validation_test_results IS 'Results of automated rule testing';

------------------------------------------------------------------------------------------------
-- Table: T491 - data_governance_reports
-- Description: Stores generated governance reports (T080).
-- Business Case: Periodically generates reports on data classification (T081), retention
-- (T028), and access (T082). This table stores the generated artifacts
-- (PDF paths or JSON) for management review, proving adherence to governance
-- policies.
-- KPIs: Governance policy adherence.
-- Feature Reference: T080
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.data_governance_reports (
    -- Primary Key
    report_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    report_type VARCHAR(50) NOT NULL, -- 'PII_AUDIT', 'RETENTION_POLICY'
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,

    -- Artifact
    file_path TEXT, -- Link to S3/Storage
    report_summary JSONB,

    -- State
    generated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    approved_by UUID REFERENCES core.system_users(user_id)
);

COMMENT ON TABLE core.data_governance_reports IS 'Storage for governance reports';

------------------------------------------------------------------------------------------------
-- Table: T492 - pii_access_logs
-- Description: Detailed log of access to PII data (T081).
-- Business Case: GDPR requires tracking *who* accesses sensitive data and *when*. This table
-- logs access to fields defined in T081. It provides the audit trail necessary for
-- Data Breach investigations and compliance reporting.
-- KPIs: PII access visibility.
-- Feature Reference: T081
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.pii_access_logs (
    -- Primary Key
    access_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Actor
    user_id UUID REFERENCES core.system_users(user_id),
    user_role VARCHAR(50),

    -- Data
    table_name VARCHAR(100) NOT NULL,
    record_id UUID NOT NULL,
    fields_accessed TEXT[], -- e.g., {'ssn', 'email'}

    -- Context
    reason_code VARCHAR(20), -- BUSINESS_PROCESS, SUPPORT
    access_type VARCHAR(10), -- READ, WRITE

    -- Metadata
    accessed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_pii_access_record ON core.pii_access_logs(table_name, record_id);
COMMENT ON TABLE core.pii_access_logs IS 'Detailed log of PII data access';

------------------------------------------------------------------------------------------------
-- Table: T493 - audit_trail_records
-- Description: Configured audit records for tables (T082).
-- Business Case: T082 defines *which* tables to audit. This table stores the actual audit
-- records for those tables. It uses JSONB to store the full row state (old and new)
-- as per T082 configuration, ensuring a centralized, queryable audit store.
-- KPIs: Audit record completeness.
-- Feature Reference: T082
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.audit_trail_records (
    -- Primary Key
    record_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    table_name VARCHAR(100) NOT NULL,
    record_uuid UUID NOT NULL, -- The ID of the row changed
    operation_type VARCHAR(10) NOT NULL, -- INSERT, UPDATE, DELETE

    -- Data
    old_data JSONB,
    new_data JSONB,

    -- Actor
    changed_by UUID REFERENCES core.system_users(user_id),
    changed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_audit_trail_table ON core.audit_trail_records(table_name, changed_at DESC);
COMMENT ON TABLE core.audit_trail_records IS 'Centralized audit storage';

------------------------------------------------------------------------------------------------
-- Table: T494 - encryption_key_rotation
-- Description: Schedule and history of key rotation (T083).
-- Business Case: Tracks the schedule for rotating T083 keys. This table ensures keys are
-- rotated before they expire or are compromised. It logs the rotation events,
-- linking old and new key IDs for decryption continuity of legacy data.
-- KPIs: Key rotation schedule adherence.
-- Feature Reference: T083
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.encryption_key_rotation (
    -- Primary Key
    rotation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    key_id UUID REFERENCES core.encryption_keys(key_id),
    previous_key_id UUID REFERENCES core.encryption_keys(key_id),

    -- Schedule
    rotation_date DATE NOT NULL,
    rotation_status VARCHAR(20) DEFAULT 'PENDING',

    -- Metadata
    executed_by UUID REFERENCES core.system_users(user_id),
    completed_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.encryption_key_rotation IS 'Schedule for encryption key rotation';

------------------------------------------------------------------------------------------------
-- Table: T495 - api_spec_versions
-- Description: Tracks active versions of API specs (T084).
-- Business Case: Manages the deprecation and sunset of T084 specs. Allows multiple versions
-- to coexist (e.g., v1 and v2) for a smooth transition. This table maps
-- incoming API version headers to the correct T084 ID.
-- KPIs: API version fragmentation.
-- Feature Reference: T084
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.api_spec_versions (
    -- Primary Key
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    spec_name VARCHAR(100) NOT NULL,
    version VARCHAR(20) NOT NULL,
    spec_id UUID REFERENCES core.api_specifications(id),

    -- Lifecycle
    is_default BOOLEAN DEFAULT false,
    is_deprecated BOOLEAN DEFAULT false,
    sunset_date DATE,

    -- Routing
    header_value VARCHAR(50), -- e.g., 'application/vnd.pari.v2+json'

    -- Constraints
    CONSTRAINT spec_name_ver UNIQUE (spec_name, version)
);

COMMENT ON TABLE core.api_spec_versions IS 'Active API version mapping';

------------------------------------------------------------------------------------------------
-- Table: T496 - service_registry
-- Description: Dynamic registry of microservices (T085).
-- Business Case: While T085 holds definitions, this table holds the live instances (pods,
-- containers) of the service. Enables client-side load balancing and discovery
-- within the K8s cluster.
-- KPIs: Service availability.
-- Feature Reference: T085
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.service_registry (
    -- Primary Key
    instance_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Service Identity
    service_name VARCHAR(100) NOT NULL,
    service_version VARCHAR(50) NOT NULL,

    -- Network
    host_ip INET NOT NULL,
    port INTEGER NOT NULL,
    last_heartbeat TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- State
    is_healthy BOOLEAN DEFAULT true
);

CREATE INDEX idx_service_registry_name ON core.service_registry(service_name, is_healthy);
COMMENT ON TABLE core.service_registry IS 'Live instances of microservices';

------------------------------------------------------------------------------------------------
-- Table: T497 - load_balancer_status
-- Description: Real-time status of Load Balancers (T086).
-- Business Case: T086 defines config; this table monitors the operational status of the LBs
-- (Active, Draining, Error). It feeds the automated failover logic if a
-- load balancer fails.
-- KPIs: Load Balancer uptime.
-- Feature Reference: T086
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.load_balancer_status (
    -- Primary Key
    lb_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    lb_name VARCHAR(100) NOT NULL REFERENCES core.load_balancer_config(lb_name),
    vip_address INET NOT NULL,

    -- State
    status VARCHAR(20) NOT NULL, -- ACTIVE, ERROR, DRAINING
    active_connections INTEGER,
    throughput_mbps NUMERIC(10,2),

    -- Metadata
    checked_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.load_balancer_status IS 'Real-time status of load balancers';

------------------------------------------------------------------------------------------------
-- Table: T498 - cache_invalidation_logs
-- Description: Logs of cache invalidation events (T087).
-- Business Case: When T087 rules are triggered (e.g., currency update), caches are cleared.
-- This table logs these events. It helps debug performance issues where a cache
-- was incorrectly cleared, causing a database stampede.
-- KPIs: Cache invalidation error rate.
-- Feature Reference: T087
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cache_invalidation_logs (
    -- Primary Key
    log_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    table_name VARCHAR(100) NOT NULL,
    trigger_event VARCHAR(50) NOT NULL, -- INSERT, UPDATE
    cache_key_pattern TEXT NOT NULL, -- e.g., 'currency:EUR:*'

    -- Result
    success BOOLEAN NOT NULL,
    error_message TEXT,

    -- Metadata
    invalidated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.cache_invalidation_logs IS 'Logs of cache invalidation operations';

------------------------------------------------------------------------------------------------
-- Table: T499 - shard_mapping_history
-- Description: History of changes to shard mapping (T088).
-- Business Case: T088 maps logical shards to physical DBs. When this mapping changes (e.g.,
-- moving a shard to new hardware), this table records the move. It ensures that
-- in-flight transactions or lagging consumers (T096) can be accounted for or
-- retried against the correct location.
-- KPIs: Shard migration success.
-- Feature Reference: T088
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.shard_mapping_history (
    -- Primary Key
    history_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    shard_id INTEGER REFERENCES core.database_shards(shard_id),
    old_db_host VARCHAR(255),
    new_db_host VARCHAR(255),

    -- Operation
    migration_status VARCHAR(20) NOT NULL, -- PLANNED, IN_PROGRESS, COMPLETED
    started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.shard_mapping_history IS 'History of shard migrations';

------------------------------------------------------------------------------------------------
-- Table: T500 - pool_configuration_history
-- Description: History of pool size adjustments (T089).
-- Business Case: T089 config changes frequently. This table logs changes to pool limits
-- (max_connections). It helps correlate performance issues (timeouts) with specific
-- infrastructure scaling events.
-- KPIs: Configuration change tracking.
-- Feature Reference: T089
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.pool_configuration_history (
    -- Primary Key
    change_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    pool_name VARCHAR(100) NOT NULL REFERENCES core.connection_pools(pool_name),

    -- Change
    attribute_name VARCHAR(50) NOT NULL, -- max_connections, timeout
    old_value NUMERIC(10,2),
    new_value NUMERIC(10,2),

    -- Actor
    changed_by UUID REFERENCES core.system_users(user_id),
    changed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.pool_configuration_history IS 'History of pool config changes';

------------------------------------------------------------------------------------------------
-- Table: T501 - partition_config_history
-- Description: History of partition scheme changes (T090).
-- Business Case: Partitioning schemes (T090) may evolve (changing from daily to hourly).
-- This table logs these schema changes, which is critical for DBAs to manage
-- the lifecycle of old partitions vs new ones.
-- KPIs: Schema evolution tracking.
-- Feature Reference: T090
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.partition_config_history (
    -- Primary Key
    history_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    table_name VARCHAR(100) NOT NULL REFERENCES core.partition_schemes(table_name),

    -- Change
    old_interval VARCHAR(50),
    new_interval VARCHAR(50),
    partition_key VARCHAR(100),

    -- Actor
    applied_by UUID REFERENCES core.system_users(user_id),
    applied_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.partition_config_history IS 'History of partitioning scheme changes';

------------------------------------------------------------------------------------------------
-- Table: T502 - index_usage_history
-- Description: History of index usage stats (T091).
-- Business Case: Tracks usage of indexes over time. Helps identify indexes that became obsolete
-- (usage drops to zero) or those that became critical (usage spikes). It supports
-- periodic index cleanup or creation efforts.
-- KPIs: Index efficiency.
-- Feature Reference: T091
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.index_usage_history (
    -- Primary Key
    stat_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    index_name VARCHAR(255) NOT NULL,
    table_name VARCHAR(100) NOT NULL,

    -- Metrics
    usage_count BIGINT,
    size_bytes BIGINT,

    -- Metadata
    measured_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.index_usage_history IS 'Historical stats for index usage';

------------------------------------------------------------------------------------------------
-- Table: T503 - distributed_lock_history
-- Description: History of held locks (T092).
-- Business Case: Tracks lifecycle of locks (Acquire, Release, Expire). Useful for debugging
-- deadlocks (where a lock was never released) or long-running processes that
-- are monopolizing shared resources.
-- KPIs: Lock release rate.
-- Feature Reference: T092
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.distributed_lock_history (
    -- Primary Key
    history_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    lock_key VARCHAR(255) NOT NULL,
    owner_id UUID,

    -- Event
    event_type VARCHAR(20) NOT NULL, -- ACQUIRE, RELEASE, EXPIRE
    event_time TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_lock_history_key ON core.distributed_lock_history(lock_key, event_time DESC);
COMMENT ON TABLE core.distributed_lock_history IS 'History of lock acquisition/release';

------------------------------------------------------------------------------------------------
-- Table: T504 - cron_schedules
-- Description: Dynamic scheduling overrides for jobs (T093).
-- Business Case: Sometimes jobs need to be paused or triggered ad-hoc. This table stores
-- overrides to the Cron expression in T093. It allows operations to pause
-- processing (e.g., maintenance) without changing the permanent definition.
-- KPIs: Schedule flexibility.
-- Feature Reference: T093
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cron_schedules (
    -- Primary Key
    schedule_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    job_name VARCHAR(100) NOT NULL REFERENCES core.scheduled_jobs(job_name),

    -- Override
    paused BOOLEAN DEFAULT false,
    next_run_at TIMESTAMP WITH TIME ZONE,
    override_cron VARCHAR(50), -- One-time override

    -- Metadata
    updated_by UUID REFERENCES core.system_users(user_id),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.cron_schedules IS 'Dynamic scheduling overrides for cron jobs';

------------------------------------------------------------------------------------------------
-- Table: T505 - async_task_queue
-- Description: Definition of task types/queues (T094).
-- Business Case: Defines the properties of queues (Retry policy, Priority). T094 logs the
-- instances; this table defines the queue itself (e.g., "High Priority Validation"
-- has 3 retries).
-- KPIs: Queue configuration management.
-- Feature Reference: T094
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.async_task_queue (
    -- Primary Key
    queue_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    queue_name VARCHAR(100) NOT NULL,
    task_type VARCHAR(100) NOT NULL,
    priority INTEGER DEFAULT 5,

    -- Policy
    max_retries INTEGER DEFAULT 3,
    backoff_strategy VARCHAR(20) DEFAULT 'EXPONENTIAL',
    timeout_seconds INTEGER,

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.async_task_queue IS 'Definitions of background task queues';

------------------------------------------------------------------------------------------------
-- Table: T506 - kafka_config
-- Description: Configuration for Kafka clients (T095).
-- Business Case: Stores producer/consumer configuration per topic (acks, retries, compression).
-- This ensures that different topics (e.g., high-risk validation vs logs) can
-- have appropriate reliability/durability settings.
-- KPIs: Kafka configuration consistency.
-- Feature Reference: T095
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.kafka_config (
    -- Primary Key
    config_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    topic_name VARCHAR(255) NOT NULL REFERENCES core.message_queue_topics(topic_name),
    client_type VARCHAR(20), -- PRODUCER, CONSUMER

    -- Config
    acks VARCHAR(20) DEFAULT '1', -- 0, 1, all
    compression_type VARCHAR(20) DEFAULT 'SNAPPY',
    retries INTEGER DEFAULT 3,
    batch_size INTEGER DEFAULT 16384
);

COMMENT ON TABLE core.kafka_config IS 'Per-topic Kafka client configuration';

------------------------------------------------------------------------------------------------
-- Table: T507 - consumer_group_config
-- Description: Configuration for Consumer Groups (T096).
-- Business Case: Defines group settings (session timeout, auto-offset-reset). This table allows
-- tuning of T096 groups to balance latency (frequent commits) vs throughput
-- (batch commits).
-- KPIs: Consumer performance tuning.
-- Feature Reference: T096
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.consumer_group_config (
    -- Primary Key
    config_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    group_id VARCHAR(255) NOT NULL,

    -- Config
    auto_offset_reset VARCHAR(20) DEFAULT 'EARLIEST',
    session_timeout_ms INTEGER DEFAULT 30000,
    max_poll_records INTEGER DEFAULT 500
);

COMMENT ON TABLE core.consumer_group_config IS 'Configuration for consumer groups';

------------------------------------------------------------------------------------------------
-- Table: T508 - migration_history
-- Description: Detailed log of DB schema migrations (T097).
-- Business Case: T097 lists applied migrations. This table logs the *execution details*:
-- checksums, duration, script content. It provides a deeper forensic trail than
-- T097 for auditing database changes.
-- KPIs: Migration safety.
-- Feature Reference: T097
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.migration_history (
    -- Primary Key
    history_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    migration_id VARCHAR(255) NOT NULL REFERENCES core.schema_evolution_history(migration_id),

    -- Execution
    script_text TEXT NOT NULL,
    checksum_before CHAR(64),
    checksum_after CHAR(64),
    execution_time_ms INTEGER,

    -- Metadata
    applied_by VARCHAR(100), -- System or User
    applied_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.migration_history IS 'Detailed execution log for schema migrations';

------------------------------------------------------------------------------------------------
-- Table: T509 - view_dependencies_history
-- Description: History of changes to view dependencies (T098).
-- Business Case: Tracks changes in the DAG of views (T098). Helps identify breaking
-- changes where a downstream view depends on a column that was renamed in the
-- upstream table.
-- KPIs: View dependency integrity.
-- Feature Reference: T098
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.view_dependencies_history (
    -- Primary Key
    history_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    view_name VARCHAR(255) NOT NULL,
    dependency_name VARCHAR(255) NOT NULL,

    -- Event
    event_type VARCHAR(20) NOT NULL, -- ADDED, REMOVED, CHANGED
    detected_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.view_dependencies_history IS 'History of view dependency changes';

------------------------------------------------------------------------------------------------
-- Table: T510 - trigger_execution_history
-- Description: History of trigger executions (T099).
-- Business Case: Logs details of trigger fires, including the data that caused the fire.
-- This can be useful for debugging complex logic implemented in triggers (e.g.,
-- "Why was this specific row updated?").
-- KPIs: Trigger debugging capability.
-- Feature Reference: T099
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.trigger_execution_history (
    -- Primary Key
    history_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    trigger_name VARCHAR(100) NOT NULL REFERENCES core.trigger_definitions(trigger_name),
    table_name VARCHAR(100) NOT NULL,

    -- Payload
    row_id UUID,
    operation VARCHAR(10) NOT NULL,

    -- Data
    row_data JSONB, -- Snapshot of the row (limited size)

    -- Metadata
    fired_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.trigger_execution_history IS 'Detailed history of trigger fires';

------------------------------------------------------------------------------------------------
-- Table: T511 - proc_registry
-- Description: Detailed registry of Stored Procedures (T100).
-- Business Case: While T100 exists, this table adds metadata like source code hashes,
-- change history, and dependencies. It ensures that the T100 registry is
-- comprehensive and allows automated detection of code drift in stored logic.
-- KPIs: Stored logic integrity.
-- Feature Reference: T100
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.proc_registry (
    -- Primary Key
    registry_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    proc_name VARCHAR(255) NOT NULL REFERENCES core.stored_procedures(proc_name),

    -- Metadata
    source_hash CHAR(64), -- Hash of the function body
    dependencies TEXT[], -- Tables/Functions called
    line_count INTEGER,

    -- State
    is_valid BOOLEAN DEFAULT true,
    last_validated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.proc_registry IS 'Extended registry for stored procedures';

------------------------------------------------------------------------------------------------
-- Table: T512 - federated_identities
-- Description: Stores identities from external IdPs (OIDC/SAML - T039/T075).
-- Business Case: Cache of user identities from Google, Okta, etc. Maps the external
-- subject/sub to an internal `system_user_id` (T451). Enables Single Sign-On
-- (SSO) by linking external accounts to local roles.
-- KPIs: SSO login latency.
-- Feature Reference: T039, T075
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.federated_identities (
    -- Primary Key
    identity_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- External Identity
    provider_id VARCHAR(50) NOT NULL, -- 'google', 'okta'
    provider_subject TEXT NOT NULL, -- Email or User ID
    provider_issuer_url TEXT NOT NULL,

    -- Local Mapping
    user_id UUID NOT NULL REFERENCES core.system_users(user_id),

    -- State
    is_active BOOLEAN DEFAULT true,
    last_login_at TIMESTAMP WITH TIME ZONE,

    -- Constraints
    CONSTRAINT fed_identity_unique UNIQUE (provider_id, provider_subject)
);

CREATE INDEX idx_fed_identities_user ON core.federated_identities(user_id);
COMMENT ON TABLE core.federated_identities IS 'Federated identity mapping';

------------------------------------------------------------------------------------------------
-- Table: T513 - trusted_devices
-- Description: Stores trusted devices for 2FA/Device Binding (F026, F126).
-- Business Case: M12 can bind validation rules to trusted devices (e.g., skip extra checks
-- if from trusted device). This table stores user-agent hashes, IP ranges,
-- or fingerprints linked to users. Enhances security without sacrificing UX.
-- KPIs: Fraud reduction via Device Binding.
-- Feature Reference: F026, F126
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.trusted_devices (
    -- Primary Key
    device_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Owner
    user_id UUID NOT NULL REFERENCES core.system_users(user_id),

    -- Device Data
    user_agent_hash CHAR(64) NOT NULL,
    device_fingerprint JSONB, -- Canvas, WebGL hashes
    trusted_ip_range INET,

    -- State
    is_active BOOLEAN DEFAULT true,
    last_seen_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.trusted_devices IS 'Trusted device profiles for MFA';

------------------------------------------------------------------------------------------------
-- Table: T514 - geo_velocity_rules
-- Description: Rules for Geo-Velocity checks (Speed of travel).
-- Business Case: Detects impossible travel (e.g., Login in London 10 mins after Login in
-- Tokyo). This table defines thresholds (distance per hour) per risk level.
-- It feeds into F126 (Timestamp Sync) and M03 (Fraud).
-- KPIs: Geo-velocity fraud detection.
-- Feature Reference: F126
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.geo_velocity_rules (
    -- Primary Key
    rule_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Configuration
    max_distance_km INTEGER NOT NULL,
    time_window_minutes INTEGER NOT NULL,

    -- Action
    action_on_violation VARCHAR(20) NOT NULL CHECK (action_on_violation IN ('WARN', 'BLOCK', 'CHALLENGE')),
    risk_score_impact INTEGER
);

COMMENT ON TABLE core.geo_velocity_rules IS 'Configuration for geo-velocity checks';

------------------------------------------------------------------------------------------------
-- Table: T515 - behavioral_analytics
-- Description: Stores aggregated behavioral profiles for Fraud (M03).
-- Business Case: M12 validation needs context. This table stores profiles (e.g., average
-- transaction amount, login times). The validation engine queries this to compare
-- current input against historical behavior (Anomaly Detection).
-- KPIs: Behavioral fraud detection accuracy.
-- Feature Reference: F087
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.behavioral_analytics (
    -- Primary Key
    profile_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Entity
    entity_id UUID NOT NULL, -- User or Merchant ID
    entity_type VARCHAR(20) NOT NULL, -- USER, MERCHANT

    -- Metrics (JSONB for flexibility)
    metrics_snapshot JSONB NOT NULL, -- e.g., {"tx_avg": 100, "login_hours": [9,10...]}

    -- Metadata
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_behavior_entity ON core.behavioral_analytics(entity_id, entity_type);
COMMENT ON TABLE core.behavioral_analytics IS 'Behavioral profiles for anomaly detection';

------------------------------------------------------------------------------------------------
-- Table: T516 - compliance_certificates
-- Description: Stores evidence of compliance certifications (SOC2, ISO27001).
-- Business Case: Tracks the lifecycle of compliance evidence. Stores links to reports
-- (PDF) and audit dates. Ensures that the platform always has valid evidence
-- ready for auditors or partners requiring due diligence.
-- KPIs: Compliance audit readiness.
-- Feature Reference: Governance
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.compliance_certificates (
    -- Primary Key
    cert_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    certificate_type VARCHAR(50) NOT NULL, -- SOC2_TYPE2, ISO27001
    scope TEXT NOT NULL,

    -- Evidence
    report_url TEXT, -- S3 Link
    issue_date DATE NOT NULL,
    expiry_date DATE NOT NULL,

    -- Audit
    auditor_firm VARCHAR(255),

    -- State
    is_current BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.compliance_certificates IS 'Compliance certificate tracking';

------------------------------------------------------------------------------------------------
-- Table: T517 - disaster_recovery_plans
-- Description: Configuration for Disaster Recovery (DR) procedures.
-- Business Case: Defines DR steps, RTO (Recovery Time Objective), and RPO (Recovery Point
-- Objective) for the M12 module. Ensures that in case of data center failure,
-- the validation framework can be restored within SLA.
-- KPIs: Recovery Time Objective (RTO) adherence.
-- Feature Reference: Infra
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.disaster_recovery_plans (
    -- Primary Key
    plan_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Configuration
    service_component VARCHAR(100) NOT NULL, -- 'M12_API', 'POSTGRES_DB'
    rto_minutes INTEGER NOT NULL,
    rpo_minutes INTEGER NOT NULL,

    -- Procedure
    failover_instructions TEXT, -- Markdown
    contact_list JSONB, -- On-call engineers

    -- Testing
    last_test_date DATE,
    last_test_result VARCHAR(20) -- PASS, FAIL
);

COMMENT ON TABLE core.disaster_recovery_plans IS 'Disaster recovery procedures';

------------------------------------------------------------------------------------------------
-- Table: T518 - backup_manifests
-- Description: Manifest of database backups.
-- Business Case: Lists available backups, their sizes, and checksums. Allows restoration
-- of specific tables (T001, T005) to a point-in-time. Critical for
-- recovering from logical data corruption (e.g., bad mass update).
-- KPIs: Backup availability.
-- Feature Reference: Data
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.backup_manifests (
    -- Primary Key
    backup_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    backup_type VARCHAR(20) NOT NULL, -- FULL, INCREMENTAL
    database_name VARCHAR(100) NOT NULL,

    -- Backup Data
    started_at TIMESTAMP WITH TIME ZONE NOT NULL,
    completed_at TIMESTAMP WITH TIME ZONE,
    size_bytes BIGINT,
    checksum_sha256 CHAR(64) NOT NULL,

    -- Location
    storage_path TEXT NOT NULL, -- S3 URI

    -- Status
    status VARCHAR(20) NOT NULL -- COMPLETED, FAILED, RESTORING
);

COMMENT ON TABLE core.backup_manifests IS 'Database backup catalog';

------------------------------------------------------------------------------------------------
-- Table: T519 - restoration_logs
-- Description: Logs of backup restoration operations.
-- Business Case: Tracks who restored what data and when. Essential for security investigation.
-- Restoration can be risky (overwriting live data), so this audit trail ensures
-- accountability and checks for conflicts.
-- KPIs: Restoration safety.
-- Feature Reference: Data
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.restoration_logs (
    -- Primary Key
    log_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    backup_id UUID NOT NULL REFERENCES core.backup_manifests(backup_id),

    -- Operation
    target_tables TEXT[], -- Specific tables restored
    point_in_time TIMESTAMP WITH TIME ZONE,

    -- Actor
    requested_by UUID NOT NULL REFERENCES core.system_users(user_id),
    approved_by UUID REFERENCES core.system_users(user_id),

    -- State
    status VARCHAR(20) NOT NULL,
    started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    completed_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.restoration_logs IS 'Audit log of restoration events';

------------------------------------------------------------------------------------------------
-- Table: T520 - capacity_planning
-- Description: Stores metrics for capacity planning (CPU, Storage growth).
-- Business Case: Projects future resource needs based on current trends (e.g., T005
-- growth rate). Helps engineers provision infrastructure ahead of time to prevent
-- performance degradation.
-- KPIs: Capacity forecast accuracy.
-- Feature Reference: Infra
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.capacity_planning (
    -- Primary Key
    metric_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Dimensions
    resource_type VARCHAR(50) NOT NULL, -- CPU, STORAGE, CONNECTIONS
    service_component VARCHAR(100) NOT NULL,
    forecast_date DATE NOT NULL,

    -- Metrics
    projected_value NUMERIC(15,2) NOT NULL,
    actual_value NUMERIC(15,2),

    -- Model
    model_version VARCHAR(20),
    confidence_level VARCHAR(20) -- HIGH, MEDIUM, LOW
);

COMMENT ON TABLE core.capacity_planning IS 'Capacity planning metrics';

------------------------------------------------------------------------------------------------
-- Table: T521 - cost_allocation
-- Description: Allocates infrastructure costs to tenants/features.
-- Business Case: Attributes AWS/Azure costs to specific tenants (T048) or features. Enables
-- multi-tenant billing (T134) by calculating "Validation Cost Per Transaction".
-- KPIs: Cost attribution accuracy.
-- Feature Reference: T048
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cost_allocation (
    -- Primary Key
    allocation_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    cost_center VARCHAR(100) NOT NULL, -- 'TENANT_A', 'M12_CORE'
    tenant_id UUID REFERENCES core.tenants(tenant_id),

    -- Cost Data
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,

    -- Breakdown
    compute_cost NUMERIC(15,2),
    storage_cost NUMERIC(15,2),
    bandwidth_cost NUMERIC(15,2),
    total_cost NUMERIC(15,2)
);

COMMENT ON TABLE core.cost_allocation IS 'Infrastructure cost allocation';

------------------------------------------------------------------------------------------------
-- Table: T522 - sla_reports
-- Description: Stores SLA (Service Level Agreement) performance reports.
-- Business Case: Aggregates performance metrics against defined SLA targets (e.g., API Latency
-- < 200ms). Generates SLA Breach reports for internal governance and customer
-- accountability.
-- KPIs: SLA breach rate.
-- Feature Reference: M08
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.sla_reports (
    -- Primary Key
    report_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    sla_target_id VARCHAR(50) NOT NULL,
    report_period DATE NOT NULL,

    -- Performance
    target_value NUMERIC(10,2),
    actual_value NUMERIC(10,2),
    is_breach BOOLEAN NOT NULL,

    -- Details
    breach_details TEXT,

    -- State
    generated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.sla_reports IS 'SLA performance tracking';

------------------------------------------------------------------------------------------------
-- Table: T523 - incident_reports
-- Description: Stores incident management reports.
-- Business Case: Tracks incidents (outages, bugs) impacting M12. Links to root cause analysis
-- (RCA) and post-mortems. Ensures that recurring incidents are mitigated via
-- follow-up actions.
-- KPIs: Mean Time To Resolve (MTTR).
-- Feature Reference: M08
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.incident_reports (
    -- Primary Key
    incident_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Incident
    title TEXT NOT NULL,
    severity VARCHAR(20) NOT NULL, -- SEV1, SEV2, SEV3
    status VARCHAR(20) NOT NULL, -- OPEN, INVESTIGATING, RESOLVED

    -- Timing
    detected_at TIMESTAMP WITH TIME ZONE NOT NULL,
    resolved_at TIMESTAMP WITH TIME ZONE,

    -- Details
    root_cause TEXT,
    resolution_summary TEXT,

    -- Assignment
    assigned_to UUID REFERENCES core.system_users(user_id)
);

COMMENT ON TABLE core.incident_reports IS 'Incident management records';

------------------------------------------------------------------------------------------------
-- Table: T524 - change_management
-- Description: Tickets for ITIL-style Change Management.
-- Business Case: Requires approval for high-risk changes (e.g., Schema Migration, T097).
-- This table stores Change Requests (CR), approval status, and CAB (Change Advisory
-- Board) decisions. Ensures controlled modifications to the validation framework.
-- KPIs: Change approval time.
-- Feature Reference: T097
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.change_management (
    -- Primary Key
    change_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    title TEXT NOT NULL,
    change_type VARCHAR(50) NOT NULL, -- STANDARD, NORMAL, EMERGENCY
    risk_score INTEGER CHECK (risk_score BETWEEN 1 AND 5),

    -- Execution
    planned_start_date DATE NOT NULL,
    planned_end_date DATE NOT NULL,

    -- Approval
    requested_by UUID NOT NULL REFERENCES core.system_users(user_id),
    approval_status VARCHAR(20) DEFAULT 'PENDING', -- PENDING, APPROVED, REJECTED
    approved_by UUID REFERENCES core.system_users(user_id),
    approver_comments TEXT
);

COMMENT ON TABLE core.change_management IS 'Change Management tickets';

------------------------------------------------------------------------------------------------
-- Table: T525 - access_requests
-- Description: Tickets requesting privileged access.
-- Business Case: Users request elevated access (e.g., 'Audit_Log_View') for investigations.
-- This table tracks the request, justification, and temporary grant status.
-- Ensures oversight of privileged data access.
-- KPIs: Access request processing time.
-- Feature Reference: T456
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.access_requests (
    -- Primary Key
    request_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Request
    requested_by UUID NOT NULL REFERENCES core.system_users(user_id),
    resource_type VARCHAR(100) NOT NULL, -- 'AUDIT_LOG', 'PII_DATA'
    justification TEXT NOT NULL,

    -- Lifecycle
    status VARCHAR(20) DEFAULT 'PENDING', -- PENDING, APPROVED, DENIED, EXPIRED
    granted_by UUID REFERENCES core.system_users(user_id),

    -- Duration
    access_from TIMESTAMP WITH TIME ZONE,
    access_until TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.access_requests IS 'Requests for privileged access';

------------------------------------------------------------------------------------------------
-- Table: T526 - approval_workflows
-- Description: Definition of approval workflows (T524, T525).
-- Business Case: Defines the sequence of approvers (e.g., Manager -> Security Officer).
-- This table configures how T524/T525 requests route, enabling complex approval
-- chains without code changes.
-- KPIs: Workflow flexibility.
-- Feature Reference: T524
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.approval_workflows (
    -- Primary Key
    workflow_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    workflow_name VARCHAR(100) NOT NULL,
    target_type VARCHAR(50) NOT NULL, -- 'CHANGE_REQUEST', 'ACCESS_REQUEST'

    -- Steps (JSONB for flexibility)
    steps JSONB NOT NULL, -- [{"step": 1, "role": "Manager"}, {"step": 2, "role": "Admin"}]

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.approval_workflows IS 'Definitions of approval workflows';

------------------------------------------------------------------------------------------------
-- Table: T527 - user_provisioning
-- Description: Logs of user creation/provisioning events.
-- Business Case: Tracks automated provisioning of users (T451) via IdP (T039) or Admin.
-- Ensures that all users have valid roles and permissions assigned correctly upon
-- creation.
-- KPIs: Provisioning success rate.
-- Feature Reference: T451
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.user_provisioning (
    -- Primary Key
    provisioning_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    user_id UUID REFERENCES core.system_users(user_id),
    source_system VARCHAR(50), -- 'SCIM', 'LDAP', 'MANUAL'

    -- Action
    action_type VARCHAR(20) NOT NULL, -- CREATE, UPDATE, DISABLE
    roles_assigned TEXT[],
    permissions_granted TEXT[],

    -- State
    status VARCHAR(20) NOT NULL, -- SUCCESS, FAILED
    error_message TEXT,

    -- Metadata
    occurred_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.user_provisioning IS 'Logs of user provisioning';

------------------------------------------------------------------------------------------------
-- Table: T528 - resource_quotas
-- Description: Defines quotas for resources (Compute, Storage) per tenant/user.
-- Business Case: Multi-tenant limits (T048). This table defines limits to prevent "Noisy
-- Neighbor" issues where one tenant's validation load impacts others. Enforced
-- by the control plane.
-- KPIs: Resource quota compliance.
-- Feature Reference: T048
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.resource_quotas (
    -- Primary Key
    quota_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Scope
    tenant_id UUID REFERENCES core.tenants(tenant_id),
    resource_type VARCHAR(50) NOT NULL, -- 'API_CALLS', 'VALIDATION_RULES'

    -- Limits
    limit_value NUMERIC(15,2) NOT NULL,
    period VARCHAR(20), -- 'HOURLY', 'MONTHLY'

    -- Current Usage
    current_value NUMERIC(15,2) DEFAULT 0,
    last_reset TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_quota_tenant ON core.resource_quotas(tenant_id, resource_type);
COMMENT ON TABLE core.resource_quotas IS 'Resource quotas per tenant';

------------------------------------------------------------------------------------------------
-- Table: T529 - tag_taxonomy
-- Description: Hierarchical structure of tags for organizing resources.
-- Business Case: Taxonomy for Tags (e.g., 'Finance', 'Europe', 'Payments'). This table
-- defines the hierarchy. Tags allow flexible classification of rules (T001) or
-- data for reporting and filtering.
-- KPIs: Tag usage consistency.
-- Feature Reference: Organization
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.tag_taxonomy (
    -- Primary Key
    tag_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    tag_name VARCHAR(100) NOT NULL,
    parent_tag_id UUID REFERENCES core.tag_taxonomy(tag_id),

    -- State
    color VARCHAR(7), -- Hex for UI
    is_system_tag BOOLEAN DEFAULT false -- Cannot be deleted
);

COMMENT ON TABLE core.tag_taxonomy IS 'Hierarchical tag definitions';

------------------------------------------------------------------------------------------------
-- Table: T530 - resource_inventory
-- Description: Catalog of all system resources (Services, DBs, Queues).
-- Business Case: CMDB (Configuration Management Database) for M12 components. Tracks
-- ownership, dependencies, and environment. Essential for impact analysis
-- before changes.
-- KPIs: Asset visibility.
-- Feature Reference: Discovery
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.resource_inventory (
    -- Primary Key
    asset_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identity
    asset_name VARCHAR(100) NOT NULL,
    asset_type VARCHAR(50) NOT NULL, -- 'DATABASE', 'SERVICE', 'QUEUE', 'CACHE'
    environment VARCHAR(20) NOT NULL, -- DEV, STAGING, PROD

    -- Details
    description TEXT,
    configuration_url TEXT, -- Link to T084 or Config repo

    -- Ownership
    owner_id UUID REFERENCES core.system_users(user_id),
    team VARCHAR(100),

    -- Lifecycle
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE'
);

COMMENT ON TABLE core.resource_inventory IS 'CMDB for system resources';

------------------------------------------------------------------------------------------------
-- Table: T531 - security_policies
-- Description: Definitions of security policies (e.g., Password Complexity).
-- Business Case: Stores the logic for policies like "Must rotate keys every 90 days" or
-- "Password must be 12 chars". The validation engine (M12) enforces these
-- policies on configuration changes.
-- KPIs: Policy enforcement rate.
-- Feature Reference: T467
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.security_policies (
    -- Primary Key
    policy_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Definition
    policy_name VARCHAR(100) NOT NULL,
    policy_type VARCHAR(50) NOT NULL, -- 'KEY_ROTATION', 'PASSWORD_COMPLEXITY'
    rule_json JSONB NOT NULL, -- {"min_length": 12}

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.security_policies IS 'Definitions of security policies';

------------------------------------------------------------------------------------------------
-- Table: T532 - policy_assignments
-- Description: Assigns policies (T531) to resources/users.
-- Business Case: Maps "Key Rotation" policy to "Encryption Keys" (T083). Or assigns "Strict
-- IP" policy to "Admin Users". This flexible assignment ensures policies are
-- applied where needed without hardcoding.
-- KPIs: Policy coverage.
-- Feature Reference: T531
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.policy_assignments (
    -- Primary Key
    assignment_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Link
    policy_id UUID NOT NULL REFERENCES core.security_policies(policy_id),
    target_type VARCHAR(50) NOT NULL, -- 'RESOURCE', 'ROLE', 'USER'
    target_id UUID NOT NULL, -- ID of Resource or User or Role

    -- Constraints
    CONSTRAINT policy_assign_unique UNIQUE (policy_id, target_type, target_id)
);

COMMENT ON TABLE core.policy_assignments IS 'Assignments of security policies';

------------------------------------------------------------------------------------------------
-- Table: T533 - compliance_scans
-- Description: Logs of automated compliance scans (Vulnerability scanning).
-- Business Case: Stores results from tools (e.g., Nessus, SonarQube) scanning the M12
-- codebase/infra. Tracks CVEs and security findings. Ensures the validation
-- framework is hardened against known threats.
-- KPIs: Vulnerability remediation time.
-- Feature Reference: Security
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.compliance_scans (
    -- Primary Key
    scan_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    tool_name VARCHAR(50) NOT NULL,
    target_resource VARCHAR(100) NOT NULL,

    -- Result
    scan_date DATE NOT NULL,
    total_findings INTEGER,
    critical_findings INTEGER,

    -- Artifact
    report_url TEXT
);

COMMENT ON TABLE core.compliance_scans IS 'Results of compliance/vulnerability scans';

------------------------------------------------------------------------------------------------
-- Table: T534 - vulnerability_findings
-- Description: Detailed list of vulnerabilities from scans (T533).
-- Business Case: Stores individual findings (CVE ID, Severity, Status). Links to the
-- specific code commit or infrastructure change that introduced it. Enables tracking
-- of security debt.
-- KPIs: Vulnerability backlog.
-- Feature Reference: T533
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.vulnerability_findings (
    -- Primary Key
    finding_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Vulnerability
    cve_id VARCHAR(50),
    title TEXT NOT NULL,
    severity VARCHAR(20) NOT NULL, -- CRITICAL, HIGH, MEDIUM, LOW
    state VARCHAR(20) DEFAULT 'OPEN', -- OPEN, FIXED, IGNORED

    -- Context
    scan_id UUID REFERENCES core.compliance_scans(scan_id),
    remediation_ticket_id VARCHAR(100), -- Link to JIRA/ServiceNow

    -- Fix
    fixed_by UUID REFERENCES core.system_users(user_id),
    fixed_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.vulnerability_findings IS 'Detailed vulnerability records';

------------------------------------------------------------------------------------------------
-- Table: T535 - patch_management
-- Description: Tracks application of security patches.
-- Business Case: Ensures OS and Libs are patched. Records patch application to specific
-- environments. Prevents known exploits (Log4j, etc.) from affecting the M12
-- validation engine.
-- KPIs: Patch lag (Days behind).
-- Feature Reference: Security
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.patch_management (
    -- Primary Key
    patch_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Patch
    patch_name VARCHAR(100) NOT NULL,
    cve_ids TEXT[], -- Array of CVEs addressed

    -- Application
    environment VARCHAR(20) NOT NULL,
    installed_version VARCHAR(50),
    patched_by UUID REFERENCES core.system_users(user_id),

    -- State
    installed_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    is_rollback BOOLEAN DEFAULT false
);

COMMENT ON TABLE core.patch_management IS 'Security patch tracking';

------------------------------------------------------------------------------------------------
-- Table: T536 - config_deltas
-- Description: Tracks changes to configuration values (Drift detection).
-- Business Case: Detects "Drift" where the actual config of a running service differs
-- from the expected config (T049, T084). This indicates unauthorized changes
-- or failed deployments.
-- KPIs: Configuration drift incidents.
-- Feature Reference: T049
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.config_deltas (
    -- Primary Key
    delta_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    service_name VARCHAR(100) NOT NULL,
    config_key TEXT NOT NULL,

    -- Deltas
    expected_value JSONB,
    actual_value JSONB,

    -- State
    detected_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    resolved_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.config_deltas IS 'Configuration drift detection logs';

------------------------------------------------------------------------------------------------
-- Table: T537 - state_exports
-- Description: Logs of database state exports (e.g., for cloning).
-- Business Case: Supports exporting M12 state (Rules, Config) to lower environments (Dev/Test).
-- Ensures that the "Golden Copy" of configuration is tracked and reproducible.
-- KPIs: Environment parity.
-- Feature Reference: Backup
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.state_exports (
    -- Primary Key
    export_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    source_environment VARCHAR(20) NOT NULL, -- PROD
    target_environment VARCHAR(20) NOT NULL, -- STAGING

    -- Details
    table_list TEXT[], -- Tables exported
    checksum CHAR(64), -- Checksum of the dump

    -- Artifact
    file_path TEXT, -- S3 Path

    -- Actor
    exported_by UUID NOT NULL REFERENCES core.system_users(user_id),
    exported_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.state_exports IS 'Database state export logs';

------------------------------------------------------------------------------------------------
-- Table: T538 - secret_scanning
-- Description: Results of secret scanning (finding keys in code).
-- Business Case: Scans code/commit logs for accidental leakage of secrets (API Keys,
-- Certificates). M12 handling PII must be secure; finding leaked secrets in
-- repo is critical.
-- KPIs: Secret leakage incidents.
-- Feature Reference: Security
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.secret_scanning (
    -- Primary Key
    scan_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    repository_url TEXT NOT NULL,
    commit_hash CHAR(40),

    -- Result
    secrets_found INTEGER,
    files_scanned INTEGER,

    -- Artifact
    scan_report_url TEXT,
    scanned_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.secret_scanning IS 'Secret scanning results';

------------------------------------------------------------------------------------------------
-- Table: T539 - data_classification
-- Description: Stores classification levels for data types (T081).
-- Business Case: Central catalog of data sensitivity. Maps 'Email' to 'PII', 'Transaction
-- Amount' to 'FINANCIAL'. Used to drive T081 and encryption requirements.
-- KPIs: Classification coverage.
-- Feature Reference: T081
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.data_classification (
    -- Primary Key
    class_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Data Identity
    resource_type VARCHAR(100) NOT NULL, -- 'TABLE.COLUMN' or 'JSON_FIELD'
    data_name VARCHAR(255) NOT NULL,

    -- Classification
    sensitivity_level VARCHAR(50) NOT NULL, -- 'PUBLIC', 'CONFIDENTIAL', 'RESTRICTED', 'TOP_SECRET'
    legal_basis TEXT, -- GDPR_ART_6_1_F

    -- State
    is_active BOOLEAN DEFAULT true
);

COMMENT ON TABLE core.data_classification IS 'Catalog of data classifications';

------------------------------------------------------------------------------------------------
-- Table: T540 - consent_records
-- Description: Stores user consent records (GDPR).
-- Business Case: M12 might process personal data (T081). This table records user
-- consent (e.g., for marketing cookies). Ensures we only process data where
-- consent is proven.
-- KPIs: Consent compliance.
-- Feature Reference: GDPR
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.consent_records (
    -- Primary Key
    consent_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- User
    user_id UUID, -- Could be anonymous hash
    tenant_id UUID NOT NULL REFERENCES core.tenants(tenant_id),

    -- Consent
    consent_type VARCHAR(50) NOT NULL, -- 'MARKETING', 'ANALYTICS'
    is_granted BOOLEAN NOT NULL,
    granted_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    revoked_at TIMESTAMP WITH TIME ZONE,

    -- Context
    legal_text TEXT, -- Version of privacy policy agreed to
    ip_address INET
);

COMMENT ON TABLE core.consent_records IS 'User consent tracking';

------------------------------------------------------------------------------------------------
-- Table: T541 - data_subject_requests
-- Description: Tracks GDPR Data Subject Requests (DSAR).
-- Business Case: Users have rights (Access, Delete, Portability). This table logs these
-- requests for M12 data (Validation Logs). Links to T083 for decryption keys
-- to fulfill access rights.
-- KPIs: DSAR response time.
-- Feature Reference: GDPR
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.data_subject_requests (
    -- Primary Key
    request_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- User
    user_id UUID, -- Anonymous identifier
    contact_email TEXT NOT NULL,

    -- Request
    request_type VARCHAR(20) NOT NULL, -- ACCESS, DELETE, PORTABILITY
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING', -- PENDING, IN_PROGRESS, COMPLETED

    -- Processing
    assigned_to UUID REFERENCES core.system_users(user_id),
    due_date DATE,
    completed_at TIMESTAMP WITH TIME ZONE,

    -- Result
    result_package_url TEXT, -- Link to exported data
    denial_reason TEXT
);

COMMENT ON TABLE core.data_subject_requests IS 'GDPR Data Subject Request tracking';

------------------------------------------------------------------------------------------------
-- Table: T542 - right_to_be_forgotten
-- Description: Specific logs of deletion requests (T541).
-- Business Case: Ensures that when a user requests erasure (RTBF), it is thoroughly executed.
-- Logs scrubbed tables (T005, T456) and any remnants. Proves compliance to
-- regulators.
-- KPIs: Erasure completeness.
-- Feature Reference: GDPR
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.right_to_be_forgotten (
    -- Primary Key
    erasure_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    dsar_id UUID NOT NULL REFERENCES core.data_subject_requests(request_id),

    -- Execution
    tables_affected TEXT[] NOT NULL, -- List of tables where rows were deleted
    rows_deleted BIGINT NOT NULL,

    -- Verification
    verification_query TEXT, -- Query to prove data is gone
    verified_by UUID REFERENCES core.system_users(user_id),
    verified_at TIMESTAMP WITH TIME ZONE
);

COMMENT ON TABLE core.right_to_be_forgotten IS 'Execution log for Right to be Forgotten';

------------------------------------------------------------------------------------------------
-- Table: T543 - data_portability
-- Description: Stores links to exported data packages (T541).
-- Business Case: When a user requests data portability, M12 exports their data (Validations,
-- Config). This table links to the secure package location and records the
-- format provided (JSON, CSV).
-- KPIs: Data export accuracy.
-- Feature Reference: GDPR
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.data_portability (
    -- Primary Key
    export_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    dsar_id UUID NOT NULL REFERENCES core.data_subject_requests(request_id),

    -- Data
    file_format VARCHAR(20) NOT NULL, -- JSON, CSV, XML
    file_path TEXT NOT NULL, -- Encrypted S3 path

    -- Metadata
    record_count BIGINT,
    export_size_bytes BIGINT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.data_portability IS 'Data portability export records';

------------------------------------------------------------------------------------------------
-- Table: T544 - cookie_consent
-- Description: Stores user cookie consent preferences.
-- Business Case: Maps user IDs (or device fingerprints) to their consent for cookies (Required,
-- Analytics). Allows M12 web clients to respect user privacy choices (T540).
-- KPIs: Cookie compliance.
-- Feature Reference: GDPR
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.cookie_consent (
    -- Primary Key
    consent_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- User
    user_fingerprint CHAR(64) NOT NULL, -- Hashed device/browser ID
    tenant_id UUID REFERENCES core.tenants(tenant_id),

    -- Preferences (JSONB for flexibility)
    preferences JSONB NOT NULL, -- {"necessary": true, "marketing": false}

    -- Metadata
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.cookie_consent IS 'Cookie consent preferences';

------------------------------------------------------------------------------------------------
-- Table: T545 - marketing_preferences
-- Description: Stores opt-in/out preferences for comms (Email, SMS).
-- Business Case: Controls whether users receive operational vs. marketing messages.
-- Essential for legal compliance (CAN-SPAM, GDPR).
-- KPIs: Marketing opt-out rate.
-- Feature Reference: Marketing
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.marketing_preferences (
    -- Primary Key
    pref_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- User
    user_id UUID REFERENCES core.system_users(user_id), -- Or email key

    -- Channels
    email_marketing BOOLEAN DEFAULT FALSE,
    sms_marketing BOOLEAN DEFAULT FALSE,
    push_marketing BOOLEAN DEFAULT FALSE,

    -- State
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_source VARCHAR(50) -- USER, ADMIN
);

COMMENT ON TABLE core.marketing_preferences IS 'Marketing communication preferences';

------------------------------------------------------------------------------------------------
-- Table: T546 - communication_logs
-- Description: Audit of outbound communications (Email, SMS).
-- Business Case: T462 tracks delivery, but this tracks *content* and context. Logs exactly
-- what was sent to whom (masked PII). Critical for debugging and legal
-- defensibility if a user claims they didn't get a notification.
-- KPIs: Communication content auditability.
-- Feature Reference: Operations
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.communication_logs (
    -- Primary Key
    log_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Message
    template_id UUID REFERENCES core.notification_templates(template_id),
    channel VARCHAR(20) NOT NULL,
    recipient_masked TEXT NOT NULL, -- 'j***@email.com'

    -- Context
    correlation_id UUID, -- Link to event
    error_code VARCHAR(50), -- If failed

    -- State
    sent_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE core.communication_logs IS 'Audit log of outbound messages';

------------------------------------------------------------------------------------------------
-- Table: T547 - sms_optouts
-- Description: Registry of users who opted out of SMS.
-- Business Case: "STOP" command handling. Users texting "STOP" are added here. The validation
-- engine checks this list before attempting SMS delivery (T072), saving costs and
-- preventing legal issues.
-- KPIs: SMS opt-out rate.
-- Feature Reference: T010
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.sms_optouts (
    -- Primary Key
    optout_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Identity
    phone_number VARCHAR(20) NOT NULL, -- E.164 format
    tenant_id UUID REFERENCES core.tenants(tenant_id),

    -- State
    opted_out_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_sms_optouts_phone ON core.sms_optouts(phone_number);
COMMENT ON TABLE core.sms_optouts IS 'Registry of SMS opt-outs';

------------------------------------------------------------------------------------------------
-- Table: T548 - email_bounces
-- Description: Logs of bounced emails.
-- Business Case: Tracks hard bounces and soft bounces. If an address bounces repeatedly, it is added
-- to T011 (Blacklist). M12 uses this to keep T005 (Logs) clean by not
-- attempting to verify emails that don't exist.
-- KPIs: Email bounce rate.
-- Feature Reference: T005
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.email_bounces (
    -- Primary Key
    bounce_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Email
    email_address VARCHAR(255) NOT NULL,

    -- Bounce Info
    bounce_type VARCHAR(20) NOT NULL, -- HARD, SOFT
    bounce_reason TEXT,
    smtp_code VARCHAR(10),

    -- State
    bounced_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_email_bounces_address ON core.email_bounces(email_address);
COMMENT ON TABLE core.email_bounces IS 'Log of bounced emails';

------------------------------------------------------------------------------------------------
-- Table: T549 - suppression_lists
-- Description: Global suppression lists for emails/phones (M003).
-- Business Case: Contains emails/phones that have complained, litigated, or opted out
-- globally. M12 checks this list during validation (F005) to prevent sending
-- emails to these high-risk contacts.
-- KPIs: Complaint reduction.
-- Feature Reference: M003
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.suppression_lists (
    -- Primary Key
    suppression_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Contact
    contact_value VARCHAR(255) NOT NULL,
    contact_type VARCHAR(20) NOT NULL, -- EMAIL, PHONE

    -- Reason
    reason_code VARCHAR(50) NOT NULL, -- COMPLAINT, LITIGATION, OPTOUT
    source VARCHAR(50), -- 'FEEDBACK_LOOP', 'LEGAL'

    -- State
    is_active BOOLEAN DEFAULT true,
    added_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_suppression_val ON core.suppression_lists(contact_value);
COMMENT ON TABLE core.suppression_lists IS 'Global suppression lists';

------------------------------------------------------------------------------------------------
-- Table: T550 - blacklist_check
-- Description: Results of checking inputs against blacklists (T011, T549, T548).
-- Business Case: Logs whenever a validation checks a blacklist (Email, IP, Device).
-- Tracks which blacklist was hit and why. Useful for measuring the effectiveness
-- of the blacklists (how much bad traffic are they blocking?).
-- KPIs: Blacklist hit rate.
-- Feature Reference: T011, T548
------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.blacklist_check (
    -- Primary Key
    check_id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,

    -- Context
    resource_type VARCHAR(20) NOT NULL, -- IP, EMAIL, DOMAIN
    resource_value TEXT NOT NULL,
    blacklist_name VARCHAR(50) NOT NULL, -- 'EMAIL_BOUNCES', 'ABUSEIP'

    -- Event
    matched_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,

    -- Source
    api_endpoint VARCHAR(255),
    user_agent TEXT
);

CREATE INDEX idx_blacklist_type ON core.blacklist_check(resource_type, matched_at DESC);
COMMENT ON TABLE core.blacklist_check IS 'Logs of blacklist matches';

-- ================================================================================================
-- 5. ENTITY RELATIONSHIPS AND CONSTRAINTS (Foreign Keys - Part 8)
-- ================================================================================================

-- Many FKs are defined inline or references existing tables.
-- T454 -> T452, T453
ALTER TABLE core.user_role_assignments
    ADD CONSTRAINT fk_user_role_user FOREIGN KEY (user_id) REFERENCES core.system_users(user_id) ON DELETE CASCADE,
    ADD CONSTRAINT fk_user_role_role FOREIGN KEY (role_id) REFERENCES core.system_roles(role_id) ON DELETE CASCADE;

-- T455 -> T452, T453
ALTER TABLE core.role_permission_grants
    ADD CONSTRAINT fk_role_perm_role FOREIGN KEY (role_id) REFERENCES core.system_roles(role_id) ON DELETE CASCADE,
    ADD CONSTRAINT fk_role_perm_perm FOREIGN KEY (permission_id) REFERENCES core.system_permissions(permission_id) ON DELETE CASCADE;

-- ================================================================================================
-- 6. TRIGGERS FOR AUDIT COLUMNS (Part 8)
-- ================================================================================================

-- Apply trigger_update_updated_at to Part 8 tables
DO $$ DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT table_name
             FROM information_schema.tables
             WHERE table_schema = 'core'
             AND table_name IN (
                 'system_users', 'system_roles', 'system_permissions',
                 'notification_templates', 'service_dependencies',
                 'load_balancer_rules', 'shard_mapping_history',
                 'api_spec_versions', 'kafka_config',
                 'compliance_certificates', 'disaster_recovery_plans',
                 'resource_quotas', 'security_policies'
             )
    LOOP
        EXECUTE format('CREATE TRIGGER trigger_update_%s BEFORE UPDATE ON core.%I FOR EACH ROW EXECUTE FUNCTION core.trigger_update_updated_at()', r.table_name, r.table_name);
    END LOOP;
END$$;

